CREATE DEFINER=`root`@`localhost` PROCEDURE `Delete_Campaign`(
    IN campaign_details_id_ INT
)
BEGIN
    DECLARE affected_rows INT;
    
    UPDATE campaign_details 
    SET Delete_Status = 1 
    WHERE campaign_details_id = campaign_details_id_;
    
    SET affected_rows = ROW_COUNT();
    
    IF affected_rows > 0 THEN
        SELECT campaign_details_id_ AS campaign_Id_;
    ELSE
        SELECT -1 AS campaign_Id_;
    END IF;
END$$
