CREATE DEFINER=`root`@`localhost` PROCEDURE `Delete_Department_Status`( In Department_Status_Id_ Int)
Begin 
 if exists(select student.Status_Id  from student where DeleteStatus=False and Status_Id = Department_Status_Id_ ) or
 (select department.Department_Status_Id  from department where Is_Delete=False and Department_Status_Id = Department_Status_Id_ ) or
  (select Status_Selection.Status_Id  from Status_Selection where Is_Delete=False and Status_Id = Department_Status_Id_ )
    then
        set Department_Status_Id_=-2;
else
	update Department_Status set Is_Delete=true where Department_Status_Id =Department_Status_Id_ ;
	delete from Status_Selection where Status_Id=Department_Status_Id_;
end if;
 select Department_Status_Id_;
 End$$
DELIMITER ;

