/*if User_Type_=2 then
  SET SearchbyName_Value =concat(SearchbyName_Value," and student.Registered_By =",Login_User_Id_);
    else
    SET SearchbyName_Value =concat(SearchbyName_Value," and student.Registered_By in (select User_Details_Id from user_details where Branch_Id in (select
distinct Branch_Id from user_department where User_Id =",Login_User_Id_," and VIew_All=1))");
end if;*/
if Department_>0 then
SET SearchbyName_Value =concat(SearchbyName_Value," and student.Followup_Department_Id =",Department_);
end if;
if Branch_>0 then
SET SearchbyName_Value =concat(SearchbyName_Value," and  student.Followup_Branch_Id =",Branch_);
end if;
if User_Id_>0 then
SET SearchbyName_Value =concat(SearchbyName_Value," and student.To_User_Id =",User_Id_);
end if;
if Enquiry_Source_>0 then
SET SearchbyName_Value =concat(SearchbyName_Value," and student.Enquiry_Source_Id  =",Enquiry_Source_);
end if;
if Country_Id_>0 then
SET SearchbyName_Value =concat(SearchbyName_Value," and student.Profile_Country_Id =",Country_Id_);
end if;


if Status_Id_Temp_>0 then
SET SearchbyName_Value =concat(SearchbyName_Value," and student.Status_Id =",Status_Id_Temp_);
end if;


if Is_Date_Check_=true then
set Search_Date_=concat( SearchbyName_Value," and date(student.Entry_date) >= '", Fromdate_ ,"' and  date(student.Entry_date) <= '", Todate_,"'");
ELSE
set Search_Date_= "and 1 =1 ";
end if;

if User_Type_ =2 then
    SET Search_by_type_ =concat(Search_by_type_," or student.User_List like '%*",Login_User_Id_,"*%'");
    #set Department_String_='';
end if;


set UnionQuery="";
SET @query = Concat( "select * from (select * from(select CAST(CAST(1 AS UNSIGNED) AS SIGNED)as tp,
(Date_Format(student.Registered_On,'%d-%m-%Y-%h:%i')) As Registered_On ,student.Student_Name Student,
student.Phone_Number Mobile, (Date_Format(student.Next_FollowUp_Date,'%d-%m-%Y')) As Follow_Up_On,Followup_Department_Name Department,
Department_Status_Name Status,To_User_Name To_Staff,student.To_User_Name As Created_By,
(Date_Format(student.Entry_Date,'%d-%m-%Y   %h:%i')) As Created_On,student.Remark,Enquiry_Source_Name as Enquiry_Source,student.Student_Id
from student 
where student.DeleteStatus=0     ",SearchbyName_Value," ",Search_Date_," ",Department_String_,"
and (student.Role_Id in(",RoleId_,")  ",Search_by_type_,") )as lds )as ldtwo
order by tp ");

PREPARE QUERY FROM @query;
#select @query;inner join Branch on Branch.Branch_Id= student.Branch
#insert into data_log_ value(0,@query,'enquiry report');
EXECUTE QUERY;
END$$
