CREATE DEFINER=`root`@`localhost` PROCEDURE `Get_All_Email_Templates`(IN p_name VARCHAR(255))
BEGIN
    SELECT 
        et.id, 
        et.name, 
        et.subject, 
        et.body, 
        et.brevo_template_id,
        et.created_by, 
        et.updated_by, 
        et.created_at, 
        et.document_id, 
        et.document_name, 
        et.updated_at, 
        et.status,
        COALESCE(
            JSON_ARRAYAGG(
                JSON_OBJECT(
                    'name', eta.file_name,
                    'path', eta.file_path
                )
            ),
            JSON_ARRAY()
        ) AS attachments
    FROM email_templates et
    LEFT JOIN email_template_attachments eta ON eta.template_id = et.id AND eta.delete_status = 0
    WHERE et.Delete_Status = 0
      AND (p_name = '' OR et.name LIKE CONCAT('%', p_name, '%'))
    GROUP BY et.id;
END$$
DELIMITER ;

