CREATE DEFINER=`root`@`localhost` PROCEDURE `Get_Brand_By_Department`(
    IN Department_Id_ INT,Brand_Name_ VARCHAR(250)
)
BEGIN
set Brand_Name_ = Concat( '%',Brand_Name_ ,'%');
    SELECT
        Brand_Id,
        Brand_Name,
        Default_Department_Id
    FROM Brand
    WHERE Is_Delete = FALSE
      AND Default_Department_Id = Department_Id_
        AND Brand_Name LIKE Brand_Name_
    ORDER BY IFNULL(Brand_Order, 0);
END$$
