CREATE DEFINER=`root`@`localhost` PROCEDURE `get_campaigne_department_details`(IN campaign_details_id_ INT)
BEGIN
    SELECT 
        c.Department_Id, 
        c.Department_Name, 
        u.user_id AS To_User_Id, 
        u.user_name AS To_User_Name, 
        c.Department_Status_Id AS Status_Id, 
        c.Department_Status_Name AS Status_Name 
    FROM campaign_details c
    INNER JOIN campaign_users u ON c.campaign_details_id = u.campaign_details_id
    WHERE c.campaign_details_id = campaign_details_id_
    ORDER BY u.sort_order ASC;
END$$
