CREATE DEFINER=`root`@`localhost` PROCEDURE `Get_Chats`(In Channel_Id_ int,Login_User_ int)
BEGIN
select From_User_Name,From_User,Chats,(Date_Format(Entry_Date,'%d-%m-%Y   %h:%i')) As Date,User_List as Tagged_Users_List,ifnull(File_Name,'') File_Name,ifnull(Display_File,'') Display_File,Channel_Id
from chats where Channel_Id = Channel_Id_ order by Chat_Id desc limit 10;
update channel_sub set Msg_Count = 0 ,ReadStatus = 1 where Channel_Id = Channel_Id_ and User_Id = Login_User_  and DeleteStatus=0;

select User_Id from channel_sub where Channel_Id=Channel_Id_;
select Channel_Id,Channel_Name,Channel_Type,User_Name from channel where Channel_Id = Channel_Id_ and DeleteStatus = 0;
END$$
