CREATE DEFINER=`root`@`localhost` PROCEDURE `Get_Dashboard_Account_Count`(In RoleId_ varchar(100),Department_String_ varchar(4000),Login_User_Id_ int,Fromdate_ date,Todate_ date,
Date_Value_ int,User_Id_ int,Dept_Id_ int,Branch_Id_ int,Department_Status_Id_ int,Country_Ids_ longtext,Intake_Ids_ longtext,Intake_Year_Ids_ longtext)
BEGIN
#declare Fromdate_ date;declare Todate_ date;
declare Department_String_To_User_ varchar(4000);declare Department_String_Registered_By varchar(4000);
declare Search_Date_ varchar(200);declare User_Type_ int;declare curday int;declare Department_String_Reg_ varchar(4000);declare SearchbyName_Value varchar(2000);declare SearchbyName_Value_Register varchar(2000);declare SearchbyName_Value_Followup_ varchar(2000);
declare SearchbyName_Value_Application varchar(2000);
declare SearchbyName_Value_FollowUp varchar(2000);declare SearchbyName_Value_Task varchar(2000); DECLARE Search_Date_Registered_ VARCHAR(200);
DECLARE Search_Date_FollowUp VARCHAR(200);DECLARE Search_Date_Fees_ VARCHAR(200);DECLARE Search_Date_Application_ VARCHAR(200);DECLARE Search_Date_Task_ VARCHAR(200);DECLARE Search_Date_Commission_ VARCHAR(200);DECLARE Search_by_type_ VARCHAR(200);
if Date_Value_=0 then
set Fromdate_=now();
set Todate_=now();
set curday=(SELECT DAY(Fromdate_)-1);
#set Fromdate_=(SELECT DATE_SUB(Fromdate_, INTERVAL curday DAY));
end if;

set SearchbyName_Value ='';set SearchbyName_Value_FollowUp ='';set SearchbyName_Value_Task ='';set Search_by_type_ ='';set SearchbyName_Value_Register ='';set SearchbyName_Value_Application='';
set Search_Date_Registered_ ='';set Search_Date_FollowUp ='';set Search_Date_Fees_ ='';set Search_Date_Application_ = '';set Search_Date_Task_ ='';set Search_Date_Commission_ ='';
set Search_Date_='';set Department_String_Reg_ ='';set Department_String_='';set SearchbyName_Value_Followup_ ='';
set User_Type_=(select User_Type from user_details where User_Details_Id=Login_User_Id_);
set Department_String_Reg_ = (select Department_String from user_details where User_Details_Id = Login_User_Id_);
if User_Id_ >0 then
SET SearchbyName_Value =concat(SearchbyName_Value," and student.To_User_Id =",User_Id_);
    SET SearchbyName_Value_FollowUp =concat(SearchbyName_Value_FollowUp," and student_followup.User_Id =",User_Id_);
    SET SearchbyName_Value_Task =concat(SearchbyName_Value_Task," and Student_Task.To_User =",User_Id_);
    SET SearchbyName_Value_Register =concat(SearchbyName_Value_Register," and student.Registered_By =",User_Id_);
    SET SearchbyName_Value_Application =concat(SearchbyName_Value_Application," and application_details.To_User_Id =",User_Id_);
end if;
if Dept_Id_ >0 then
SET SearchbyName_Value =concat(SearchbyName_Value," and student.Followup_Department_Id =",Dept_Id_);
    SET SearchbyName_Value_FollowUp =concat(SearchbyName_Value_FollowUp," and student_followup.Department =",Dept_Id_);
    SET SearchbyName_Value_Task =concat(SearchbyName_Value_Task," and Student_Task.Department_Id =",Dept_Id_);
    SET SearchbyName_Value_Register =concat(SearchbyName_Value_Register," and student.Followup_Department_Id =",Dept_Id_);
    SET SearchbyName_Value_Application =concat(SearchbyName_Value_Application," and student.Followup_Department_Id =",Dept_Id_);
end if;
if Branch_Id_ >0 then
SET SearchbyName_Value =concat(SearchbyName_Value," and student.Followup_Branch_Id =",Branch_Id_);
    SET SearchbyName_Value_FollowUp =concat(SearchbyName_Value_FollowUp," and student_followup.Branch =",Branch_Id_);
    SET SearchbyName_Value_Task =concat(SearchbyName_Value_Task," and Student_Task.Branch_Id =",Branch_Id_);
    SET SearchbyName_Value_Register =concat(SearchbyName_Value_Register," and student.Followup_Branch_Id =",Branch_Id_);
    SET SearchbyName_Value_Application =concat(SearchbyName_Value_Application," and student.Followup_Branch_Id =",Branch_Id_);
end if;
if Department_Status_Id_ >0 then
SET SearchbyName_Value =concat(SearchbyName_Value," and student.Status_Id =",Department_Status_Id_);
    SET SearchbyName_Value_FollowUp =concat(SearchbyName_Value_FollowUp," and student_followup.Status =",Department_Status_Id_);

end if;

 if Country_Ids_ IS NOT NULL AND Country_Ids_ != '0' then
    SET SearchbyName_Value = CONCAT(SearchbyName_Value, " AND application_details.Country_Id IN (", Country_Ids_, ")");
end if;

 if Intake_Ids_ IS NOT NULL AND Intake_Ids_ != '0' then
    SET SearchbyName_Value = CONCAT(SearchbyName_Value, " AND application_details.intake_Id IN (", Intake_Ids_, ")");
end if;

 if Intake_Year_Ids_ IS NOT NULL AND Intake_Year_Ids_ != '0' then
    SET SearchbyName_Value = CONCAT(SearchbyName_Value, " AND application_details.Intake_Year_Id IN (", Intake_Year_Ids_, ")");
end if;

/*if Is_Date_Check_=true then
if Date_value_=2 then
set Search_Date_=concat( SearchbyName_Value," and date(student.Entry_date) >= '", Fromdate_ ,"' and  date(student.Entry_date) <= '", Todate_,"'");
elseif Date_value_=1 then
set Search_Date_=concat( SearchbyName_Value," and date(student.Next_FollowUp_date) >= '", Fromdate_ ,"' and  date(student.Next_FollowUp_date) <= '", Todate_,"'");
end if;
ELSE
set Search_Date_= "and 1 =1 ";
end if;*/
#set Search_Date_=concat( " and date(student.Entry_Date) >=  '", Fromdate_ ,"' and  date(student.Entry_Date) <= '", Todate_,"'");
   if Date_Value_>0 then
SET Search_Date_ = CONCAT(" AND DATE(student.Entry_Date) >= '", Fromdate_, "' AND DATE(student.Entry_Date) <= '", Todate_, "'");
set Search_Date_Registered_=concat( " and date(student.Registered_On) >=  '", Fromdate_ ,"' and  date(student.Registered_On) <= '", Todate_,"'");
SET Search_Date_FollowUp = concat( " and date(student.Next_FollowUp_Date) < '", Date_Format( Now(),'%Y-%m-%d'),"'" );
set Search_Date_Fees_=concat( " and date(Fees_Receipt.Entry_Date) >=  '", Fromdate_ ,"' and  date(Fees_Receipt.Entry_Date) <= '", Todate_,"'");
set Search_Date_Commission_=concat( " and date(commission_receipt.Entry_Date) >=  '", Fromdate_ ,"' and  date(commission_receipt.Entry_Date) <= '", Todate_,"'");
set Search_Date_Application_=concat( " and date(application_details.Date_Of_Applying) >=  '", Fromdate_ ,"' and  date(application_details.Date_Of_Applying) <= '", Todate_,"'");
set Search_Date_Task_=concat( " and date(Student_Task.Followup_Date) >=  '", Fromdate_ ,"' and date(Student_Task.Followup_Date) <= '", Todate_,"'");




     ELSE
set Search_Date_= "and 1 =1 ";
    set Search_Date_Registered_ = "and 1 =1 ";
    set Search_Date_FollowUp = concat( " and date(student.Next_FollowUp_Date) < '", Date_Format( Now(),'%Y-%m-%d'),"'" );
    set Search_Date_Fees_ = "and 1 =1 ";
    set Search_Date_Commission_ = "and 1 =1 ";
    set Search_Date_Application_=  "and 1 =1 ";
    set Search_Date_Task_ = "and 1 =1 ";
end if;


if User_Type_=2 then
SET Department_String_ =concat(Department_String_Reg_," and student.To_User_Id =",Login_User_Id_);
        SET Department_String_Registered_By =concat(" and student.Registered_By =",Login_User_Id_);
else
SET Department_String_ =concat(Department_String_Reg_," and student.To_User_Id in (select User_Details_Id from user_details where Branch_Id in (select
distinct Branch_Id from user_department where User_Id =",Login_User_Id_," and VIew_All=1))");
SET Department_String_Registered_By =concat(" and student.Registered_By in (select User_Details_Id from user_details where Branch_Id in (select
distinct Branch_Id from user_department where User_Id =",Login_User_Id_," and VIew_All=1))");
end if;

set Department_String_To_User_ =REPLACE(Department_String_Reg_,'By_User_Id','To_User_Id');
 



if User_Type_ =2 then

    SET Search_by_type_ =concat(Search_by_type_," or student.User_List like '%*",Login_User_Id_,"*%'");    
    SET SearchbyName_Value_Register =concat(SearchbyName_Value_Register," and student.Registered_By =",Login_User_Id_);
   
    SET SearchbyName_Value_Followup_ =concat(SearchbyName_Value_Followup_," and student.To_User_Id =",Login_User_Id_);
   
    #set Department_String_To_User_='';
end if;

#set Department_String_Registered_By =REPLACE(Department_String,'By_User_Id','Registered_By');
#insert into data_log_ values(0,Department_String_Reg_,'');
SET @query = Concat( "
/*  
select 1 as tp,'',count(student.Student_Id) as Data_Count from student
inner join Department on Department.Department_Id= student.Followup_Department_Id  ",Department_String_To_User_," ",SearchbyName_Value,"
#inner join user_details on user_details.User_Details_Id=student.To_User_Id
where student.DeleteStatus=0     ", Search_Date_ ,"
and (student.Role_Id in(",RoleId_,")  ",Search_by_type_,")
*/
#All Applications
select 1 as tp,'',count(application_details.Application_details_Id) as Data_Count from application_details 
where application_details.DeleteStatus=0  ",SearchbyName_Value,"  ", Search_Date_Application_ ,"

   union
#offer
   
select 2 as tp,'',count(application_details.Application_details_Id) as Data_Count from application_details 
where application_details.DeleteStatus=0 and  Application_status_Id=2  ",SearchbyName_Value," ", Search_Date_Application_ ,"
union
#payments
select 3 as tp,'',
    COALESCE(SUM(fees_receipt.Amount), 0) AS Data_Count 
FROM student
INNER JOIN user_details AS T ON T.User_Details_Id = student.To_User_Id 
INNER JOIN Fees_Receipt ON Fees_Receipt.Student_Id = student.Student_Id
INNER JOIN Fees_Receipt_Status ON Fees_Receipt_Status.Fees_Receipt_Status_Id = Fees_Receipt.Fees_Receipt_Status
INNER JOIN Branch ON Branch.Branch_Id = Fees_Receipt.Fee_Receipt_Branch 
INNER JOIN Fees ON Fees.Fees_Id = Fees_Receipt.Fees_Id 
inner join application_details on application_details.Student_Id = fees_receipt.Student_Id
#LEFT JOIN application_details ON application_details.Application_details_Id = Fees_Receipt.Application_details_Id
WHERE 
    student.DeleteStatus = 0 
    AND fees_receipt.Delete_Status = 0  
    AND fees_receipt.Fees_Receipt_Status = 2   ", Search_Date_Fees_ ,"  ",SearchbyName_Value,"
#select 3 as tp,'',COALESCE(SUM(fees_receipt.Amount), 0) AS Data_Count  from fees_receipt 
#inner join application_details on application_details.Student_Id = fees_receipt.Student_Id
#where fees_receipt.Delete_Status=0  ",SearchbyName_Value," ", Search_Date_Application_ ,"

union
#visa rejected
SELECT 
    4 AS tp, 
    '', 
    COUNT(student.Student_Id) AS Data_Count 
FROM student
INNER JOIN user_details AS T ON T.User_Details_Id = student.To_User_Id 
INNER JOIN Fees_Receipt ON Fees_Receipt.Student_Id = student.Student_Id
INNER JOIN Fees_Receipt_Status ON Fees_Receipt_Status.Fees_Receipt_Status_Id = Fees_Receipt.Fees_Receipt_Status
INNER JOIN Branch ON Branch.Branch_Id = Fees_Receipt.Fee_Receipt_Branch 
INNER JOIN Fees ON Fees.Fees_Id = Fees_Receipt.Fees_Id 
LEFT JOIN application_details ON application_details.Application_details_Id = Fees_Receipt.Application_details_Id
WHERE 
    student.DeleteStatus = 0 
    AND fees_receipt.Delete_Status = 0  
    AND fees_receipt.Fees_Receipt_Status = 2  
    AND student.Is_Registered = 0   ", Search_Date_ ,"  ",SearchbyName_Value,"
  

#select 4 as tp,'',count(student.Student_Id) as Data_Count from student 
#where student.DeleteStatus=0 and student.Is_Registered=0 ",SearchbyName_Value," ", Search_Date_Application_ ,"

union
#visa received
select 5 as tp,'',count(application_details.Application_details_Id) as Data_Count from application_details 
where application_details.DeleteStatus=0 and  Application_status_Id=3   ",SearchbyName_Value," ", Search_Date_Application_ ," 

union

#Non Enrolments (pending)

select 6 as tp,'',COALESCE(sum(commission_receipt.Amount),0) as Data_Count from student
inner join Department on Department.Department_Id= student.Followup_Department_Id  ",Department_String_To_User_,"
inner join commission_receipt on commission_receipt.Student_Id=student.Student_Id
inner join user_details on user_details.User_Details_Id=commission_receipt.User_Id
inner join Branch on Branch.Branch_Id= commission_receipt.Fee_Receipt_Branch
where student.DeleteStatus=0  ", Search_Date_Commission_ ,"
and user_details.Role_Id in(",RoleId_,")


 union
SELECT 
    7 AS tp, 
    '' ,
    COALESCE(SUM(fees_receipt.Amount), 0) - COALESCE(SUM(commission_receipt.Amount), 0) AS Pending_Commission
FROM student
INNER JOIN Department ON Department.Department_Id = student.Followup_Department_Id  
INNER JOIN commission_receipt ON commission_receipt.Student_Id = student.Student_Id
INNER JOIN user_details ON user_details.User_Details_Id = commission_receipt.User_Id
INNER JOIN Branch ON Branch.Branch_Id = commission_receipt.Fee_Receipt_Branch
INNER JOIN fees_receipt ON fees_receipt.Student_Id = student.Student_Id 
    AND fees_receipt.Delete_Status = 0
WHERE 
    student.DeleteStatus = 0   
    AND commission_receipt.Delete_Status = 0 
   ", Search_Date_Commission_ ,"
and user_details.Role_Id in(",RoleId_,")

 union
select 9 as tp,'',COALESCE(count(student.Student_Id)) as Data_Count from student
where student.DeleteStatus=0  ",Search_Date_FollowUp,"  and student.Role_Id in(",RoleId_,")


 union
#Deferrals 
select 10 as tp,'',count(application_details.Application_details_Id) as Data_Count from application_details 
where application_details.DeleteStatus=0 and  Application_status_Id=5 ",SearchbyName_Value," ", Search_Date_Application_ ,"


 order by tp
 ");
PREPARE QUERY FROM @query;
#select @query;

insert into data_log_ value(0,@query,'query');
EXECUTE QUERY;
END$$
DELIMITER ;

DELIMITER $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `Get_Dashboard_Count`(In RoleId_ varchar(100),Department_String_ varchar(4000),Login_User_Id_ int,Fromdate_ date,Todate_ date,
Date_Value_ int,User_Id_ int,User_Type_ int)
BEGIN
declare Department_String_To_User_ varchar(4000);declare Department_String_Registered_By varchar(4000);
declare Search_Date_ varchar(200);declare User_Type_ int;declare curday int;declare Department_String_Reg_ varchar(4000);
declare SearchbyName_Value varchar(2000);declare SearchbyName_Value_FollowUp varchar(2000);declare SearchbyName_Value_Task varchar(2000);declare SearchbyName_Value_Register varchar(2000);
declare SearchbyName_Value_receipt varchar(2000);
declare Search_Date_Application_ varchar(200); declare Search_Date_Student_ varchar(200); declare Search_Date_Student_Reg_ varchar(200);
declare Search_Date_Next_Followup_ varchar(200); declare Search_Date_Fees_Receipt_ varchar(200);declare Search_Date_Student_Task_ varchar(200);
set SearchbyName_Value='';set SearchbyName_Value_FollowUp ='';set SearchbyName_Value_Task ='';set SearchbyName_Value_Register='';set SearchbyName_Value_receipt='';
if Date_Value_=0 then
set Search_Date_Application_ =" and 1=1 ";
set Search_Date_Student_ = " and 1=1";
set Search_Date_Student_Reg_ = " and 1=1";
set Search_Date_Next_Followup_ = concat( " and date(student.Next_FollowUp_Date) < '", Date_Format( Now(),'%Y-%m-%d'),"'" );
set Search_Date_Fees_Receipt_ = " and 1=1";
set Search_Date_Student_Task_ =" and 1=1";
set Fromdate_=now();
set Todate_=now();
set curday=(SELECT DAY(Fromdate_)-1);
set Fromdate_=(SELECT DATE_SUB(Fromdate_, INTERVAL curday DAY));
else
set Search_Date_Application_ =concat(" and date(application_details.Date_Of_Applying) >= '", Fromdate_ ,"' and  date(application_details.Date_Of_Applying) <= '", Todate_,"'");
set Search_Date_Student_ =concat( " and date(student.Entry_Date) >= '", Fromdate_ ,"' and  date(student.Entry_Date) <= '", Todate_,"'");
set Search_Date_Student_Reg_ =concat( " and date(student.Registered_On) >= '", Fromdate_ ,"' and  date(student.Registered_On) <= '", Todate_,"'");
set Search_Date_Next_Followup_ =concat( " and date(student.Next_FollowUp_Date) < '", Date_Format( Now(),'%Y-%m-%d'),"'" );
set Search_Date_Fees_Receipt_ = concat(" and date(Fees_Receipt.Entry_Date) >= '", Fromdate_ ,"' and  date(Fees_Receipt.Entry_Date) <= '", Todate_,"'");
set Search_Date_Student_Task_ =concat(" and date(Student_Task.Followup_date) >= '", Fromdate_ ,"' and  date(Student_Task.Followup_date) <= '", Todate_,"'");
end if;

#set Fromdate_=now();
#set Todate_=now();
#set curday=(SELECT DAY(Fromdate_)-1);
#set Fromdate_=(SELECT DATE_SUB(Fromdate_, INTERVAL curday DAY));
set Search_Date_='';set Department_String_Reg_ ='';set Department_String_='';
set User_Type_=(select User_Type from user_details where User_Details_Id=Login_User_Id_);
set Department_String_Reg_ = (select Department_String from user_details where User_Details_Id = Login_User_Id_);
set Search_Date_=concat( " and date(student.Entry_Date) >=  '", Fromdate_ ,"' and  date(student.Entry_Date) <= '", Todate_,"'");
if User_Id_ >0 then
	SET SearchbyName_Value =concat(SearchbyName_Value," and student.To_User_Id =",User_Id_);
    SET SearchbyName_Value_FollowUp =concat(SearchbyName_Value_FollowUp," and student_followup.User_Id =",User_Id_);
    SET SearchbyName_Value_Task =concat(SearchbyName_Value_Task," and Student_Task.To_User =",User_Id_);
    SET SearchbyName_Value_Register =concat(SearchbyName_Value_Register," and student.Registered_By =",User_Id_);
    SET SearchbyName_Value_receipt =concat(SearchbyName_Value_receipt," and fees_receipt.User_Id =",User_Id_);
end if;
	if User_Type_=2 then
		SET Department_String_ =concat(Department_String_Reg_," and student.To_User_Id =",Login_User_Id_);
        SET Department_String_Registered_By =concat(" and student.Registered_By =",Login_User_Id_);
	else
		SET Department_String_ =concat(Department_String_Reg_," and student.To_User_Id in (select User_Details_Id from user_details where Branch_Id in (select
		distinct Branch_Id from user_department where User_Id =",Login_User_Id_," and VIew_All=1))");
		SET Department_String_Registered_By =concat(" and student.Registered_By in (select User_Details_Id from user_details where Branch_Id in (select
		distinct Branch_Id from user_department where User_Id =",Login_User_Id_," and VIew_All=1))");
	end if;
set Department_String_To_User_ =REPLACE(Department_String_Reg_,'By_User_Id','To_User_Id');

If User_Type_=1 then

	Set SearchbyName_Value_Task = 
		concat(SearchbyName_Value_Task," and Student_Task.By_User_Id in 
								(
									select 
										distinct user_id 
									from 
										user_department 
									where 
										branch_id in
                                        (
											select 
												branch_Id 
											from 
												user_department 
											where user_id=",Login_User_Id_,"
                                            )
									)");
Else			
SET SearchbyName_Value_Task =concat(SearchbyName_Value_Task," and (To_User =",Login_User_Id_," or By_User_Id =",Login_User_Id_," ) ");

				
	
End If;    
#insert into data_log_ values(0,Department_String_Reg_,'');
SET @query = Concat( "  
select 1 as tp,count(student.Student_Id) as Data_Count from student
inner join Department on Department.Department_Id= student.Followup_Department_Id  ",Department_String_To_User_,"
#inner join user_details on user_details.User_Details_Id=student.To_User_Id
where student.DeleteStatus=0",Search_Date_Student_,"
and student.Role_Id in(",RoleId_,")  ",SearchbyName_Value,"
   union
select 2 as tp,count(student.Student_Id) as Data_Count from student
inner join Department on Department.Department_Id= student.Followup_Department_Id  ",Department_String_To_User_,"
inner join user_details on user_details.User_Details_Id=student.Registered_By
where student.DeleteStatus=0 and  student.Is_Registered=1",Search_Date_Student_Reg_,"
and student.Role_Id in(",RoleId_,")",SearchbyName_Value_Register,"
union
    select 3 as tp,count(student.Student_Id) as Data_Count from student
#inner join Department on Department.Department_Id= student.Followup_Department_Id  
#inner join user_details on user_details.User_Details_Id=student.To_User_Id
where student.DeleteStatus=0 and student.FollowUp=1  ",Department_String_To_User_,"",Search_Date_Next_Followup_,"
and student.Role_Id in(",RoleId_,") ",SearchbyName_Value,"
union
 select 4 as tp,COALESCE(sum(Fees_Receipt.Amount),0) as Data_Count from student
inner join Department on Department.Department_Id= student.Followup_Department_Id  ",Department_String_To_User_,"
inner join Fees_Receipt on Fees_Receipt.Student_Id=student.Student_Id
inner join user_details on user_details.User_Details_Id=Fees_Receipt.User_Id
inner join Branch on Branch.Branch_Id= fees_receipt.Fee_Receipt_Branch
where student.DeleteStatus=0 and fees_receipt.Delete_Status=0",Search_Date_Fees_Receipt_,"
and user_details.Role_Id in(",RoleId_,")",SearchbyName_Value_receipt,"
union
select 5 as tp,COALESCE(count(student.Student_Id)) as Data_Count from student
inner join Department on Department.Department_Id= student.Followup_Department_Id  ",Department_String_To_User_,"
inner join application_details on application_details.Student_Id=student.Student_Id
inner join user_details on user_details.User_Details_Id=application_details.User_Id
where student.DeleteStatus=0  and application_details.DeleteStatus=0   
",Search_Date_Application_,"
and user_details.Role_Id in(",RoleId_,")",SearchbyName_Value,"

union
select 6 as tp,COALESCE(count(Student_Task.Student_Task_Id)) as Data_Count from Student_Task
where Student_Task.DeleteStatus=0 and Task_Status=1",Search_Date_Student_Task_,"",SearchbyName_Value_Task,"




 union
select 7 as tp,COALESCE(count(student_followup.Status_Type_Id)) as Data_Count from student_followup
where student_followup.DeleteStatus=0 and  Department=372 and Status_Type_Id=1 and student_followup.User_Id=",User_Id_,"  


 union
select 8 as tp,COALESCE(count(student_followup.Status_Type_Id)) as Data_Count from student_followup
where student_followup.DeleteStatus=0  and Department=372 and Status_Type_Id=2 and student_followup.User_Id=",User_Id_," 

union
select 9 as tp,COALESCE(count(Student_Task.Student_Task_Id)) as Data_Count from Student_Task
where Student_Task.DeleteStatus=0 and Task_Status=2",Search_Date_Student_Task_,"
",SearchbyName_Value_Task,"


union
select 10 as tp,COALESCE(count(Student_Task.Student_Task_Id)) as Data_Count from Student_Task
where Student_Task.DeleteStatus=0 and Task_Status=1",Search_Date_Student_Task_,"
",SearchbyName_Value_Task,"

union
select 11 as tp,COALESCE(count(application_tab_status.Student_Id)) as Data_Count from student
inner join application_tab_status on student.Student_Id =application_tab_status.Student_Id
where application_tab_status.DeleteStatus=0 and student.DeleteStatus=0 and Application_status_tab=1  ",Search_Date_," ",Department_String_To_User_,"

union
select 12 as tp,COALESCE(count(application_tab_status.Student_Id)) as Data_Count from student
inner join application_tab_status on student.Student_Id =application_tab_status.Student_Id
where application_tab_status.DeleteStatus=0 and student.DeleteStatus=0 and Offer_status=1 ",Search_Date_," ",Department_String_To_User_,"

union
select 13 as tp,COALESCE(count(application_tab_status.Student_Id)) as Data_Count from student
inner join application_tab_status on student.Student_Id =application_tab_status.Student_Id
where application_tab_status.DeleteStatus=0 and student.DeleteStatus=0 and Invoice_Status=1 ",Search_Date_," ",Department_String_To_User_,"

union
select 14 as tp,COALESCE(count(application_tab_status.Student_Id)) as Data_Count from student
inner join application_tab_status on student.Student_Id =application_tab_status.Student_Id
where application_tab_status.DeleteStatus=0 and student.DeleteStatus=0 and Initial_Fee_Status=1",Search_Date_," ",Department_String_To_User_,"

union
select 15 as tp,COALESCE(count(application_tab_status.Student_Id)) as Data_Count from student
inner join application_tab_status on student.Student_Id =application_tab_status.Student_Id
where application_tab_status.DeleteStatus=0 and student.DeleteStatus=0 and Half_Fee_Status=1 ",Search_Date_," ",Department_String_To_User_,"

union
select 16 as tp,COALESCE(count(application_tab_status.Student_Id)) as Data_Count from student
inner join application_tab_status on student.Student_Id =application_tab_status.Student_Id
where application_tab_status.DeleteStatus=0 and student.DeleteStatus=0 and Full_Fee_Status=1 ",Search_Date_," ",Department_String_To_User_,"

 order by tp  ");
PREPARE QUERY FROM @query;
#select @query;
insert into data_log_ value(0,@query,'');
EXECUTE QUERY;
END$$
