select 1 as tp,'',count(application_details.Application_details_Id) as Data_Count from application_details 
where application_details.DeleteStatus=0 ",SearchbyName_Value,"  ", Search_Date_Application_ ," and application_details.User_List like '%*",Login_User_Id_,"*%'

   union
