CREATE DEFINER=`root`@`localhost` PROCEDURE `Get_Enquiry_Source_data_Count`(In RoleId_ varchar(100),Department_String varchar(1000),Fromdate_ date,Todate_ date,
Date_Value_ int,User_Id_ int)
BEGIN

declare curday int;declare SearchbyName_Value varchar(2000); declare Search_Date_ varchar(2000);
declare Search_Date_Student_ varchar(200); 

set SearchbyName_Value='';

if Date_Value_=0 then
	set Search_Date_Student_ = " and 1=1";
	set Fromdate_=now();
	set Todate_=now();
	set curday=(SELECT DAY(Fromdate_)-1);
	set Fromdate_=(SELECT DATE_SUB(Fromdate_, INTERVAL curday DAY));
  
else
	set Search_Date_Student_ =concat( " and date(student.Entry_Date) >= '", Fromdate_ ,"' and  date(student.Entry_Date) <= '", Todate_,"'");
end if;
if User_Id_>0 then
SET SearchbyName_Value =concat(SearchbyName_Value," and student.To_User_Id =",User_Id_);
end if;


#set Fromdate_=now();
#set Todate_=now();
#set curday=(SELECT DAY(Fromdate_)-1);
#set Fromdate_=(SELECT DATE_SUB(Fromdate_, INTERVAL curday DAY));

SET @query = Concat( "select enquiry_source.Enquiry_Source_Name,count(student.Student_Id) as Data_Count from
enquiry_source left join student on enquiry_source.Enquiry_Source_Id=student.Enquiry_Source_Id and student.DeleteStatus=0  
and student.Role_Id in(",RoleId_,") where enquiry_source.DeleteStatus=0 ",Department_String,"",SearchbyName_Value,"",Search_Date_Student_,"
group by enquiry_source.Enquiry_Source_Name
order by Enquiry_Source_Name");
PREPARE QUERY FROM @query;
#select @query;
#insert into data_log_ value(0,@query,'');
EXECUTE QUERY;
END$$
