CREATE DEFINER=`root`@`localhost` PROCEDURE `Get_FollowUp`(IN Student_Id_ INT)
BEGIN
    -- Retrieve distinct departments the student has interacted with
    WITH LatestFollowUp AS (
        SELECT sf.*
        FROM student_followup sf
        INNER JOIN (
            -- Get the latest follow-up entry for each department
            SELECT Department, MAX(Entry_date) AS LatestEntry
            FROM student_followup
            WHERE Student_Id = Student_Id_ AND DeleteStatus = 0
            GROUP BY Department
        ) latest ON sf.Department = latest.Department AND sf.Entry_date = latest.LatestEntry
        WHERE sf.Student_Id = Student_Id_ AND sf.DeleteStatus = 0
    )
    
    -- Select required columns
    SELECT 
        sf.Student_FollowUp_Id,
        sf.Student_Id,
        sf.Entry_date,
        sf.Department,
        sf.Status,
        sf.User_Id,
        sf.By_User_Id,
        
        sf.Branch_Name,
        sf.UserName AS ToUserName,  -- User responsible for follow-up
        sf.ByUserName,
        sf.Dept_StatusName,
        sf.Dept_Name as Department_Name
       
    FROM LatestFollowUp sf
    ORDER BY sf.Entry_date DESC;

END$$
DELIMITER ;

DELIMITER $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `Get_Followup_Date_Generic`(
    IN Student_Id_ INT,
    IN Department_Id_ INT,
    IN Department_Status_Id_ INT
)
BEGIN
    DECLARE v_used_count INT;
    DECLARE v_day_count INT;
    DECLARE v_followup_date DATE;
    declare Next_FollowUp_date_ date;
    set Next_FollowUp_date_=(select Next_FollowUp_date from student_followup where Student_Id = Student_Id_ 
    order by Student_FollowUp_Id asc limit 1);

    /* already same status ethra thavana use cheythu */
    SELECT COUNT(*)
    INTO v_used_count
    FROM student_followup
    WHERE Student_Id = Student_Id_ AND Department=Department_Id_
      AND Status = Department_Status_Id_;
    /* next available status_count (VALUE independent) */
    SELECT Duration_Count
    INTO v_day_count
    FROM department_status_duration
    WHERE Department_Status_Id = Department_Status_Id_ AND Department_Id=Department_Id_
    and Duration_Count=v_used_count
    ORDER BY Duration_Count
    LIMIT v_used_count, 1;
    /* if exceeded → last record */
    IF v_day_count IS NULL THEN
        SELECT Duration_Count
        INTO v_day_count
        FROM department_status_duration
        WHERE Department_Status_Id = Department_Status_Id_ AND Department_Id=Department_Id_
        ORDER BY Duration_Count DESC
        LIMIT 1;
    END IF;
    SET v_followup_date = DATE_ADD(Next_FollowUp_date_, INTERVAL v_day_count DAY);
    SELECT (case when ifnull(v_followup_date,'')='' then  (Date_Format(now(),'%Y-%m-%d')) else (Date_Format(v_followup_date,'%Y-%m-%d')) end)  AS followup_date;
END$$
DELIMITER ;

