Begin
declare Task_Count_ int;declare Cur_Date_ date;
set Cur_Date_=CURDATE() ;
SELECT Student_Id,Student_Name,Address2,IFNULL(Email, '') as Email,Address1,
Alternative_Email,Phone_Number,Guardian_telephone,Counsilor_Note,BPH_Note,Pre_Visa_Note,
Alternative_Phone_Number,Dob,(Date_Format(Entry_date,'%Y-%m-%d')) As Entry_date,Spouse_visa_Name as Passport_Name,Country_Name,Student_Status_Id,
Enquiry_Source_Id,Enquiry_Mode_Id,Shore_Id,Sub_Status_Name,Whatsapp,Refund_Amount,Refund_Description,Proceeding_University_Id,Proceeding_University_Name,
Is_Registered,Programme_Course Program_Course_Name,IFNULL(Agent, '') as Agent,Send_Welcome_Mail_Status,Program_Course_Id,Unique_Id,Sub_Status_Id,
Previous_Visa_Rejection,No_of_Kids_and_Age,Dropbox_Link,Spouse_Occupation,Date_of_Marriage,Spouse_Name,Enquiryfor_Id,To_User_Id,Marital_Status_Id,
IFNULL(Passport_No,'') as Passport_No,(Date_Format(Passport_fromdate,'%Y-%m-%d')) As Passport_fromdate,IFNULL(FollowUp_Entrydate,'') as FollowUp_Entrydate,
(Date_Format(Passport_Todate,'%Y-%m-%d')) As Passport_Todate,IFNULL(Passport_Id, 0) as Passport_Id,IFNULL(Spouse_Visa_Id,0) as Spouse_Visa_Id,
IFNULL(Registered_On, '') as Registered_On,IFNULL(Registration_Target, 0) as Registration_Target,IFNULL(FollowUp_Count, 0) as FollowUp_Count,
IFNULL(Registration_Branch, '') as Registration_Branch,IFNULL(Entry_Type, '') as Entry_Type,IFNULL(First_Followup_Status, '') as First_Followup_Status,
IFNULL(First_Followup_Date, '') as First_Followup_Date,IFNULL(Student_Registration_Id, 0) as Student_Registration_Id,IFNULL(FollowUp, '') as FollowUp, 
IFNULL(Followup_Department_Name, '') as Department_Name,IFNULL(Followup_Branch_Name, '') as Branch_Name,IFNULL(Agent_Name, '') as Agent_Name, 
IFNULL(Client_Accounts_Name, '') as Client_Accounts_Name,IFNULL(Department_Status_Name, '') as Department_Status_Name,IFNULL(Role_Id, 0) as Role_Id,
IFNULL(To_User_Name, '') as User_Details_Name,IFNULL(Enquiry_Source_Name, '') as Enquiry_Source_Name,IFNULL(Created_User, '') as Created_User, 
IFNULL(Registered_User, '') as Registered_User,IFNULL(Registered_Branch, '') as Registered_Branch,IFNULL(Marital_Status_Id,'') as Marital_Status_Id,
IFNULL(Marital_Status_Name,'') as Marital_Status_Name,IFNULL(Program_Course_Id,0) as Program_Course_Id,IFNULL(Profile_Country_Id,0) as Country_Id,
IFNULL(Profile_University_Id,0) as Profile_University_Id,(Date_Format(Created_On,'%Y-%m-%d')) as Created_On,Next_FollowUp_date as date,Education_Loan,
Loan_Amount,Loan_Description,Education_Loan,Loan_Amount,Loan_Description,User_Match_Flag,IFNULL(Proceeding_University_Id,0)Proceeding_University_Id,
IFNULL(Proceeding_University_Name,'')Proceeding_University_Name,IFNULL(Proceeding_Country_Id,0)Proceeding_Country_Id,IFNULL(Brand_Id,0)Brand_Id,
IFNULL(Proceeding_Country_Name,'')Proceeding_Country_Name,IFNULL(Proceeding_Intake_Id,0)DSE_Id,IFNULL(Proceeding_Intake_Name,'')DSE_Name,
IFNULL(Brand_Name,'')Brand_Name,ifnull(Location_Id,0)Location_Id,ifnull(Location_Name,'')Location_Name,ifnull(Enquiry_No,'')Enquiry_No,
ifnull(Lead_Id,'') Lead_Id, Transfer_date
From Student where Student_Id =Student_Id_ and DeleteStatus=false ;
select * from Student_Document where Student_Id =Student_Id_ and DeleteStatus=false order by Document_Id;
set Task_Count_ = (select count(Student_Task_Id) as Student_Task_Count from Student_Task  
where DeleteStatus=0 and Student_Task.Task_Status =1 and To_User = To_User_ and Student_Id = Student_Id_ and date(Student_Task.Followup_Date) <= Cur_Date_);
select Task_Count_;
#(case when Transfer_Date is null then now() else Date_Format(Transfer_Date,'%Y-%m-%d')end) As Last_Name,
