#IFNULL(Work_Experience,'') Work_Experience ,#IFNULL(Resume,'') Resume ,IFNULL(Address1, '') as Address1,#Password,#College_University,
#Intake,#Year,Reference,#Visa_Submission_Date,#Activity,#Visa_Outcome,#IFNULL(Course_Link, '') as Course_Link,#Status_Details,#Student_Remark,
#IFNULL(Created_On,'') as Created_On,#IFNULL(Visa_Outcome, '') as Visa_Outcome, #IFNULL(Intake_Id,0) as Intake_Id,
End$$
