CREATE DEFINER=`root`@`localhost` PROCEDURE `Get_Tasknew_Task`( In Student_Id_ Int,Task_Group_Id_ int,Login_User_ int)
Begin
declare Cur_Date_ date;
set Cur_Date_=CURDATE() ;
SELECT DISTINCT(student_task.Student_Task_Id),Task_Group_Id,student_task.Student_Id,Student_Name,
To_User,To_User_Name,Department_Name,Task_Details,
(Date_Format(student_task.Followup_Date,'%d-%m-%Y')) AS Grid_Followup_Date, (Date_Format(student_task.Followup_Date,'%Y-%m-%d')) AS Followup_Date,
Task_Status,Status_Name,student_task.Remark,task_item.Task_Item_Id,task_item.Task_Item_Name,Department_Id,student_task.Task_Group_Id,Branch_Id,Branch_Name
#,student_followup.Department,student_followup.Dept_Name,student_followup.User_Id,student_followup.UserName
From student_task 
inner join task_item on task_item.Task_Item_Id=student_task.Task_Item_Id
#inner join student_followup on student_followup.Student_Id=student_task.Student_Id
#where student_task.Student_Id =Student_Id_ and student_task.Task_Group_Id=Task_Group_Id_ and student_task.DeleteStatus=false ;
where student_task.Student_Id =Student_Id_ and student_task.Task_Group_Id=Task_Group_Id_ and student_task.DeleteStatus=false and ( To_User =Login_User_ or By_User_Id=Login_User_ ) ;
select count(Student_Task_Id) as Student_Task_Count from Student_Task  where DeleteStatus=0 and Student_Task.Task_Status =1 and To_User =Login_User_ and Student_Id = Student_Id_ and date(Student_Task.Followup_Date) <= Cur_Date_ ;
 End$$
