CREATE DEFINER=`root`@`localhost` PROCEDURE `Group_Save`(In Group_Users_ json, Group_Name_ varchar(1000),From_User_ int,From_UserName_ varchar(100),Channel_Type_ int)
BEGIN
declare Channel_Id_ int; declare Group_Users_Id_ int;declare i int default 0 ;
insert into channel (Channel_Name,User_Id,User_Name,Channel_Type,Entry_Date,DeleteStatus)
			values	(Group_Name_,From_User_,From_UserName_,Channel_Type_,now(),0);
set Channel_Id_ = (select last_insert_id());
WHILE i < JSON_LENGTH(Group_Users_) DO
#if( Group_Users_>0) then
	SELECT JSON_UNQUOTE (JSON_EXTRACT(Group_Users_,CONCAT('$[',i,'].User_Id'))) INTO Group_Users_Id_;
	#SELECT JSON_UNQUOTE (JSON_EXTRACT(Group_Users_,'$.User_Details_Id')) INTO Group_Users_Id_;
	insert into channel_sub (Channel_Id,User_Id,Msg_Count,ReadStatus,DeleteStatus)
	values (Channel_Id_,Group_Users_Id_,0,0,false);
#end if; 
SELECT i + 1 INTO i;      
END WHILE;          
select Channel_Id_,Channel_Type_,From_UserName_ as User_Name_;
END$$
DELIMITER ;

