CREATE DEFINER=`root`@`localhost` PROCEDURE `Load_ChatUser_Details_comment`(
IN Value_ VARCHAR(1000),
    IN Login_User_ INT,
    IN Application_Details_Id_ INT
)
BEGIN
    -- Fetch details for the application, including To_User_Id and User_Id
    SELECT
     distinct ad.To_User_Id as User_Details_Id,
        ud_to.User_Details_Name      
    FROM
        application_details_history ad
    inner JOIN
        user_details ud_to ON ad.To_User_Id = ud_to.User_Details_Id
WHERE
        ad.Application_Details_Id = Application_Details_Id_
        union
         SELECT
         ad.User_Id as User_Details_Id,
        ud_by.User_Details_Name        
    FROM
        application_details ad
    inner JOIN
        user_details ud_by ON ad.User_Id = ud_by.User_Details_Id
    WHERE
        ad.Application_Details_Id = Application_Details_Id_;  
       
END$$
DELIMITER ;

