CREATE DEFINER=`root`@`localhost` PROCEDURE `Pending_FollowUp`(In Department_ int,Branch_ int,By_User_ int,Login_User_Id_ int)
BEGIN
declare Search_Date_ varchar(500);declare Department_String_To_User_ varchar(4000);
declare RoleId_ varchar(100);declare Department_String_ varchar(4000);
declare SearchbyName_Value varchar(2000);declare User_Type_ int;
set SearchbyName_Value='',Search_Date_='',Department_String_To_User_='',Department_String_='';
set User_Type_=(select User_Type from user_details where User_Details_Id=Login_User_Id_);
 set RoleId_ =(select Role_String from user_details where User_Details_Id = Login_User_Id_);
#set Department_String_ = (select Department_String from user_details where User_Details_Id = Login_User_Id_);
set Search_Date_=concat( " and date(student.Next_FollowUp_Date) < '", Date_Format( Now(),'%Y-%m-%d'),"'" );
if Department_>0 then
SET SearchbyName_Value =concat(SearchbyName_Value," and student.Followup_Department_Id =",Department_);
end if;
if Branch_>0 then
SET SearchbyName_Value =concat(SearchbyName_Value," and student.Followup_Branch_Id =",Branch_);
end if;
/*if User_Type_=2 then
 	SET SearchbyName_Value =concat(SearchbyName_Value," and student.To_User_Id =",Login_User_Id_);
    else
    SET SearchbyName_Value =concat(SearchbyName_Value," and student.To_User_Id in (select User_Details_Id from user_details where Branch_Id in (select
distinct Branch_Id from user_department where User_Id =",Login_User_Id_," and VIew_All=1))");
end if;*/
SET SearchbyName_Value =concat(SearchbyName_Value," and student.To_User_Id in(select User_Selection_Id from sub_users where User_Id=",Login_User_Id_,")");
if By_User_>0 then
SET SearchbyName_Value =concat(SearchbyName_Value," and student.To_User_Id in(select User_Selection_Id from sub_users where User_Id=",By_User_,")");
end if;
set Department_String_To_User_ =REPLACE(Department_String_,'By_User_Id','To_User_Id');
SET @query = Concat( "select (Date_Format(student.Entry_Date,'%d-%m-%Y')) As Created_On,user_details.User_Details_Name As Created_By,
 student.Student_Name Student,student.Phone_Number Mobile,Branch.Branch_Name Branch,
(Date_Format(student.Next_FollowUp_Date,'%d-%m-%Y')) As Follow_Up_On,Department.Department_Name Department,
student.Department_Status_Name Status,T.User_Details_Name To_Staff,B.User_Details_Name Registered_By,
(Date_Format(student.Registered_On,'%d-%m-%Y-%h:%i')) As Registered_On,student.Remark,student.Student_Id
from student
inner join Department on Department.Department_Id= student.Followup_Department_Id  ",Department_String_To_User_,Search_Date_,"
left join user_details on user_details.User_Details_Id=student.Created_By
inner join Branch on Branch.Branch_Id= student.Followup_Branch_Id
#inner join Department_Status on Department_Status.Department_Status_Id=student.Status_Id
left join user_details as T on T.User_Details_Id=student.To_User_Id
left join user_details as B on B.User_Details_Id=student.Registered_By
where student.DeleteStatus=0 and student.FollowUp=1  ",SearchbyName_Value,"
and T.Role_Id in(",RoleId_,")
order by Next_FollowUp_Date asc ");
PREPARE QUERY FROM @query;
#select @query;
insert into data_log_ value(0,@query,'Pending_FollowUp');
EXECUTE QUERY;
END$$
DELIMITER ;

DELIMITER $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `Post_Call_Data`(In Phone_Number_ varchar(100),Extension_Id_ varchar(100),User_Phone_ varchar(45),File_Info_ varchar(100),CallType_ varchar(100))
BEGIN
declare Student_Id_ int;declare Student_Name_ varchar(500);declare User_Id_ int;declare User_Details_Name_ varchar(500);declare User_Branch_Id_ int;
declare User_Branch_Name_ varchar(200);declare User_Department_Id_ int;declare User_Department_Name_ varchar(200);declare Department_Status_Id_ int;
declare Department_Status_Name_ varchar(100);declare Role_Id_ int;declare Student_FollowUp_Id_ int;
declare Department_FollowUp_ int;declare Whatsapp_Notification_ int;

set Phone_Number_=REPLACE(REPLACE(REPLACE(REPLACE(Phone_Number_, ' ', ''), '\t', ''), '\n', ''), '+', '');

set Student_Id_ = (SELECT COALESCE((SELECT Student_Id FROM Student WHERE  Phone_Number like concat('%',Phone_Number_,'%') and DeleteStatus=0), 0));

set User_Id_ = (SELECT User_Details_Id FROM user_details WHERE   Mobile = User_Phone_  and  FollowUp_Target=Extension_Id_ and DeleteStatus=0);
set  User_Details_Name_ =(SELECT User_Details_Name FROM user_details WHERE   User_Details_Id = User_Id_  );
set User_Branch_Id_= (SELECT Branch_Id FROM user_details WHERE   User_Details_Id = User_Id_  );
set User_Branch_Name_= (SELECT Branch_Name FROM branc h WHERE   Branch_Id = User_Branch_Id_  );

set User_Department_Id_= (SELECT Department_Id FROM user_details WHERE   User_Details_Id = User_Id_  );
set User_Department_Name_= (SELECT Department_Name FROM user_details WHERE   User_Details_Id = User_Id_   );

set Department_Status_Id_ =(SELECT Department_Status_Id FROM department WHERE   Department_Id = User_Department_Id_  );
set Department_Status_Name_ =(SELECT Department_Status_Name FROM department_status WHERE   Department_Status_Id = Department_Status_Id_  );
set Department_FollowUp_ =(select Followup from department_status where Department_Status_Id=Department_Status_Id_);
set Role_Id_ =(SELECT Role_Id FROM user_details WHERE   User_Details_Id = User_Id_  );

if(Student_Id_)>0 then

set Whatsapp_Notification_ = 0;
set Student_Name_ = (SELECT Student_Name FROM Student WHERE   Student_Id = Student_Id_  and DeleteStatus=0);

INSERT INTO student_followup(Student_Id ,Entry_Date,Next_FollowUp_Date,FollowUp_Difference,Department ,Status ,User_Id ,Branch,Remark,Remark_Id,By_User_Id,
Class_Id ,Class_Name,DeleteStatus,FollowUP_Time,Actual_FollowUp_Date,Entry_Type,Branch_Name,UserName,ByUserName,Dept_StatusName,Dept_Name,Student,FollowUp,File_Name,CallType)
values (Student_Id_ ,Now(),Now(),0,User_Department_Id_ ,Department_Status_Id_ ,User_Id_ ,User_Branch_Id_,'',0,User_Id_,312,'New Lead',false,
Now(),Now(),1,User_Branch_Name_,User_Details_Name_,User_Details_Name_,Department_Status_Name_,User_Department_Name_,Student_Name_,Department_FollowUp_,File_Info_,CallType_);
set Student_Followup_Id_ =(SELECT LAST_INSERT_ID());

 update Student set Student_Followup_Id=Student_Followup_Id_,Next_FollowUp_Date=now(),
Status_Id=Department_Status_Id_,By_User_Id=User_Id_,To_User_Id=User_Id_,Remark='',Remark_Id=0,Followup_Department_Name = User_Department_Name_,
Department_Status_Name = Department_Status_Name_,To_User_Name = User_Details_Name_,By_UserName = User_Details_Name_,FollowUp = Department_FollowUp_,
    Followup_Department_Id=User_Department_Id_,Followup_Branch_Id = User_Branch_Id_,Role_Id = Role_Id_
where Student_Id=Student_Id_;
else

SET Student_Id_ = (SELECT  COALESCE( MAX(Student_Id ),0)+1 FROM Student);
INSERT INTO Student(Student_Id , Agent_Id, Entry_Date,Student_Name ,Address1 ,Address2 ,Email ,Alternative_Email,Phone_Number,Alternative_Phone_Number ,Dob ,Country_Name ,
Student_Status_Id,
    Enquiry_Source_Id ,Created_By,Whatsapp,DeleteStatus,Is_Registered,FollowUp_Count,FollowUp_EntryDate,
Entry_Type,First_Followup_Status,First_Followup_Date,Programme_Course,Reference,Passport_No,Passport_fromdate,Passport_Todate,Passport_Id,Enquiry_Source_Name,Created_User
,Marital_Status_Id,Marital_Status_Name,Program_Course_Id,Profile_Country_Id,Created_On,
Enquiryfor_Id,Enquirfor_Name,Shore_Id,Shore_Name,Spouse_Name,Date_of_Marriage,Spouse_Occupation,Spouse_Qualification,Dropbox_Link,
No_of_Kids_and_Age,Previous_Visa_Rejection,Enquiry_Mode_Id,Enquiry_Mode_Name,Branch_Id,Department_Id,
Visa_User,Pre_Visa_User,Pre_Admission_User,Admission_User,Applicaton_User,Counsilor_User,Refund_user,Cas_User,Visa_Rejection_User,
Pre_Application_User,Bph_User,Closed_User,Unique_Id,Class_Id,Class_Name,Guardian_telephone,Link_Send_By,Status_Student_Fill,Counsilor_Note,BPH_Note,Pre_Visa_Note,Followup_Branch_Name)
values (Student_Id_ ,1,now(),'unknown' ,'' ,'' ,'','',Phone_Number_ ,
'','' ,'' ,0,
    64 ,User_Id_,Phone_Number_,false,0,0,now(),1,1,now(),'','','',now(),now(),0,'voxbay',User_Details_Name_,0,'',0,0,now(),
0,'',0,'','','','','','','','',0,'',User_Branch_Id_,User_Department_Id_, 0,0,0,0,0,User_Id_,0,0,0,0,0,0,UUID(),312,'New Lead','',0,0,'','','',User_Branch_Name_);
   

INSERT INTO student_followup(Student_Id ,Entry_Date,Next_FollowUp_Date,FollowUp_Difference,Department ,Status ,User_Id ,Branch,Remark,Remark_Id,By_User_Id,
Class_Id ,Class_Name,DeleteStatus,FollowUP_Time,Actual_FollowUp_Date,Entry_Type,Branch_Name,UserName,ByUserName,Dept_StatusName,Dept_Name,Student,FollowUp,File_Name,CallType)
values (Student_Id_ ,Now(),Now(),0,User_Department_Id_ ,Department_Status_Id_ ,User_Id_ ,User_Branch_Id_,'',0,User_Id_,312,'New Lead',false,
Now(),Now(),1,User_Branch_Name_,User_Details_Name_,User_Details_Name_,Department_Status_Name_,User_Department_Name_,Student_Name_,Department_FollowUp_,File_Info_,CallType_);
