CREATE DEFINER=`root`@`localhost` PROCEDURE `Post_FB_Lead_Immigration`(
  IN p_DATE VARCHAR(100),
  IN p_NAME VARCHAR(1000),
  IN p_PHONE VARCHAR(200),
  IN p_DISTRICT VARCHAR(200),
  IN p_MODEL VARCHAR(500)
)
BEGIN
    DECLARE User_Id_ INT;
    DECLARE User_Status_ INT;
    DECLARE Backup_User_ INT;
    DECLARE Working_Status_ INT;
    DECLARE Sub_User_ INT;
    DECLARE Status_Id_ INT;
    DECLARE Department_Status_Id_ INT;
    DECLARE Department_Status_Name_ VARCHAR(50);
    DECLARE By_User_Name_ VARCHAR(250);
    DECLARE Department_Name_ VARCHAR(100);
    DECLARE Department_FollowUp_ TINYINT;
    DECLARE To_User_Name_ VARCHAR(250);
    DECLARE Student_FollowUp_Id_ INT;
    DECLARE Department_Id_ INT;
    DECLARE Remark_Id_ INT;
    DECLARE Role_Id_ INT;
    DECLARE Entry_Type_ INT;
    DECLARE Notification_Type_Name_ VARCHAR(100);
    DECLARE Whatsapp_ VARCHAR(20);
    DECLARE Total_User_ INT;
    DECLARE Student_Id_ INT;
    DECLARE x INT;
    DECLARE Application_details_Id_ INT;
    DECLARE Application_status_Id_ INT;
    DECLARE Old_Id_ INT;
    DECLARE Application_Status_Name_ VARCHAR(45);
    DECLARE Notification_Id_ INT;
    DECLARE From_User_Name_ VARCHAR(45);
    DECLARE ToUser_Name_ VARCHAR(45);
    DECLARE Notification_Count_ INT;
    DECLARE Current_Department_Id_ INT;
    DECLARE i INT DEFAULT 0;
    DECLARE Enquiry_Source_Id_ INT;
	DECLARE Enquiry_Source_Name_ VARCHAR(45);
    DECLARE Class_Id_ INT;
    Declare Login_user_id_ int;    
    Declare Last_User_Id_ int;
    declare Counsilor_Note_ longtext;
    declare Enquiry_for_Id_ int default 0;
    declare Enquiry_for_Name_ varchar(200) default 'Select';
    declare Model_Id_ int;
    declare Branch_Id_ int;
	declare Branch_Name_ varchar(200);
    declare Model_Name_ varchar(200);
	declare Phone_Number_ varchar(200);
    declare v_date datetime;
    set v_date = LEFT(REPLACE(p_date,'T',' '),19);
    SET x = 0;        
    set Department_Id_ = 440;
    set Department_Name_='NEXA DIGITAL';
    set Enquiry_Source_Id_=15;
    set Enquiry_Source_Name_='META';
    set Department_Status_Id_ = 710;
    set Department_Status_Name_ = 'JUST ENQUIRY';
    
    set Department_FollowUp_= (select Followup from department_status where  Department_Status_Id=Department_Status_Id_);
    
    set  Branch_Name_=(select  SUBSTRING_INDEX(p_DISTRICT, '_', 1));
	set  Model_Name_=(select  SUBSTRING_INDEX(p_MODEL, '_', 1));      
    set Model_Id_ =(select Country_Id from country where Country_Name=Model_Name_ and Brand_Id in(select Brand_Id 
    from brand where Default_Department_Id=440));
    set Branch_Id_=(select Branch_Id from branch where Branch_Name=Branch_Name_);
    
    SELECT COALESCE((
    SELECT last_assigned_user_id
    FROM round_robin_tracker
    WHERE department_id = Department_Id_
    and branch_id=Branch_Id_
), 0)
INTO User_Id_;

SELECT COALESCE((
    SELECT User_Details_Id
    FROM user_details
    WHERE Department_Id = Department_Id_
      and branch_id=Branch_Id_
      AND DeleteStatus = 0
      AND User_Details_Id > IFNULL(User_Id_,0)
      and Lead_Assigned=1
    ORDER BY User_Details_Id
    LIMIT 1
), 0)
INTO User_Id_;

IF User_Id_ IS NULL OR User_Id_ = 0 THEN
    SELECT COALESCE((
        SELECT User_Details_Id
        FROM user_details
        WHERE Department_Id = Department_Id_
          and branch_id=Branch_Id_
          AND DeleteStatus = 0
		and Lead_Assigned=1
        ORDER BY User_Details_Id
        LIMIT 1
    ),0)
    INTO User_Id_;
END IF;
    
DELETE FROM round_robin_tracker
WHERE department_id = Department_Id_;
INSERT INTO round_robin_tracker (department_id, branch_id, last_assigned_user_id)
VALUES (Department_Id_, Branch_Id_, User_Id_);

    SET Phone_Number_ =
        IF(CHAR_LENGTH(p_PHONE) > 10, RIGHT(p_PHONE, 10),
            IF(SUBSTRING(p_PHONE, 1, 3) = '+91', REPLACE(p_PHONE, '+91', ''),
                IF(SUBSTRING(p_PHONE, 1, 2) = 'p:', REPLACE(p_PHONE, 'p:', ''), p_PHONE)));
         
    SELECT Working_Status, Backup_User_Id
    INTO Working_Status_, Backup_User_
    FROM user_details WHERE User_Details_Id = User_Id_;
       
    SELECT Working_Status, Backup_User_Id, Role_Id, User_Details_Name
    INTO Working_Status_, Backup_User_, Role_Id_, To_User_Name_ 
    FROM User_Details WHERE User_Details_Id = User_Id_;
    
    SET By_User_Name_ = (SELECT User_Details_Name FROM user_details 
                             WHERE User_Details_Id = User_Id_);                             
 
	SET Student_Id_ = (SELECT  COALESCE( MAX(Student_Id ),0)+1 FROM Student);
    INSERT INTO Student(
        Student_Id, Agent_Id, Entry_Date, Student_Name,Phone_Number, Student_Status_Id, Enquiry_Source_Id, Created_By, 
         DeleteStatus, FollowUp_Count, FollowUp_EntryDate, Entry_Type,Profile_Country_Id,Country_Name,Enquiry_Source_Name, 
         Created_User, Created_On,Enquiryfor_Id,Enquirfor_Name
    ) VALUES (
        Student_Id_, 0, v_date, p_NAME,Phone_Number_, 0, Enquiry_Source_Id_,User_Id_,
        false,0,v_date, 1,Model_Id_,Model_Name_,Enquiry_Source_Name_, 
        By_User_Name_,v_date,0,'Select'
    );
    INSERT INTO student_followup(
        Student_Id, Entry_Date, Next_FollowUp_Date, FollowUp_Difference, Department, 
        Status, User_Id, Branch, Remark, Remark_Id, By_User_Id, 
        DeleteStatus, FollowUP_Time, Actual_FollowUp_Date, Entry_Type, Branch_Name, 
        UserName, ByUserName, Dept_StatusName, Dept_Name, Student,FollowupBranch, FollowUp,FollowUp_Count
    ) VALUES (
        Student_Id_, v_date, v_date, 0, Department_Id_, Department_Status_Id_, User_Id_, Branch_Id_, '', 0, User_Id_, 
        false, v_date,v_date, 1, Branch_Name_, To_User_Name_, By_User_Name_, Department_Status_Name_, Department_Name_, 
        p_NAME,Branch_Name_, Department_FollowUp_,1
    );    
    SET Student_Followup_Id_ = (SELECT LAST_INSERT_ID());    
    UPDATE Student 
    SET Student_Followup_Id = Student_Followup_Id_,
        Next_FollowUp_Date = v_date,
        Status_Id = Department_Status_Id_,
        By_User_Id = User_Id_,
        To_User_Id = User_Id_,
        Remark = '',
        Remark_Id = 0,
        Followup_Department_Name = Department_Name_,
        Department_Status_Name = Department_Status_Name_,
        To_User_Name = To_User_Name_,
        By_UserName = By_User_Name_,
        FollowUp = Department_FollowUp_,
        Followup_Department_Id = Department_Id_,
        Followup_Branch_Id = Branch_Id_,
        Role_Id = Role_Id_
    WHERE Student_Id = Student_Id_;
    
    SET ToUser_Name_ = (SELECT User_Details_Name FROM user_details WHERE User_Details_Id = User_Id_ AND DeleteStatus = false);  
    SET Notification_Type_Name_ = 'Pably';
    SET Entry_Type_ = 14;
    SET Notification_Id_ = (SELECT COALESCE(MAX(Notification_Id), 0) + 1 FROM Notification);    
    INSERT INTO Notification (
        Notification_Id, From_User, From_User_Name, To_User, To_User_Name, 
        Status_Id, Status_Name, View_Status, Remark, Entry_Date, 
        Student_Id, Student_Name, DeleteStatus, Description, Entry_Type) 
    VALUES (Notification_Id_, 0, '', User_Id_, By_User_Name_,0, '', 1, '', v_date, 
        Student_Id_, p_NAME, false, Notification_Type_Name_, Entry_Type_);    
    SET Notification_Count_ = (SELECT COALESCE(MAX(Notification_Count), 0) + 1 FROM User_Details WHERE User_Details_Id = User_Id_);    
    UPDATE User_Details SET Notification_Count = Notification_Count_ WHERE User_Details_Id = User_Id_;    

SELECT 
    Student_Id_,
    User_Id_,
    By_User_Name_,
    Notification_Id_,
    p_NAME,
    Entry_Type_,
    ToUser_Name_,
    Notification_Type_Name_,
    p_NAME;
END$$
