DELIMITER $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `Post_GoogleSheet_Campaign_Lead`(
  IN Student_Name_ VARCHAR(1000),
  IN Phone_Number_ VARCHAR(100),
  IN Destination_ VARCHAR(2000),
  IN preferred_course_ VARCHAR(2000),
  IN email_ VARCHAR(500),
  IN followupdate_ VARCHAR(500),
  IN location_ VARCHAR(500),
  IN have_ielts_ VARCHAR(500),
  IN need_scholarship_help_ VARCHAR(255),
  IN preferred_degree_ VARCHAR(255),
  IN ad_id_ VARCHAR(1000),
  IN ad_name_ VARCHAR(1000),
  IN adset_id_ VARCHAR(1000),
  IN adset_name_ VARCHAR(1000),
  IN campaign_id_ VARCHAR(1000),
  IN campaign_name_ VARCHAR(1000),
  IN form_id_ VARCHAR(1000),
  IN form_name_ VARCHAR(1000),
  IN is_organic_ TINYINT(1),
  IN platform_ VARCHAR(100),
  IN interested_in_scholarship_ VARCHAR(100)
)
BEGIN
    DECLARE User_Id_ INT;
    DECLARE User_Status_ INT;
    DECLARE Backup_User_ INT;
    DECLARE Working_Status_ INT;
    DECLARE Sub_User_ INT;
    DECLARE Status_Id_ INT;
    DECLARE Department_Status_Id_ INT;
    DECLARE Department_Status_Name_ VARCHAR(50);
    DECLARE Branch_ INT;
    DECLARE Branch_Name_ VARCHAR(50);
    DECLARE By_User_Name_ VARCHAR(250);
    DECLARE Department_Name_ VARCHAR(100);
    DECLARE Department_FollowUp_ TINYINT;
    DECLARE To_User_Name_ VARCHAR(250);
    DECLARE Student_FollowUp_Id_ INT;
    DECLARE Department_Id_ INT;
    DECLARE Remark_Id_ INT;
    DECLARE Role_Id_ INT;
    DECLARE Entry_Type_ INT;
    DECLARE Notification_Type_Name_ VARCHAR(100);
    DECLARE Whatsapp_ VARCHAR(20);
    DECLARE Total_User_ INT;
    DECLARE Student_Id_ INT;
    DECLARE x INT;
    DECLARE Application_details_Id_ INT;
    DECLARE Application_status_Id_ INT;
    DECLARE Old_Id_ INT;
    DECLARE Application_Status_Name_ VARCHAR(45);
    DECLARE To_User_ INT;
    DECLARE Notification_Id_ INT;
    DECLARE From_User_Name_ VARCHAR(45);
    DECLARE ToUser_Name_ VARCHAR(45);
    DECLARE Notification_Count_ INT;
    DECLARE Current_Department_Id_ INT;
    DECLARE i INT DEFAULT 0;
    DECLARE Enquiry_Source_Id_ INT;
	DECLARE Enquiry_Source_Name_ VARCHAR(45);
    DECLARE Class_Id_ INT;
    Declare Login_user_id_ int;    
    Declare Last_User_Id_ int;
    declare Counsilor_Note_ longtext;
    SET x = 0;        
    select Department_Id ,Department_Name,Department_Status_Id,Department_Status_Name,Branch_Id,to_user_id,Branch_Name,Enquiry_Source_Id,Enquiry_Source_Name,Last_User_Id
    into Department_Id_, Department_Name_,Department_Status_Id_,Department_Status_Name_,Branch_,User_Id_,Branch_Name_,Enquiry_Source_Id_,Enquiry_Source_Name_,Last_User_Id_
    from campaign_details where campaign_id = campaign_id_;
    
    if(ifnull(User_Id_,0)=0)then
		set Login_user_id_ = 0;		
		set Login_user_id_ = (SELECT COALESCE((
  SELECT User_Details_Id
  FROM user_details
  WHERE DeleteStatus = 0
    AND Working_Status = 1
    AND Department_Id = Department_Id_
    AND Branch_Id = Branch_
    AND User_Details_Id > IFNULL(Last_User_Id_, 0)
    AND Lead_Assigned = 1
  ORDER BY User_Details_Id ASC
  LIMIT 1
), 0));
        if(ifnull(Login_user_id_,0)=0)then
			set Login_user_id_ = (select ifnull(User_Details_Id,0) from user_details where DeleteStatus=0 and Working_Status=1 and Department_Id=Department_Id_ 
			and Branch_Id=Branch_ and Lead_Assigned=1 order by User_Details_Id asc limit 1);
		end if;
	else
        set Login_user_id_ = User_Id_;
	end if;
    
    update campaign_details set Last_User_Id=Login_user_id_ where campaign_id = campaign_id_;
    Select Followup into  Department_FollowUp_ from department_status where Department_Status_Id =Department_Status_Id_;
    
    SET Phone_Number_ =
        IF(CHAR_LENGTH(Phone_Number_) > 10, RIGHT(Phone_Number_, 10),
            IF(SUBSTRING(Phone_Number_, 1, 3) = '+91', REPLACE(Phone_Number_, '+91', ''),
                IF(SUBSTRING(Phone_Number_, 1, 2) = 'p:', REPLACE(Phone_Number_, 'p:', ''), Phone_Number_)));
    
    SET Whatsapp_ = Phone_Number_;  
    
    SET Old_Id_ = (SELECT COALESCE(Student_Id, 0) FROM Student 
                    WHERE DeleteStatus = FALSE AND (Phone_Number LIKE CONCAT('%', Phone_Number_, '%')) LIMIT 1);
    
    SET Student_Id_ = (SELECT Student_Id FROM Student 
                        WHERE DeleteStatus = 0 
                        AND (Phone_Number LIKE CONCAT('%', Phone_Number_, '%') 
                            OR Whatsapp LIKE CONCAT('%', Phone_Number_, '%') 
                            OR Alternative_Phone_Number LIKE CONCAT('%', Phone_Number_, '%')
                            OR Phone_Number LIKE CONCAT('%', Whatsapp_, '%') 
                            OR Whatsapp LIKE CONCAT('%', Whatsapp_, '%') 
                            OR Alternative_Phone_Number LIKE CONCAT('%', Whatsapp_, '%'))
                        LIMIT 1);
    
    SELECT Working_Status, Backup_User_Id
    INTO Working_Status_, Backup_User_
    FROM user_details WHERE User_Details_Id = Login_user_id_;
       
    SELECT Working_Status, Backup_User_Id, Role_Id, User_Details_Name
    INTO Working_Status_, Backup_User_, Role_Id_, To_User_Name_ 
    FROM User_Details WHERE User_Details_Id = Login_user_id_;
    
    SET By_User_Name_ = (SELECT User_Details_Name FROM user_details 
                             WHERE User_Details_Id = Login_user_id_);   
set Counsilor_Note_=concat(Destination_ ,",", preferred_course_);
IF (ifnull(Student_Id_,0)=0) THEN   
	SET Student_Id_ = (SELECT  COALESCE( MAX(Student_Id ),0)+1 FROM Student);
    INSERT INTO Student(
        Student_Id, Agent_Id, Entry_Date, Student_Name, Address2, Email, Alternative_Email, 
        Phone_Number, Dob, Country_Name, Student_Status_Id, Enquiry_Source_Id, Created_By, 
        Whatsapp, DeleteStatus, Is_Registered, FollowUp_Count, FollowUp_EntryDate, Entry_Type, 
        First_Followup_Status, First_Followup_Date, Programme_Course, Reference, Passport_No, 
        Passport_fromdate, Passport_Todate, Passport_Id, Enquiry_Source_Name, Created_User, 
        Marital_Status_Id, Marital_Status_Name, Program_Course_Id, Profile_Country_Id, Created_On,
        Enquiryfor_Id, Enquirfor_Name, Shore_Id, Shore_Name, Spouse_Name, Date_of_Marriage, 
        Spouse_Occupation, Dropbox_Link, No_of_Kids_and_Age, Previous_Visa_Rejection, 
        Enquiry_Mode_Id, Enquiry_Mode_Name, Branch_Id, Department_Id, Visa_User, Pre_Visa_User, 
        Pre_Admission_User, Admission_User, Applicaton_User, Counsilor_User, Refund_user, 
        Cas_User, Visa_Rejection_User, Pre_Application_User, Bph_User, Closed_User, Unique_Id, 
        Guardian_telephone, Link_Send_By, Status_Student_Fill, Counsilor_Note, BPH_Note, 
        Pre_Visa_Note, Followup_Branch_Name, Address1, qualification, 
        have_ielts, interested_in_scholarship, ad_id, ad_name, adset_id, adset_name, campaign_id, 
        campaign_name, form_id, form_name, is_organic, platform, preferred_degree, 
        need_scholarship_help
    ) VALUES (
        Student_Id_, 1, now(), Student_Name_, location_, '', '', 
        Phone_Number_, '', '', 0, Enquiry_Source_Id_, Login_user_id_, 
        Whatsapp_, false, 0, 0, followupdate_, 1, 
        1, followupdate_, '', '', '', 
        now(), now(), 0, Enquiry_Source_Name_, By_User_Name_, 
        0, '', 0, 0, now(),
        2, 'Study Abroad', 1, 'OffShore', '', '', 
        '', '', '', '', 0, 
        '', Branch_, Department_Id_, 0, 0, 
        0, 0, 0, Login_user_id_, 0, 
        0, 0, 0, 0, 0, UUID(), 
        '', 0, 0,Counsilor_Note_ , '', 
        '', Branch_Name_, location_, '', 
        have_ielts_, '', ad_id_, ad_name_, adset_id_, 
        adset_name_, campaign_id_, campaign_name_, form_id_, form_name_, 
        is_organic_, platform_, preferred_degree_, need_scholarship_help_
    );
    INSERT INTO student_followup(
        Student_Id, Entry_Date, Next_FollowUp_Date, FollowUp_Difference, Department, 
        Status, User_Id, Branch, Remark, Remark_Id, By_User_Id, Class_Id, Class_Name, 
        DeleteStatus, FollowUP_Time, Actual_FollowUp_Date, Entry_Type, Branch_Name, 
        UserName, ByUserName, Dept_StatusName, Dept_Name, Student,FollowupBranch, FollowUp
    ) VALUES (
        Student_Id_, Now(), followupdate_, 0, Department_Id_, 
        Department_Status_Id_, Login_user_id_, Branch_, '', 0, Login_user_id_, 312, 'New Lead', 
        false, followupdate_,followupdate_, 1, Branch_Name_, 
        To_User_Name_, By_User_Name_, Department_Status_Name_, Department_Name_, Student_Name_,Branch_Name_, Department_FollowUp_
    );    
    SET Student_Followup_Id_ = (SELECT LAST_INSERT_ID());    
    UPDATE Student 
    SET Student_Followup_Id = Student_Followup_Id_,
        Next_FollowUp_Date = followupdate_,
        Status_Id = Department_Status_Id_,
        By_User_Id = Login_user_id_,
        To_User_Id = Login_user_id_,
        Remark = '',
        Remark_Id = 0,
        Followup_Department_Name = Department_Name_,
        Department_Status_Name = Department_Status_Name_,
        To_User_Name = To_User_Name_,
        By_UserName = By_User_Name_,
        FollowUp = Department_FollowUp_,
        Followup_Department_Id = Department_Id_,
        Followup_Branch_Id = Branch_,
        Role_Id = Role_Id_
    WHERE Student_Id = Student_Id_;
    SET ToUser_Name_ = (SELECT User_Details_Name FROM user_details WHERE User_Details_Id = Login_user_id_ AND DeleteStatus = false);  
    SET Notification_Type_Name_ = 'google sheet';
    SET Entry_Type_ = 14;
    SET Notification_Id_ = (SELECT COALESCE(MAX(Notification_Id), 0) + 1 FROM Notification);    
    INSERT INTO Notification (
        Notification_Id, From_User, From_User_Name, To_User, To_User_Name, 
        Status_Id, Status_Name, View_Status, Remark, Entry_Date, 
        Student_Id, Student_Name, DeleteStatus, Description, Entry_Type) 
    VALUES (Notification_Id_, 0, '', Login_user_id_, By_User_Name_,0, '', 1, '', now(), 
        Student_Id_, Student_Name_, false, Notification_Type_Name_, Entry_Type_);    
    SET Notification_Count_ = (SELECT COALESCE(MAX(Notification_Count), 0) + 1 FROM User_Details WHERE User_Details_Id = Login_user_id_);    
    UPDATE User_Details SET Notification_Count = Notification_Count_ WHERE User_Details_Id = Login_user_id_;    
#END IF;
END IF;
SELECT 
    Student_Id_,
    Login_user_id_,
    By_User_Name_,
    Notification_Id_,
    Student_Name_,
    Entry_Type_,
    ToUser_Name_,
    Notification_Type_Name_,
    Student_Name_;
END$$
DELIMITER ;

