DELIMITER $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `save_call_data`(
    IN p_uuid VARCHAR(50),
    IN p_call_to_number VARCHAR(50),
    IN p_caller_id_number VARCHAR(50),
    IN p_hangup_cause VARCHAR(100),
    IN p_direction VARCHAR(20),
    IN p_duration INT,
    IN p_answered_agent VARCHAR(100),
    IN p_answered_agent_name VARCHAR(100),
    IN p_answered_agent_number VARCHAR(50),
    IN p_missed_agent VARCHAR(100),
    IN p_recording_url TEXT,
    IN p_call_status VARCHAR(50),
    IN p_call_id VARCHAR(100),
    IN p_outbound_sec INT,
    IN p_aws_call_recording_identifier VARCHAR(200),
    IN p_customer_no_with_prefix VARCHAR(50),
    IN p_reason_key VARCHAR(100)
)
BEGIN
    DECLARE v_normalized_number VARCHAR(20);
    DECLARE v_student_id INT;
    DECLARE v_student_name VARCHAR(255);
    DECLARE v_followup_id INT;
   
    -- User related fields from user_details
    DECLARE v_department_id INT;
    DECLARE v_department_name VARCHAR(100);
    DECLARE v_role_id BIGINT;
    DECLARE v_branch_id INT;
    DECLARE v_branch_name VARCHAR(100);
    DECLARE v_user_id BIGINT;
    DECLARE v_username VARCHAR(250);
    DECLARE v_status VARCHAR(250);
    DECLARE v_status_type_id INT;
    DECLARE v_status_type_name VARCHAR(100);
    DECLARE v_p_answered_agent_number VARCHAR(50);

    -- Duplicate checking variables (same as Save_Profile)
    DECLARE Duplicate_Student_Id INT; 
    DECLARE Alternate_student_Id INT; 
    DECLARE Whatsap_student_Id INT;
    DECLARE Duplicate_Student_Name VARCHAR(500); 
    DECLARE Duplicate_User_Name VARCHAR(500); 
    DECLARE Duplicate_User_Id INT;
    DECLARE Duplicate_Department_Name VARCHAR(50);
    DECLARE Duplicate_Remark_Name VARCHAR(2000);
    DECLARE Duplicate_Department_Id_ INT;
    DECLARE Duplicate_FollowUp_Date DATETIME;
    DECLARE Duplicate_Message_ TEXT;
    DECLARE Duplicate_type INT;
    DECLARE To_String VARCHAR(100);
    DECLARE Department_Status INT;
    DECLARE Duplicate_Student_Id_Alternate_Phone INT;
    DECLARE Duplicate_Student_Id_Whatsapp INT;

    -- Normalize phone number (+91 / 91 strip and clean)
    SET v_normalized_number = p_call_to_number;
    
    -- Strip leading +91 or 91
    IF LEFT(v_normalized_number, 3) = '+91' THEN
        SET v_normalized_number = SUBSTRING(v_normalized_number, 4);
    ELSEIF LEFT(v_normalized_number, 2) = '91' THEN
        SET v_normalized_number = SUBSTRING(v_normalized_number, 3);
    END IF;
   
    -- Clean phone number - remove spaces, tabs, newlines, and + (same as Save_Profile)
    SET v_normalized_number = REPLACE(REPLACE(REPLACE(REPLACE(v_normalized_number, ' ', ''), '\t', ''), '\n', ''), '+', '');

    -- Log original agent number
    INSERT INTO data_logs VALUES (0, p_answered_agent_number);

    -- Normalize agent number - same as original
    SET v_p_answered_agent_number = p_answered_agent_number;
    SET v_p_answered_agent_number = REPLACE(v_p_answered_agent_number, '+', '');
    SET v_p_answered_agent_number = REPLACE(v_p_answered_agent_number, ' ', '');
    SET v_p_answered_agent_number = REPLACE(v_p_answered_agent_number, '-', '');
    SET v_p_answered_agent_number = REPLACE(v_p_answered_agent_number, '(', '');
    SET v_p_answered_agent_number = REPLACE(v_p_answered_agent_number, ')', '');

    -- Trim leading 91
    IF LEFT(v_p_answered_agent_number, 2) = '91' THEN
        SET v_p_answered_agent_number = SUBSTRING(v_p_answered_agent_number, 3);
    END IF;

    -- Log normalized agent number
    INSERT INTO data_logs VALUES (0, v_p_answered_agent_number);

    -- Duplicate checking logic - EXACTLY same as Save_Profile using LIKE with last 10 digits
    IF v_normalized_number != "" THEN
        -- Check in Phone_Number field
        SET Duplicate_Student_Id = (
            SELECT Student_Id 
            FROM Student 
            WHERE DeleteStatus = FALSE 
              AND (Phone_Number LIKE CONCAT('%', v_normalized_number, '%'))
            LIMIT 1
        );
        
        IF Duplicate_Student_Id > 0 THEN
            SET To_String = " Phone ";
        ELSE
            -- Check in Alternative_Phone_Number field
            SET Duplicate_Student_Id = (
                SELECT Student_Id 
                FROM Student 
                WHERE DeleteStatus = FALSE 
                  AND (Alternative_Phone_Number LIKE CONCAT('%', v_normalized_number, '%'))
                LIMIT 1
            );
            
            IF Duplicate_Student_Id > 0 THEN
                SET To_String = " Alternative ";
            ELSE
                -- Check in Whatsapp field
                SET Duplicate_Student_Id = (
                    SELECT Student_Id 
                    FROM Student 
                    WHERE DeleteStatus = FALSE 
                      AND (Whatsapp LIKE CONCAT('%', v_normalized_number, '%'))
                    LIMIT 1
                );
                
                IF Duplicate_Student_Id > 0 THEN
                    SET To_String = " Whatsapp ";
                END IF;
            END IF;
        END IF;
    END IF;

    -- If duplicate found, populate details
    IF Duplicate_Student_Id > 0 THEN
        SET Duplicate_type = 1;
        SET Duplicate_User_Id = (
            SELECT To_User_Id 
            FROM Student 
            WHERE Student_Id = Duplicate_Student_Id 
              AND DeleteStatus = FALSE
        );
        SET Duplicate_Department_Id_ = (
            SELECT Followup_Department_Id 
            FROM Student 
            WHERE Student_Id = Duplicate_Student_Id 
              AND DeleteStatus = FALSE
        );
        SET Duplicate_FollowUp_Date = (
            SELECT Next_FollowUp_date 
            FROM Student 
            WHERE Student_Id = Duplicate_Student_Id 
              AND DeleteStatus = FALSE
        );
        SET Duplicate_Student_Name = (
            SELECT Student_Name 
            FROM Student 
            WHERE Student_Id = Duplicate_Student_Id 
              AND DeleteStatus = FALSE
        );
        SET Duplicate_User_Name = (
            SELECT User_Details_Name 
            FROM user_details 
            WHERE User_Details_Id = Duplicate_User_Id 
              AND DeleteStatus = FALSE
        );
        SET Duplicate_Department_Name = (
            SELECT Department_Name 
            FROM department 
            WHERE Department_Id = Duplicate_Department_Id_ 
              AND Is_Delete = FALSE
        );
        SET Duplicate_Remark_Name = (
            SELECT Remark 
            FROM student 
            WHERE Student_Id = Duplicate_Student_Id 
              AND DeleteStatus = FALSE
        );
        SET Department_Status = (
            SELECT FollowUp 
            FROM department 
            WHERE Department_Id = Duplicate_Department_Id_ 
              AND Is_Delete = FALSE
        );
        SET Duplicate_Message_ = CONCAT(
            'The Phone Number ', v_normalized_number, 
            ' Already Exist as ', To_String, ' for ', Duplicate_Student_Name,
            ' and is handled by ', Duplicate_User_Name, ' ',
            (DATE_FORMAT(Duplicate_FollowUp_Date, '%d-%m-%Y')),
            ' Department is:', Duplicate_Department_Name,
            ' and Remark is:', Duplicate_Remark_Name
        );
        
        -- Use existing student
        SET v_student_id = Duplicate_Student_Id;
        SET v_student_name = Duplicate_Student_Name;
    ELSE
        -- No duplicate found, check if student exists or create new
        SET v_student_id = NULL;
        SET v_student_name = NULL;
    END IF;

    -- If no duplicate and no existing student, create new student
    IF v_student_id IS NULL THEN
        INSERT INTO student (
            Entry_date,
            Phone_Number,
            Student_Name,
            Student_Status_Id,
            Enquiry_Source_Id,
            Enquiry_Source_Name,
            DeleteStatus
        ) VALUES (
            NOW(6),
            v_normalized_number,
            'New Lead',
            1,
            11,
            'Tata Tele',
            0
        );
        SET v_student_id = LAST_INSERT_ID();
        SET v_student_name = 'New Lead';
    END IF;
   
    -- Get user details from normalized agent number - same as original
    SELECT
        ud.User_Details_Id,
        ud.User_Details_Name,
        ud.Role_Id,
        ud.Branch_Id,
        ud.Department_Id,
        ud.Department_Name,
        ud.Working_Status,
        ud.Default_Application_Status_Id,
        ud.Default_Application_Status_Name
    INTO
        v_user_id,
        v_username,
        v_role_id,
        v_branch_id,
        v_department_id,
        v_department_name,
        v_status,
        v_status_type_id,
        v_status_type_name
    FROM user_details ud
    WHERE ud.Mobile = v_p_answered_agent_number
    LIMIT 1;
    
    SET v_branch_name = (SELECT branch_name FROM branch WHERE branch_id = v_branch_id);

    -- If no record found, fallback to User_Details_Id = 153 - same as original
    IF v_user_id IS NULL THEN
        SELECT
            ud.User_Details_Id,
            ud.User_Details_Name,
            ud.Role_Id,
            ud.Branch_Id,
            ud.Department_Id,
            ud.Department_Name,
            ud.Working_Status,
            ud.Default_Application_Status_Id,
            ud.Default_Application_Status_Name
        INTO
            v_user_id,
            v_username,
            v_role_id,
            v_branch_id,
            v_department_id,
            v_department_name,
            v_status,
            v_status_type_id,
            v_status_type_name
        FROM user_details ud
        WHERE ud.User_Details_Id = 153
        LIMIT 1;
        SET v_branch_name = (SELECT branch_name FROM branch WHERE branch_id = 41);
    END IF;

    -- Insert into student_followup - same as original
    INSERT INTO student_followup (
        Student_Id,
        Entry_date,
        Next_FollowUp_date,
        FollowUp_Difference,
        Class_Id,
        FollowUP_Time,
        Actual_FollowUp_date,
        Entry_Type,
        Remark,
        Department,
        Status,
        User_Id,
        Status_Type_Id,
        Remark_Id,
        By_User_Id,
        Branch,
        Branch_Name,
        UserName,
        ByUserName,
        Dept_StatusName,
        Dept_Name,
        Student,
        FollowUp
    ) VALUES (
        v_student_id,
        NOW(6),
        CURDATE(),
        0,
        0,
        NOW(6),
        NOW(6),
        1,
        CONCAT('Call received. Reason: ', p_reason_key),
        v_department_id,
        v_status,
        v_user_id,
        v_status_type_id,
        NULL,
        v_user_id,
        v_branch_id,
        v_branch_name,
        v_username,
        v_username,
        v_status_type_name,
        v_department_name,
        v_student_name,
        1
    );

    SET v_followup_id = LAST_INSERT_ID();

    -- Update student table - same as original
    UPDATE student
    SET  
        Next_FollowUp_date = CURDATE(),
        Followup_Department_Id = v_department_id,
        Status_Id = v_status,
        To_User_Id = v_user_id,
        To_User_Name = v_username,
        Followup_Branch_Id = v_branch_id,
        Followup_Branch_Name = v_branch_name,
        By_User_Id = v_user_id,
        By_UserName = v_username,
        FollowUp = 1,
        Followup_Department_Name = v_department_name,
        Department_Status_Name = v_status_type_name,
        Role_Id = v_role_id,
        Status_Type_Id = v_status_type_id,
        Status_Type_Name = v_status_type_name,
        Registered_By = v_user_id,
        Registered_On = NOW(6),
        Created_User = v_username,
        Registered_Branch = v_branch_id,
        Created_On = NOW(6),
        Branch_Id = v_branch_id,
        Department_Id = v_department_id,
        Enquiry_Mode_Id = 0,
        Entry_Type = 1,
        First_Followup_Date = NOW(6),
        First_Followup_Status = 1,
        Remark = CONCAT('Call received. Reason: ', p_reason_key),
        Enquiry_Source_Id = 11,
        Enquiry_Source_Name = 'Tata Tele',
		User_Match_Flag=0
    WHERE Student_Id = v_student_id
      AND DeleteStatus = 0;

    -- Insert into call_history - same as original
    INSERT INTO call_history (
        uuid,
        call_to_number,
        caller_id_number,
        hangup_cause,
        direction,
        duration,
        answered_agent,
        answered_agent_name,
        answered_agent_number,
        missed_agent,
        recording_url,
        call_status,
        call_id,
        outbound_sec,
        aws_call_recording_identifier,
        customer_no_with_prefix,
        reason_key,
        Student_Id,
        Student_Name
    ) VALUES (
        p_uuid,
        p_call_to_number,
        p_caller_id_number,
        p_hangup_cause,
        p_direction,
        p_duration,
        p_answered_agent,
        p_answered_agent_name,
        v_p_answered_agent_number,   -- use normalized
        p_missed_agent,
        p_recording_url,
        p_call_status,
        p_call_id,
        p_outbound_sec,
        p_aws_call_recording_identifier,
        p_customer_no_with_prefix,
        p_reason_key,
        v_student_id,
        v_student_name
    );
END$$
DELIMITER ;

DELIMITER $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `Save_Campaign`(
    IN campaign_details_id_ INT,
    IN campaign_id_ VARCHAR(255),
    IN campaign_name_ VARCHAR(255),
    IN Branch_Id_ INT,
    IN Department_Id_ INT,
    IN to_user_id_ INT,
    IN Enquiry_Source_Id_ INT,
    IN Department_Status_Id_ INT,
    IN form_id_ VARCHAR(255),
    IN form_name_ VARCHAR(255),
    IN procedure_name_ VARCHAR(255),
    IN To_User_Name_ VARCHAR(100),
    IN FollowUp_ TINYINT UNSIGNED,
    IN FollowUp_Id_ INT
)
BEGIN
    DECLARE Branch_Name_ VARCHAR(255);
    DECLARE Department_Name_ VARCHAR(255);
    DECLARE Department_Status_Name_ VARCHAR(100);
    DECLARE Enquiry_Source_Name_ VARCHAR(255);
    
    SELECT Branch_Name INTO Branch_Name_ FROM branch WHERE Branch_Id = Branch_Id_;
    SELECT Department_Name INTO Department_Name_ FROM department WHERE Department_Id = Department_Id_;
    SELECT Department_Status_Name INTO Department_Status_Name_ FROM department_status WHERE Department_Status_Id = Department_Status_Id_;
    SELECT Enquiry_Source_Name INTO Enquiry_Source_Name_ FROM enquiry_source WHERE Enquiry_Source_Id = Enquiry_Source_Id_;
    
    IF campaign_details_id_ > 0 THEN
        UPDATE campaign_details SET
            campaign_id = campaign_id_,
            campaign_name = campaign_name_,
            Branch_Id = Branch_Id_,
            Branch_Name = Branch_Name_,
            Department_Id = Department_Id_,
            Department_Name = Department_Name_,
            to_user_id = to_user_id_,
            To_User_Name = To_User_Name_,
            Enquiry_Source_Id = Enquiry_Source_Id_,
            Enquiry_Source_Name = Enquiry_Source_Name_,
            Department_Status_Id = Department_Status_Id_,
            Department_Status_Name = Department_Status_Name_,
            form_id = form_id_,
            form_name = form_name_,
            procedure_name = procedure_name_,
            FollowUp = FollowUp_,
            FollowUp_Id = FollowUp_Id_
        WHERE campaign_details_id = campaign_details_id_;
    ELSE
        INSERT INTO campaign_details(
            campaign_id,
            campaign_name,
            Branch_Id,
            Branch_Name,
            Department_Id,
            Department_Name,
            to_user_id,
            To_User_Name,
            Enquiry_Source_Id,
            Enquiry_Source_Name,
            Department_Status_Id,
            Department_Status_Name,
            form_id,
            form_name,
            procedure_name,
            FollowUp,
            FollowUp_Id,
            Entry_Date
        ) VALUES (
            campaign_id_,
            campaign_name_,
            Branch_Id_,
            Branch_Name_,
            Department_Id_,
            Department_Name_,
            to_user_id_,
            To_User_Name_,
            Enquiry_Source_Id_,
            Enquiry_Source_Name_,
            Department_Status_Id_,
            Department_Status_Name_,
            form_id_,
            form_name_,
            procedure_name_,
            FollowUp_,
            FollowUp_Id_,
            NOW()
        );
        
        SET campaign_details_id_ = LAST_INSERT_ID();
    END IF;
    
    SELECT campaign_details_id_ AS campaign_Id_;
END$$
DELIMITER ;

DELIMITER $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `Save_Cas_Followup`( In Student_Task_Id_ int,Task_Status_ int,Student_Id_ int,Status_Name_ varchar(25),Remark_ varchar(2000),Followup_Date_ date,To_User_ int,To_User_Name_ varchar(200),Task_Item_Id_ int,Task_Group_Id_ int)
Begin
declare Student_Task_Followup_Id_ int;declare Department_Id_ int;declare Student_Name_ varchar(100); declare Notification_Id_ int;declare Notification_Count_ int;
declare Notification_Type_Name_ varchar(20);declare Entry_Type_ int;declare Task_Count_ int;
declare By_User_Id_ int;declare By_User_Name_ varchar(100);declare Cur_Date_ date;
set Cur_Date_=CURDATE() ;
set Department_Id_ = (select Department_Id from user_details where User_Details_Id = To_User_);
set Student_Name_ = (select Student_Name from Student where Student_Id = Student_Id_);
if Student_Task_Id_>0 then
  update Student_Task set Student_Task_Id=Student_Task_Id_,Student_Id=Student_Id_,Student_Name=Student_Name_,Followup_Date=Followup_Date_,
To_User_Name=To_User_Name_,Task_Status=Task_Status_,Status_Name=Status_Name_,Remark=Remark_,To_User=To_User_,Task_Item_Id=Task_Item_Id_,Task_Group_Id=Task_Group_Id_ where
Student_Task_Id=Student_Task_Id_ ;
 else
 SET Student_Task_Id_ = (SELECT  COALESCE( MAX(Student_Task_Id ),0)+1 FROM Student_Task);
INSERT INTO Student_Task(Student_Task_Id,Student_Id,Student_Name,Followup_Date,To_User_Name,Task_Status,Status_Name,Remark,To_User,Task_Item_Id,Department_Id,DeleteStatus,Task_Group_Id,Entry_date )
values (Student_Task_Id_,Student_Id_,Student_Name_,Followup_Date_,To_User_Name_,Task_Status_,Status_Name_,Remark_,To_User_,Task_Item_Id_,Department_Id_,false,Task_Group_Id_,now());
end if;
SET Student_Task_Followup_Id_ = (SELECT  COALESCE( MAX(Student_Task_Followup_Id ),0)+1 FROM Student_Task_Followup);
INSERT INTO Student_Task_Followup(Student_Task_Followup_Id,Student_Task_Id,Student_Id,Student_Name,Followup_Date,To_User_Name,Task_Status,Status_Name,Remark,To_User,Task_Item_Id,DeleteStatus, Entry_date)
values (Student_Task_Followup_Id_,Student_Task_Id_,Student_Id_,Student_Name_,Followup_Date_,To_User_Name_,Task_Status_,Status_Name_,Remark_,To_User_,Task_Item_Id_,false,now());
set Task_Count_ = (select count(Student_Task_Id) as Student_Task_Count from Student_Task  where DeleteStatus=0
and Student_Task.Task_Status =1 and To_User =To_User_ and
 date(Student_Task.Followup_Date) <= Cur_Date_ );
if Task_Status_ =2 then
set By_User_Id_= (select By_User_Id from Student_Task where Student_Task_Id = Student_Task_Id_ and DeleteStatus=false);
set By_User_Name_ =(select By_User_Name from Student_Task where Student_Task_Id = Student_Task_Id_ and DeleteStatus=false);
set Notification_Type_Name_ = 'Task Completed';
set Entry_Type_ = 12;
 SET Notification_Id_ = (SELECT  COALESCE( MAX(Notification_Id ),0)+1 FROM Notification);
insert into Notification (Notification_Id,From_User,From_User_Name,To_User,To_User_Name,Status_Id,Status_Name,View_Status,Remark,Entry_Date,Student_Id,Student_Name,DeleteStatus,Description,Entry_Type)
values(Notification_Id_,To_User_,To_User_Name_,By_User_Id_,By_User_Name_,Task_Status_,Status_Name_,1,Remark_,now(),Student_Id_,Student_Name_,false,Notification_Type_Name_,Entry_Type_);

set Notification_Count_ = (SELECT  COALESCE( MAX(Notification_Count ),0)+1 FROM User_Details where User_Details_Id = To_User_);    
update User_Details set Notification_Count = Notification_Count_ where User_Details_Id=To_User_;
end if;
 select Student_Task_Id_,Student_Name_,To_User_Name_,Notification_Type_Name_,Entry_Type_,By_User_Id_,Notification_Id_,Student_Id_,Task_Status_,Task_Count_,To_User_;
 End$$
DELIMITER ;

