declare New_Task_ tinyint default 0;
set Cur_Date_=CURDATE() ;
#set Department_Id_ = (select Department_Id from user_details where User_Details_Id = To_User_);
set Student_Name_ = (select Student_Name from Student where Student_Id = Student_Id_);
set Round_Robin_Check_ =(select Round_Robin from application_settings);

if Round_Robin_Check_=1 then
-- round robin --
set To_User_ = (select   COALESCE( MAX(User_Id) ,0)  from student_followup where Student_Id=Student_Id_ and Department = Department_Id_ );


if To_User_>0 then
	set First_Time_Dept_ = 0;
else
	set First_Time_Dept_ = 1;
end if;

if To_User_ = 0 then
	set CreatedBy_Id_ =  (select COALESCE( MAX(Created_By) ,0) from  student where  Student_Id=Student_Id_);
    set CreatedBy_Dept_ = (select COALESCE( MAX(Department_Id) ,0) from  user_details where  User_Details_Id = CreatedBy_Id_);
    if CreatedBy_Dept_ = Department_Id_ then
		set To_User_ = CreatedBy_Id_;
	end if;
    
end if;

#insert into  data_log_ values (0,To_User_,'tr');
#set Department_Status_Id_=(select Department_Status_Id from department where Department_Id=Department_Id_);
select Department_Status_Id,Total_User,Current_User_Index,Department_Name,FollowUp,Color_Type_Name into
Department_Status_Id_,Total_User_,Sub_User_ ,Department_Name_,Department_FollowUp_,Color_Type_Name_
from department where Department_Id=Department_Id_ ;
#set Department_FollowUp_ = (select Followup from department_status where Department_Status_Id=Transfer_Status_Id_);
 
 #insert into data_log_ values(0,'1',Department_Id_);    
set Department_Status_Name_=(select Department_Status_Name from department_status where Department_Status_Id=Department_Status_Id_);
#insert into  data_logs values (0,Department_Status_Name_);
select Working_Status,Backup_User_Id
into Working_Status_,Backup_User_
from user_details  where User_Details_Id=To_User_ ;

if (To_User_>0) then

   # set Working_Status_ =( select Working_Status from user_details where User_Details_Id=To_User_);
    set Backup_User_=( select Backup_User_Id from user_details where User_Details_Id=To_User_);
	if Working_Status_=3 or Working_Status_=2  then
		set To_User_ = Backup_User_;
	end if;
#insert into  data_log_ values (0,To_User_,'');
else
	#set Sub_User_ =( select department.current_user from department where Department_Id=Department_Id_);
	set To_User_=(select COALESCE( MAX(User_Details_Id) ,0)   from user_details where Sub_Slno=Sub_User_ and Department_Id=Department_Id_ );
	#insert into  data_logs values(1,To_User_);  
	if  (ISNULL(To_User_) or To_User_=0) then
		SET To_User_ = -1;
	else    
		   
	if Total_User_=Sub_User_ then
		set Sub_User_=1;
	else
		set Sub_User_=Sub_User_+1;
					 
	end if;
   # insert into  data_log_ values (0,Sub_User_,Total_User_);
	update department set Current_User_Index =Sub_User_  where Department_Id=Department_Id_;
    
 
end if;

end if;

-- round robin --

   set To_User_Name_ =(select User_Details_Name  from user_details where User_Details_Id=To_User_  );
end if;   
if(To_User_ <> -1) then

if Student_Task_Id_>0 then
set New_Task_ = 1;
update Student_Task set Student_Task_Id=Student_Task_Id_,Student_Id=Student_Id_,
Student_Name=Student_Name_,
Followup_Date=Followup_Date_,
To_User_Name=To_User_Name_,
To_User=To_User_,Task_Group_Id=Task_Group_Id_,
Department_Name=Department_Name_,Department_Id=Department_Id_,
Task_Details=Task_Details_,Remark=Remark_,Task_Status=Task_Status_,
Status_Name=Status_Name_,Task_Item_Id=Task_Item_Id_,
By_User_Id=By_User_Id_,By_User_Name=By_User_Name_,Branch_Id=Branch_Id_,Branch_Name=Branch_Name_
 where Student_Task_Id=Student_Task_Id_ ;
 else
 SET Student_Task_Id_ = (SELECT  COALESCE( MAX(Student_Task_Id ),0)+1 FROM Student_Task);
INSERT INTO Student_Task(Student_Task_Id,Student_Id,Student_Name,To_User_Name,To_User,Department_Id,DeleteStatus,Task_Group_Id,Entry_date,Department_Name,Task_Details,Followup_Date,Remark,Task_Status,Status_Name,Task_Item_Id,By_User_Id,By_User_Name,Branch_Id,Branch_Name )
values (Student_Task_Id_,Student_Id_,Student_Name_,To_User_Name_,To_User_,Department_Id_,false,Task_Group_Id_,now(),Department_Name_,Task_Details_,Followup_Date_,Remark_,Task_Status_,Status_Name_,Task_Item_Id_,By_User_Id_,By_User_Name_,Branch_Id_,Branch_Name_);
end if;
SET Student_Task_Followup_Id_ = (SELECT  COALESCE( MAX(Student_Task_Followup_Id ),0)+1 FROM Student_Task_Followup);
INSERT INTO Student_Task_Followup(Student_Task_Followup_Id,Student_Task_Id,Student_Id,
Student_Name,To_User_Name,To_User,DeleteStatus,
 Entry_date,Department_Id,Department_Name,Followup_Date,Status_Name,Remark,Task_Item_Id,By_User_Id,By_User_Name,Branch_Id,Branch_Name,Task_Details)
values (Student_Task_Followup_Id_,Student_Task_Id_,Student_Id_,Student_Name_,To_User_Name_,
To_User_,false,now(),Department_Id_,Department_Name_,Followup_Date_,Status_Name_,Remark_,Task_Item_Id_,By_User_Id_,By_User_Name_,Branch_Id_,Branch_Name_,Task_Details_);

#set Branch_ =(SELECT Branch_Id FROM user_details where User_Details_Id = To_User_);
#set Branch_Name_ =(SELECT Branch_Name FROM branch where Branch_Id = Branch_);
