CREATE DEFINER=`root`@`localhost` PROCEDURE `Save_Commmission`(
    IN Commission_Id_ INT,
    IN Commission_Name_ VARCHAR(45)
)
BEGIN
    IF Commission_Id_ > 0 THEN
        -- Update existing commission
        UPDATE Commission
        SET Commission_Name = Commission_Name_
        WHERE Commission_Id = Commission_Id_;
    ELSE
        -- Insert new commission
        SET Commission_Id_ = (SELECT COALESCE(MAX(Commission_Id), 0) + 1 FROM Commission);
        INSERT INTO Commission (Commission_Id, Commission_Name, DeleteStatus) 
        VALUES (Commission_Id_, Commission_Name_, FALSE);
    END IF;

    -- Return the Commission_Id_
    SELECT Commission_Id_;
END$$
DELIMITER ;

