 SET Duration_Name_=(Select Duration_Name from duration where Duration_Id = Duration_Id_ );
 #SET IELTS_=(Select Ielts_Name from ielts where Minimum_Score = Ielts_Minimum_Score_ );
 INSERT INTO Course(Course_Id ,
Course_Name ,
