CREATE DEFINER=`root`@`localhost` PROCEDURE `Save_Department`( In Department_Id_ int,
Department_Name_ varchar(50),
FollowUp_ TInyint,
Status_ varchar(50),
Department_Order_ int,
Color_ varchar(50),Department_Status_Id_ int,Transfer_Method_Id_ int,
Color_Type_Id_ int,Color_Type_Name_ varchar(45),
Status_Selection JSON)
Begin 
 DECLARE Status_Id_ int; 
DECLARE i int  DEFAULT 0;
	

    
 if  Department_Id_>0
  THEN 
	delete from Status_Selection where Department_Id=Department_Id_;
   
	UPDATE Department set Department_Id = Department_Id_ ,
	Department_Name = Department_Name_ ,
	FollowUp = FollowUp_ ,
	Status = Status_ ,
	Department_Order = Department_Order_ ,Department_Status_Id=Department_Status_Id_,Transfer_Method_Id=Transfer_Method_Id_,
	Color = Color_ ,Color_Type_Id=Color_Type_Id_,
    Color_Type_Name=Color_Type_Name_
    Where Department_Id=Department_Id_ ;
    update student set Followup_Department_Name = Department_Name_ where Followup_Department_Id = Department_Id_;
    update student set Color = Color_Type_Name_ where Followup_Department_Id = Department_Id_;
    update department_status set Transfer_Department_Name = Department_Name_ where Transfer_Department_Id = Department_Id_;
	ELSE 
	SET Department_Id_ = (SELECT  COALESCE( MAX(Department_Id ),0)+1 FROM Department); 
	INSERT INTO Department(Department_Id ,Department_Name ,FollowUp ,Status ,Department_Order ,
	Color ,Department_Status_Id,Current_User_Index,Total_User,Transfer_Method_Id,Is_Delete,Color_Type_Id,Color_Type_Name ) 
	values (Department_Id_ ,Department_Name_ ,FollowUp_ ,Status_ ,Department_Order_ ,Color_ ,Department_Status_Id_,1,0,
    Transfer_Method_Id_,false,Color_Type_Id_,Color_Type_Name_);
End If ;

WHILE i < JSON_LENGTH(Status_Selection) DO
	SELECT JSON_UNQUOTE (JSON_EXTRACT(Status_Selection,CONCAT('$[',i,'].Department_Status_Id'))) INTO Status_Id_;
	INSERT INTO Status_Selection(Department_Id ,Status_Id,Is_Delete )
	values (Department_Id_ ,Status_Id_,false);  
	SELECT i + 1 INTO i;
END WHILE;     
#COMMIT;

select Department_Id_;
#select Status_Id_;
 End$$
DELIMITER ;

DELIMITER $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `Save_Department_Status`(
  IN Department_Status_Id_ INT,
  Department_Status_Name_ VARCHAR(50),
  Status_Order_ INT,
  Editable_ TINYINT,
  Color_ VARCHAR(50),
  Status_Type_Id_ INT,
  Transfer_Status_ TINYINT,
  Notification_Status_ TINYINT,
  Notification_Department_Id_ INT,
  Notification_Department_Name_ VARCHAR(45),
  Transfer_Department_Id_ INT,
  Transfer_Department_Name_ VARCHAR(45),
  Status_Type_Name_ VARCHAR(250),
  FollowUp_ TINYINT,
  Registration_ TINYINT,
  Display_In_ INT,
  Class_Id_ INT,
  Class_Name_ TEXT,
  Class_Order_ INT,
  Registration_Mandatory_ TINYINT,
  Update_in_Profile_ TINYINT,
  Duration_ TINYINT,
  Send_Mail_ TINYINT,

 
  Send_Student_Mail_ TINYINT,
  Send_Staff_Mail_ TINYINT,
  Student_Email_Template_Id_ INT,
  Student_Email_Template_Name_ VARCHAR(100),
  Staff_Email_Template_Id_ INT,
  Staff_Email_Template_Name_ VARCHAR(100),
  Selected_Department_ VARCHAR(100),
  Send_BDM_Mail_ TINYINT,
  Send_Branch_Head_Mail_ TINYINT,
  Selected_Department_Id_ int
)
BEGIN
  IF Transfer_Status_ = 0 THEN
    SET Transfer_Department_Id_ = 0;
    SET Transfer_Department_Name_ = "";
  END IF;

  IF Class_Id_ = 0 THEN
    SET Class_Name_ = "";
  END IF;

  IF Department_Status_Id_ > 0 THEN
    UPDATE Department_Status SET
      Department_Status_Id = Department_Status_Id_,
      Department_Status_Name = Department_Status_Name_,
      Status_Order = Status_Order_,
      Editable = Editable_,
      Color = Color_,
      Status_Type_Id = Status_Type_Id_,
      Status_Type_Name = Status_Type_Name_,
      Transfer_Status = Transfer_Status_,
      Notification_Status = Notification_Status_,
      Notification_Department_Id = Notification_Department_Id_,
      Notification_Department_Name = Notification_Department_Name_,
      Transfer_Department_Id = Transfer_Department_Id_,
      Transfer_Department_Name = Transfer_Department_Name_,
      Followup = FollowUp_,
      Registration = Registration_,
      Display_In = Display_In_,
      Class_Id = Class_Id_,
      Class_Name = Class_Name_,
      Class_Order = Class_Order_,
      Registration_Mandatory = Registration_Mandatory_,
      Update_in_Profile = Update_in_Profile_,
      Duration = Duration_,
      Send_Mail = Send_Mail_,
      Send_Student_Mail = Send_Student_Mail_,
      Send_Staff_Mail = Send_Staff_Mail_,
      Student_Email_Template_Id = Student_Email_Template_Id_,
      Student_Email_Template_Name = Student_Email_Template_Name_,
      Staff_Email_Template_Id = Staff_Email_Template_Id_,
      Staff_Email_Template_Name = Staff_Email_Template_Name_,
      Selected_Department = Selected_Department_,
      Send_BDM_Mail = Send_BDM_Mail_,
      Send_Branch_Head_Mail = Send_Branch_Head_Mail_,
      Selected_Department_Id = Selected_Department_Id_
      
    WHERE Department_Status_Id = Department_Status_Id_;

    UPDATE student SET Department_Status_Name = Department_Status_Name_ WHERE Status_Id = Department_Status_Id_;
    UPDATE student SET Followup = FollowUp_ WHERE Status_Id = Department_Status_Id_;

    -- class update
    UPDATE student SET Class_Id = Class_Id_, Class_Name = Class_Name_, Class_Order = Class_Order_ WHERE Status_Id = Department_Status_Id_;
    UPDATE student_followup SET Class_Id = Class_Id_, Class_Name = Class_Name_, Class_Order = Class_Order_ WHERE Status = Department_Status_Id_;
    UPDATE application_details SET Class_Id = Class_Id_, Class_Name = Class_Name_, Class_Order = Class_Order_ WHERE Application_status_Id = Department_Status_Id_;
    UPDATE application_details_history SET Class_Id = Class_Id_, Class_Name = Class_Name_, Class_Order = Class_Order_ WHERE Application_status_Id = Department_Status_Id_;

  ELSE
    SET Department_Status_Id_ = (SELECT COALESCE(MAX(Department_Status_Id), 0) + 1 FROM Department_Status);

    INSERT INTO Department_Status (
      Department_Status_Id,
      Department_Status_Name,
      Status_Order,
      Editable,
      Color,
      Is_Delete,
      Status_Type_Id,
      Status_Type_Name,
      Notification_Department_Id,
      Notification_Department_Name,
      Transfer_Department_Id,
      Transfer_Department_Name,
      Transfer_Status,
      Notification_Status,
      Followup,
      Registration,
      Display_In,
      Class_Id,
      Class_Name,
      Class_Order,
      Registration_Mandatory,
      Update_in_Profile,
      Duration,
      Send_Mail,
      Send_Student_Mail,
      Send_Staff_Mail,
      Student_Email_Template_Id,
      Student_Email_Template_Name,
      Staff_Email_Template_Id,
      Staff_Email_Template_Name,
      Selected_Department,
      Send_BDM_Mail,
      Send_Branch_Head_Mail,
      Selected_Department_Id
    ) VALUES (
      Department_Status_Id_,
      Department_Status_Name_,
      Status_Order_,
      Editable_,
      Color_,
      FALSE,
      Status_Type_Id_,
      Status_Type_Name_,
      Notification_Department_Id_,
      Notification_Department_Name_,
      Transfer_Department_Id_,
      Transfer_Department_Name_,
      Transfer_Status_,
      Notification_Status_,
      FollowUp_,
      Registration_,
      Display_In_,
      Class_Id_,
      Class_Name_,
      Class_Order_,
      Registration_Mandatory_,
      Update_in_Profile_,
      Duration_,
      Send_Mail_,
      Send_Student_Mail_,
      Send_Staff_Mail_,
      Student_Email_Template_Id_,
      Student_Email_Template_Name_,
      Staff_Email_Template_Id_,
      Staff_Email_Template_Name_,
      Selected_Department_,
      Send_BDM_Mail_,
      Send_Branch_Head_Mail_,
      Selected_Department_Id_
    );
  END IF;

  SELECT Department_Status_Id_;
END$$
DELIMITER ;

