CREATE DEFINER=`root`@`localhost` PROCEDURE `Save_Email_Template`(
    IN p_id INT,
    IN p_name VARCHAR(255),
    IN p_subject VARCHAR(255),
    IN p_body TEXT,
    IN p_created_by VARCHAR(50),
    IN p_updated_by VARCHAR(50),
    IN p_attachments JSON,
    IN p_brevo_template_id VARCHAR(255),
    IN p_document_id INT,
    IN p_document_name VARCHAR(255)
)
BEGIN
    DECLARE new_template_id INT;
    DECLARE i INT DEFAULT 0;
    DECLARE attachment_name VARCHAR(255);
    DECLARE attachment_path VARCHAR(500);
    
    IF p_id = 0 THEN
        -- Insert new record
        INSERT INTO email_templates (
            name,
            subject,
            body,
            created_by,
            updated_by,
            created_at,
            updated_at,
            status,
            Delete_Status,
            brevo_template_id,
            document_id,
            document_name
        ) VALUES (
            p_name,
            p_subject,
            p_body,
            p_created_by,
            p_updated_by,
            NOW(),
            NOW(),
            1,
            0,
            p_brevo_template_id,
             p_document_id,
            p_document_name
        );
        SET new_template_id = LAST_INSERT_ID();
    ELSE
        -- Update existing record
        UPDATE email_templates
        SET 
            name = p_name,
            subject = p_subject,
            body = p_body,
            updated_by = p_updated_by,
            updated_at = NOW(),
            brevo_template_id = p_brevo_template_id,
            document_id = p_document_id,
            document_name = p_document_name
        WHERE id = p_id;
        SET new_template_id = p_id;
    END IF;
    
    -- Insert attachments
    DELETE FROM email_template_attachments WHERE template_id = new_template_id;
    
    IF JSON_LENGTH(p_attachments) > 0 THEN
        WHILE i < JSON_LENGTH(p_attachments) DO
            SET attachment_name = JSON_UNQUOTE(JSON_EXTRACT(p_attachments, CONCAT('$[', i, '].name')));
            SET attachment_path = JSON_UNQUOTE(JSON_EXTRACT(p_attachments, CONCAT('$[', i, '].path')));
            INSERT INTO email_template_attachments (
                template_id,
                file_name,
                file_path,
                created_by,
                created_at,
                status,
                delete_status
            ) VALUES (
                new_template_id,
                attachment_name,
                attachment_path,
                p_created_by,
                NOW(),
                1,
                0
            );
            SET i = i + 1;
        END WHILE;
    END IF;
    
    SELECT new_template_id as id;
END$$
DELIMITER ;

DELIMITER $$
