 INSERT INTO enquiry_for(Enquiry_For_Id ,
Enquiry_For_Name,DeleteStatus) 
values (Enquiry_For_Id_ ,
Enquiry_For_Name_,false );
 End If ;
 select Enquiry_For_Id_;
 End$$
