CREATE DEFINER=`root`@`localhost` PROCEDURE `Save_Profile`( In Student_Id_ int,Entry_date_ date,Enquiry_Source_Id_ int,Enquiry_Source_Name_ varchar(100),
Enquiryfor_Id_ int ,Enquirfor_Name_ varchar(45) , Shore_Id_ int , Shore_Name_ varchar(45) , Enquiry_Mode_Id_ int , Enquiry_Mode_Name_ varchar(45) ,
Program_Course_Id_ int ,Program_Course_Name_ varchar(1000) , Country_Id_ int , Country_Name_ varchar(1000) , Marital_Status_Id_ int ,
Marital_Status_Name_ varchar(45) , Passport_Id_ int ,Address1_ varchar(200) , Address2_ varchar(200) , Alternative_Email_ varchar(100) ,
Alternative_Phone_Number_ varchar(45) , Date_of_Marriage_ varchar(45) , Dob_ varchar(45) , Dropbox_Link_ varchar(1000) ,Email_ varchar(100) , 
No_of_Kids_and_Age_ varchar(45) , Passport_No_ varchar(45) , Passport_Todate_ varchar(45) , Passport_fromdate_ varchar(45) , Phone_Number_ varchar(25) , 
Previous_Visa_Rejection_ varchar(1000) ,Reference_ varchar(45) , Spouse_Name_ varchar(45) , Spouse_Occupation_ varchar(45) ,
Spouse_Qualification_ varchar(45) , Student_Name_ varchar(500) , Whatsapp_ varchar(45) ,Branch_ int , Branch_Name_ varchar(50) , By_User_Id_ int ,
By_User_Name_ varchar(45) , Department_ int , Department_FollowUp_ int , Department_Name_ varchar(50) , Department_Status_Name_ varchar(50) ,
Next_FollowUp_Date_ datetime ,Remark_ varchar(4000) , Remark_id_ int , Status_Id_ int , To_User_Name_ varchar(250) , To_User_Id_ int ,
Student_Status_Id_ int , Agent_Id_ int , Flag_Student_ int , Flag_Followup_ int ,Phone_Change_ int , Email_Change_ int , Alternative_Email_Change_ int ,
Alternative_Phone_Number_Change_ int , Whatsapp_Change_ int , Department_Id_ int , Branch_Id_ int,Unique_Id_ varchar(200),Class_Id_ int,
Class_Name_ varchar(200),Guardian_telephone_ varchar(25),Counsilor_Note_ text,BPH_Note_ text,Pre_Visa_Note_ text,Sub_Status_Id_ int,
Sub_Status_Name_ varchar(100),Status_Type_Id_ int,Status_Type_Name_ varchar(45),Class_Order_ int,Refund_Amount_ varchar(45),Refund_Description_ text,
Spouse_Visa_Id_ int,Spouse_visa_Name_ varchar(45),Duration_ varchar(45),Education_Loan_ tinyint, Loan_Amount_ varchar(45),Loan_Description_ text, 
RoundRobin tinyint,Proceeding_University_Id_ int, Proceeding_University_Name_ varchar(1000),Proceeding_Country_Id_ int,Proceeding_Country_Name_ varchar(500),
DSE_Id_ int,DSE_Name_ varchar(500),Brand_Id_ int,Brand_Name_ varchar(500),Is_TD_Date_ tinyint,TD_Date_ date,Is_HD_Date_ tinyint,HD_Date_ date,
Location_Id_ int,Location_Name_ varchar(500),Enquiry_No_ varchar(1000),Lead_Id_ varchar(500),Transfer_date_ datetime)
Begin
declare Duplicate_Student_Id int;declare Alternate_student_Id int;declare Whatsap_student_Id int;declare Email_Alternate_student_Id int;
declare Old_Class_Order_ int;declare Email_student_Id int;declare First_Time_Status_ int;declare Duplicate_Student_Name varchar(500); 
declare Duplicate_User_Name varchar(500); declare Duplicate_User_Id int;declare Duplicate_Department_Name varchar(50);
declare Duplicate_Remark_Name varchar(2000);declare Duplicate_Department_Id_ int;declare Duplicate_Remark_Id_ int;declare Duplicate_FollowUp_Date datetime;
declare Call_From int;declare Previous_Followup_Date_ datetime;declare Client_Accounts_Id_ int;declare Last_User_Id_ int default 0;
declare Color_Name_ varchar(50);declare Registered_Branch_Name_ varchar(100);declare Registration_Branch_ int;declare closed_temp_user_ int;
declare telesales_temp_user_ int;declare Registration_ tinyint;declare customersuccess_temp_user_ int;declare accounts_temp_user_ int;
declare counsilor_temp_user_ int;declare Old_Department_Order_ int;declare auditor_temp_user_ int;declare admission_temp_user_ int;
declare preadmission_temp_user_ int;declare previsa_temp_user_ int;declare preapplication_temp_user_ int;declare visa_temp_user_ int;
declare To_User_Department int;declare application_temp_user_ int;declare Status_Transfer_Check_ int;declare Old_Registration_Status_ tinyint;
declare Registration_Status_ int;declare status_insertable int;declare Department_Order_ int;DECLARE v_Duration INT DEFAULT 0;DECLARE v_BaseDate DATETIME;
DECLARE v_NextFollowUp DATETIME;declare By_User_Id__New_ int;declare By_User_Name__New_ varchar(500);declare  Duplicate_Student_Id_Alternate_Phone int;
declare Duplicate_Student_Id_Whatsapp int;declare To_String varchar(100); Declare i int default 0;declare Role_Id_ int;declare Student_FollowUp_Id_ int;
declare FollowUp_Difference_ int;declare First_Followup_Status_ int;declare Duplicate_Email_Name varchar(500);declare FollowUp_Count_ int;
declare FollowUp_EntryDate datetime;declare First_FollowUp_Date datetime;declare Duplicate_Message_ text;declare Duplicate_type int;
declare Duplicate_Registration int;declare Duplicate_Welcome_Status int;declare Department_Status int;Declare j int default 0;
declare Created_User_ varchar(100);declare Student_Registration_Id_ int;declare Student_Checklist_Id_ int;declare Check_List_Id_ int;
declare Checklist_Status_ int;declare Description_ Varchar(150);declare Dept_count_ int;declare First_Time_Dept_ tinyint;declare Login_Branch_ int;
declare Status_Transfer_Dept_Id_ int;declare Transfer_User_Id_ int;declare Transfer_Status_ tinyint;declare Max_Class_Order_ int;
declare Registartion_Mandatory_Status_ int;declare Round_Robin_Check_ int;declare Followup_Insertable int;   declare User_Match_Flag_ tinyint;
declare Default_Department_Id_ int;declare Default_Department_Name_ varchar(250);declare Default_User_Id_ int;declare Default_User_Name_ varchar(250);
DECLARE Default_Status_Id_ int;DECLARE Default_Status_Name_ varchar(250);declare User_List_ TEXT;declare alltime_view_ int;declare User_List_1 TEXT;
declare Same_User_ text;declare Application_Exist_ int;declare x int;declare insertable int;declare Notification_Id_ int;declare Notification_Count_ int;
declare Notification_Type_Name_ varchar(45);declare  Notify_ int;declare sfcount_ int;

set x=0;set insertable=0;set status_insertable =0;set Followup_Insertable =0;set closed_temp_user_ =0;set telesales_temp_user_ =0;
set customersuccess_temp_user_ =0;set accounts_temp_user_ =0;set counsilor_temp_user_ =0;set auditor_temp_user_ =0;set admission_temp_user_ =0;
set preadmission_temp_user_ =0;set previsa_temp_user_ =0;set preapplication_temp_user_ =0;set visa_temp_user_ =0;set To_User_Department =0;
set application_temp_user_=0;set Notification_Type_Name_ = 'Student Assigned';set Notify_ = 0;set FollowUp_Count_=1;set sfcount_=0;
SELECT COALESCE(Status_Order, 0) INTO v_Duration FROM Department_Status WHERE Department_Status_Id = Status_Id_;
Set Status_Transfer_Check_ = (select Transfer_Status from department_status where Department_Status_Id= Status_Id_);
Set Status_Transfer_Dept_Id_ = (select Transfer_Department_Id from department_status where Department_Status_Id= Status_Id_);
Set Transfer_Status_ =  (select Transfer_Status from department_status where Department_Status_Id= Status_Id_);
set Transfer_User_Id_ =(select User_Details_Id from user_details where Department_Id= Status_Transfer_Dept_Id_ and DeleteStatus=false limit 1);
Set Registartion_Mandatory_Status_ =  (select Registration_Mandatory from department_status where Department_Status_Id= Status_Id_);
set Registration_Status_ =(select Is_Registered from student where Student_Id= Student_Id_);
set Round_Robin_Check_ =(select Round_Robin from application_settings);

if isnull(Class_Id_) then
	set Class_Id_=(select Class_Id  from student where Student_Id= Student_Id_);
	set Class_Name_=(select Class_Name  from student where Student_Id= Student_Id_);
end if;
SET Program_Course_Name_ = TRIM(Program_Course_Name_);
if(Program_Course_Id_ =-1)then
	SET Program_Course_Id_ = (select COALESCE( MAX(Course_Id ),0) from course where Course_Name=Program_Course_Name_);
	if(Program_Course_Id_ =0)then
		SET Program_Course_Id_ = (SELECT  COALESCE( MAX(Course_Id ),0)+1 FROM course);    
		insert into course(Course_Id,Country_Id,Course_Name, Subject_Id,Duration_Id,Level_Id,Ielts_Minimum_Score,internship_Id,
		IELTS_Name,Sub_Section_Id,DeleteStatus)
		values(Program_Course_Id_,Country_Id_,Program_Course_Name_,0,0,0,0,0,0,0,0);  
	else
		SET Program_Course_Name_ = (select  Course_Name  from course where Course_Id=Program_Course_Id_);
	end if;
 end if;
set Created_User_ =(select User_Details_Name from user_details where User_Details_Id= By_User_Id_);    
set Color_Name_=(select Color_Type_Name from department where Department_Id=Department_);
set Phone_Number_=REPLACE(REPLACE(REPLACE(REPLACE(Phone_Number_, ' ', ''), '\t', ''), '\n', ''), '+', '');
set Role_Id_=(select Role_Id from user_details where User_Details_Id=To_User_Id_);
set Student_FollowUp_Id_ =(SELECT Student_FollowUp_Id from student where Student_Id =Student_Id_);
set Previous_Followup_Date_ =(SELECT Next_FollowUp_Date from student where Student_Id =Student_Id_);
set FollowUp_Difference_= DATEDIFF(Previous_Followup_Date_,now() );
set alltime_view_ = (select count(All_Time_Departments) from all_time_departments where User_Id = By_User_Id_);
SET User_List_1 = (select User_List from student where Student_Id = Student_Id_);
set Default_Department_Id_=(select Default_Department_Id from branch where Branch_Id=Branch_Id_);
set Default_Department_Name_=(select Default_Department_Name from branch where Branch_Id=Branch_Id_);
set Default_Status_Id_=(select Department_Status_Id from department where Department_Id=Default_Department_Id_);
set Default_Status_Name_=(select Department_Status_Name from department_status where Department_Status_Id=Default_Status_Id_);
set Status_Type_Id_=(select Status_Type_Id from department_status where Department_Status_Id=Status_Id_);
set Status_Type_Name_=(select Status_Type_Name from department_status where Department_Status_Id=Status_Id_);
set Dept_count_=(select count( IFNULL(Department,0)) from student_followup where Student_Id=Student_Id_ and Department=Department_);
if(Dept_count_>0) then
	set First_Time_Dept_ =0;
else
	set First_Time_Dept_=1;
end if;
set To_User_Name_=(select User_Details_Name from user_details where User_Details_Id=To_User_Id_);
Set  User_List_ =CONCAT('*',By_User_Id_, '*',',*',To_User_Id_, '*') ;
set Max_Class_Order_=(select MAX(Class_Order) from application_details where Student_Id=Student_Id_ and DeleteStatus=0);
set Class_Order_=Max_Class_Order_;
if(Status_Id_ in(select Status from student_followup where Student_Id = Student_Id_)) then    
	set First_Time_Status_ = (SELECT  COALESCE( MAX(First_Time_Status ),0)+1 FROM student_followup where Student_Id = Student_Id_);
else    
	set First_Time_Status_=0;
end if;

if( Flag_Student_>0) then	
	if  Student_Id_>0 THEN 
		UPDATE Student set Agent_Id=Client_Accounts_Id_,Student_Name = Student_Name_,Address1 = Address1_ ,Address2 = Address2_ ,Email = Email_ ,
        Entry_date=Entry_date_,Alternative_Email = Alternative_Email_ ,Alternative_Phone_Number = Alternative_Phone_Number_ ,Phone_Number = Phone_Number_ ,
		Dob = Dob_ ,Country_Name = Country_Name_ ,Student_Status_Id = Student_Status_Id_,Enquiry_Source_Id = Enquiry_Source_Id_,
		Whatsapp = Whatsapp_ ,Programme_Course=Program_Course_Name_,Reference=Reference_,Passport_No=Passport_No_,Passport_fromdate=Passport_fromdate_,
		Passport_Todate=Passport_Todate_,Passport_Id=Passport_Id_,Enquiry_Source_Name = Enquiry_Source_Name_,Enquiryfor_Id=Enquiryfor_Id_,
		Enquirfor_Name=Enquirfor_Name_,Marital_Status_Id=Marital_Status_Id_,Marital_Status_Name=Marital_Status_Name_,Enquiry_Mode_Id=Enquiry_Mode_Id_,
		Enquiry_Mode_Name=Enquiry_Mode_Name_,Spouse_Name=Spouse_Name_,No_of_Kids_and_Age=No_of_Kids_and_Age_,Date_of_Marriage=Date_of_Marriage_,
		Previous_Visa_Rejection=Previous_Visa_Rejection_,Spouse_Occupation=Spouse_Occupation_,Dropbox_Link=Dropbox_Link_,Program_Course_Id=Program_Course_Id_,
		Profile_Country_Id=Country_Id_,Shore_Id=Shore_Id_,Shore_Name=Shore_Name_,Agent_Id=Agent_Id_,Guardian_telephone=Guardian_telephone_,
		Counsilor_Note=Counsilor_Note_,BPH_Note=BPH_Note_,Pre_Visa_Note=Pre_Visa_Note_,Status_Type_Id=Status_Type_Id_,Status_Type_Name=Status_Type_Name_,
        Refund_Amount=Refund_Amount_,Refund_Description=Refund_Description_,Spouse_Visa_Id = Spouse_Visa_Id_,Followup_Duration = Duration_,
        Education_Loan = Education_Loan_, Loan_Amount = Loan_Amount_, Loan_Description = Loan_Description_,User_Match_Flag=User_Match_Flag_,
        Proceeding_University_Id=Proceeding_University_Id_,Proceeding_University_Name=Proceeding_University_Name_,Proceeding_Country_Id=Proceeding_Country_Id_,
        Proceeding_Country_Name=Proceeding_Country_Name_,Proceeding_Intake_Id=DSE_Id_,Proceeding_Intake_Name=DSE_Name_,Spouse_visa_Name=Spouse_visa_Name_,
        Brand_Id=Brand_Id_,Brand_Name=Brand_Name_,Location_Id=Location_Id_,Location_Name=Location_Name_,Enquiry_No=Enquiry_No_,Lead_Id=Lead_Id_
		Where Student_Id=Student_Id_ ;
	ELSE	
		SET Student_Id_ = (SELECT  COALESCE( MAX(Student_Id ),0)+1 FROM Student);       
		INSERT INTO Student(Student_Id,Agent_Id,Entry_Date,Student_Name,Address1,Address2,Email,Alternative_Email,Phone_Number,Alternative_Phone_Number,
        Dob ,Country_Name ,Student_Status_Id,Enquiry_Source_Id ,Created_By,Whatsapp,DeleteStatus,Is_Registered,FollowUp_Count,FollowUp_EntryDate,Entry_Type,
		First_Followup_Status,First_Followup_Date,Programme_Course,Reference,Passport_No,Passport_fromdate,Passport_Todate,Passport_Id,Enquiry_Source_Name,
		Created_User,Marital_Status_Id,Marital_Status_Name,Program_Course_Id,Profile_Country_Id,Created_On,Enquiryfor_Id,Enquirfor_Name,Shore_Id,Shore_Name,
		Spouse_Name,Date_of_Marriage,Spouse_Occupation,Dropbox_Link,No_of_Kids_and_Age,Previous_Visa_Rejection,Enquiry_Mode_Id,Enquiry_Mode_Name,Branch_Id,
		Department_Id,Visa_User,Pre_Visa_User,Pre_Admission_User,Visa_Rejection_User,Pre_Application_User,Bph_User,Closed_User,Unique_Id,Class_Id,Class_Name,
        Guardian_telephone,Status_Student_Fill,Counsilor_Note,BPH_Note,Pre_Visa_Note,Sub_Status_Id,Sub_Status_Name,Class_Order,Refund_Amount,
        Refund_Description,Max_Class_Id,Max_Class_Name,Max_Department_Id,Max_Department_Name,Max_Status_Id,Max_Status_Name,Spouse_Visa_Id,Followup_Duration,
        Education_Loan,Loan_Amount,Loan_Description,User_Match_Flag,Proceeding_University_Id,Proceeding_University_Name,Proceeding_Country_Id,
        Proceeding_Country_Name,Proceeding_Intake_Id,Proceeding_Intake_Name,Spouse_visa_Name,Brand_Id,Brand_Name,Location_Id,Location_Name,Enquiry_No,Lead_Id)
        
		values (Student_Id_ ,Agent_Id_,Entry_date_,Student_Name_ ,Address1_ ,Address2_ ,Email_ ,Alternative_Email_,Phone_Number_ ,Alternative_Phone_Number_,
        Dob_ ,Country_Name_ ,Student_Status_Id_,Enquiry_Source_Id_ ,By_User_Id_,Whatsapp_,false,0,1,now(),1,1,now(),Program_Course_Name_,Reference_,
        Passport_No_,Passport_fromdate_,Passport_Todate_,Passport_Id_,Enquiry_Source_Name_,Created_User_,Marital_Status_Id_,Marital_Status_Name_,
        Program_Course_Id_,Country_Id_,now(),Enquiryfor_Id_,Enquirfor_Name_,Shore_Id_,Shore_Name_,Spouse_Name_,Date_of_Marriage_,Spouse_Occupation_,
        Dropbox_Link_,No_of_Kids_and_Age_,Previous_Visa_Rejection_,Enquiry_Mode_Id_,Enquiry_Mode_Name_,Branch_Id_,Department_Id_,visa_temp_user_,
        previsa_temp_user_,preadmission_temp_user_,telesales_temp_user_,preapplication_temp_user_,auditor_temp_user_,closed_temp_user_,Unique_Id_,Class_Id_,
        Class_Name_,Guardian_telephone_,0,Counsilor_Note_,BPH_Note_,Pre_Visa_Note_,Sub_Status_Id_,Sub_Status_Name_,Class_Order_,Refund_Amount_,
        Refund_Description_,Class_Id_,Class_Name_,Department_,Department_Name_,Status_Id_,Department_Status_Name_,Spouse_Visa_Id_,Duration_,Education_Loan_,
        Loan_Amount_,Loan_Description_,User_Match_Flag_,Proceeding_University_Id_,Proceeding_University_Name_,Proceeding_Country_Id_,Proceeding_Country_Name_,
        DSE_Id_,DSE_Name_,Spouse_visa_Name_,Brand_Id_,Brand_Name_,Location_Id_,Location_Name_,Enquiry_No_,Lead_Id_);
	end if;
end if;
if( Flag_Followup_>0) then	

    set FollowUp_Count_ = (SELECT COALESCE( MAX(FollowUp_Count ),0)+1 FROM student where Student_Id = Student_Id_);

	INSERT INTO student_followup(Student_Id ,Entry_Date,Next_FollowUp_Date,FollowUp_Difference,Department ,Status ,User_Id ,Branch,Remark,Remark_Id,
	By_User_Id ,DeleteStatus,FollowUP_Time,Actual_FollowUp_Date,Entry_Type,Branch_Name,UserName,ByUserName,Dept_StatusName,Dept_Name,Student,FollowUp,
	Class_Id,Class_Name,Sub_Status_Id,Sub_Status_Name,Status_Type_Id,Status_Type_Name,First_Time_Dept,Class_Order,First_Time_Status,Duration,Is_TD_Date,
	TD_Date,Is_HD_Date,HD_Date,FollowUp_Count)
	values (Student_Id_ ,Now(),Next_FollowUp_Date_,0,Department_ ,Status_Id_ ,To_User_Id_ ,Branch_,Remark_,Remark_Id_,By_User_Id_,false,Now(),Now(),1,
	Branch_Name_,To_User_Name_,By_User_Name_,Department_Status_Name_,Department_Name_,Student_Name_,Department_FollowUp_,Class_Id_,Class_Name_,
	Sub_Status_Id_,Sub_Status_Name_,Status_Type_Id_,Status_Type_Name_,First_Time_Dept_,Class_Order_,First_Time_Status_,Duration_,Is_TD_Date_,
	TD_Date_,Is_HD_Date_,HD_Date_,FollowUp_Count_);
	set Student_FollowUp_Id_ =(SELECT LAST_INSERT_ID());

	Update student set Student_FollowUp_Id=Student_FollowUp_Id_ ,Followup_Department_Id = Department_ ,Status_Id = Status_Id_ ,
	To_User_Id = To_User_Id_ ,By_User_Id=By_User_Id_,Next_FollowUp_Date = Next_FollowUp_Date_ ,Remark = Remark_  ,Remark_Id = Remark_Id_,
	Followup_Branch_Id=Branch_,First_Followup_Status=1,First_Followup_Date=now(),Followup_Department_Name = Department_Name_,
	FollowUp=Department_FollowUp_,Followup_Branch_Name = Branch_Name_,Department_Status_Name=Department_Status_Name_,To_User_Name=To_User_Name_,
	Role_Id=Role_Id_,By_UserName = By_User_Name_,User_List = User_List_,FollowUp_Count = FollowUp_Count_
	where student.Student_Id=Student_Id_;

	SET Notification_Id_ = (SELECT  COALESCE( MAX(Notification_Id ),0)+1 FROM Notification);
	insert into Notification (Notification_Id,From_User,From_User_Name,To_User,To_User_Name,Status_Id,View_Status,Remark,Entry_Date,Student_Id,Student_Name,
    DeleteStatus,Description,Entry_Type)
	values(Notification_Id_,By_User_Id_,By_User_Name_,To_User_Id_,To_User_Name_,Status_Id_,1,Remark_,now(),Student_Id_,Student_Name_,false,
    Notification_Type_Name_,3);
	set Notification_Count_ = (SELECT  COALESCE( MAX(Notification_Count ),0)+1 FROM User_Details where User_Details_Id = To_User_Id_);    
	update User_Details set Notification_Count = Notification_Count_ where User_Details_Id=To_User_Id_;
	set Notify_ = 1;       
end if;	
if(Student_Id_>0)then
	if(Program_Course_Id_=13)then
		update student set Transfer_Date=Transfer_date_ where Student_Id = Student_Id_;
	end if;
	/*if(Program_Course_Id_<>13) then
		update student set Transfer_Date=null where Student_Id = Student_Id_;
