CREATE DEFINER=`root`@`localhost` PROCEDURE `Save_Student1`( In
 Student_Id_ int,
 Client_Accounts_Id_ int,
Student_Name_ varchar(50),
Last_Name_ varchar(50),
Gender_ varchar(50),
Address1_ varchar(50),
Address2_ varchar(50),
