CREATE DEFINER=`root`@`localhost` PROCEDURE `Save_Student_Document`( In Docs_ Json,Document_value_ int)
Begin
DECLARE Student_Id_ int;declare Image_  varchar(500); declare File_Name_  varchar(100);declare Student_Document_Id_ int;
declare Description_  text; Declare i int default 0;DECLARE Document_Id_ int;declare Document_Name_  varchar(100); 

if( Document_value_>0) then
	SELECT JSON_UNQUOTE (JSON_EXTRACT(Docs_,'$.Student_Document_Id')) INTO Student_Document_Id_;
    SELECT JSON_UNQUOTE (JSON_EXTRACT(Docs_,'$.Student_Id')) INTO Student_Id_;
	SELECT JSON_UNQUOTE (JSON_EXTRACT(Docs_,'$.Image')) INTO Image_;
	SELECT JSON_UNQUOTE (JSON_EXTRACT(Docs_,'$.File_Name')) INTO File_Name_;
	SELECT JSON_UNQUOTE (JSON_EXTRACT(Docs_,'$.Description')) INTO Description_;
	SELECT JSON_UNQUOTE (JSON_EXTRACT(Docs_,'$.Document_Id')) INTO Document_Id_;
	SELECT JSON_UNQUOTE (JSON_EXTRACT(Docs_,'$.Document_Name')) INTO Document_Name_;
	#delete from student_document where Student_Id = Student_Id_;
	if(Student_Document_Id_>0)
	then
		if Image_<>''  and  Image_<>'undefined' then
			UPDATE student_document set Image = Image_ Where Student_Document_Id=Student_Document_Id_ ;
		end if;
		UPDATE student_document set Student_Id = Student_Id_ ,Document_Id = Document_Id_,Document_Name = Document_Name_,Description = Description_,File_Name=File_Name_
		Where Student_Document_Id=Student_Document_Id_ ;
	else
		insert into student_document(Student_Id,Entry_date,File_Name,Document_Id,Document_Name,Image,Description,DeleteStatus)
		values (Student_Id_ ,now(),File_Name_,Document_Id_,Document_Name_,Image_,Description_,false);
	end if;
end if;
select Student_Id_;
End$$
DELIMITER ;

DELIMITER $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `Save_Student_FollowUp`(
    IN FollowUp_ JSON,
    IN Student_Id_ INT
)
BEGIN 
    DECLARE Student_FollowUp_Id_ INT;
    DECLARE Department_ INT;
    DECLARE Status_ INT;
    DECLARE User_Id_ INT;
    DECLARE By_User_Id_ INT;
    DECLARE Next_FollowUp_Date_ DATE;
    DECLARE Next_FollowUp_Time_ VARCHAR(10);
    DECLARE Next_FollowUp_DateTime DATETIME;   -- ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã¢â‚¬Â¦ÃƒÂ¢Ã¢â€šÂ¬Ã…â€œÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â¦ new full datetime variable
    DECLARE Remark_Id_ INT;
    DECLARE Remark_ VARCHAR(4000);
    DECLARE Branch_ INT;
    DECLARE Stage_ INT;
    DECLARE Entry_Date_ DATETIME;
    DECLARE FollowUp_Difference_ INT;
    DECLARE Student_Id_J INT;
    DECLARE FollowUP_Time_ DATETIME;
    DECLARE Previous_Followup_Date_ DATETIME;
    DECLARE FollowUp_Count_ INT;
    DECLARE Department_Name_ VARCHAR(50);
    DECLARE Dept_FollowUp_ INT;
    DECLARE Branch_Name_ VARCHAR(50);
    DECLARE Client_Accounts_Name_ VARCHAR(500);
    DECLARE Department_Status_Name_ VARCHAR(50);
    DECLARE User_Details_Name_ VARCHAR(250);
    DECLARE Role_Id_ INT;
    DECLARE By_User_Name_ VARCHAR(100);
    DECLARE Student_n VARCHAR(100);
    DECLARE Created_User_ VARCHAR(100);
    DECLARE Remark_Name_ VARCHAR(200);
    DECLARE Status_Type_Id_ INT;
    DECLARE Status_Type_Name_ VARCHAR(100);
    DECLARE Deparment_Status_Send_Mail_Check TINYINT;
    DECLARE x INT DEFAULT 0;
    DECLARE First_Followup_Status_ INT;
    DECLARE Duplicate_Student_Name VARCHAR(25);
    DECLARE Duplicate_User_Name VARCHAR(25);
	DECLARE User_Match_Flag_ tinyint default 0; 
    -- ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã¢â‚¬Â¦ÃƒÂ¢Ã¢â€šÂ¬Ã…â€œÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â¦ Parse Student Id
    SELECT JSON_UNQUOTE(JSON_EXTRACT(FollowUp_, '$.Student_Id')) INTO Student_Id_J;   
    IF (Student_Id_J > 0) THEN 
        SET Student_Id_ = Student_Id_J;
    END IF;

    -- ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã¢â‚¬Â¦ÃƒÂ¢Ã¢â€šÂ¬Ã…â€œÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â¦ Extract date + time from JSON
    SELECT JSON_UNQUOTE(JSON_EXTRACT(FollowUp_, '$.Next_FollowUp_Date')) INTO Next_FollowUp_Date_;
    SELECT JSON_UNQUOTE(JSON_EXTRACT(FollowUp_, '$.Next_FollowUp_Time')) INTO Next_FollowUp_Time_;

    -- ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã¢â‚¬Â¦ÃƒÂ¢Ã¢â€šÂ¬Ã…â€œÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â¦ Merge into full datetime
    SET Next_FollowUp_DateTime = STR_TO_DATE(CONCAT(Next_FollowUp_Date_, ' ', Next_FollowUp_Time_), '%Y-%m-%d %H:%i:%s');

    -- ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã¢â‚¬Â¦ÃƒÂ¢Ã¢â€šÂ¬Ã…â€œÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â¦ Extract other JSON values
    SELECT JSON_UNQUOTE(JSON_EXTRACT(FollowUp_, '$.Department')) INTO Department_;
    SELECT JSON_UNQUOTE(JSON_EXTRACT(FollowUp_, '$.Status')) INTO Status_;
    SELECT JSON_UNQUOTE(JSON_EXTRACT(FollowUp_, '$.User_Id')) INTO User_Id_;
    SELECT JSON_UNQUOTE(JSON_EXTRACT(FollowUp_, '$.Branch')) INTO Branch_;
    SELECT JSON_UNQUOTE(JSON_EXTRACT(FollowUp_, '$.Remark')) INTO Remark_;
    SELECT JSON_UNQUOTE(JSON_EXTRACT(FollowUp_, '$.Remark_id')) INTO Remark_Id_;
    SELECT JSON_UNQUOTE(JSON_EXTRACT(FollowUp_, '$.By_User_Id')) INTO By_User_Id_;
    SELECT JSON_UNQUOTE(JSON_EXTRACT(FollowUp_, '$.Department_Name')) INTO Department_Name_;
    SELECT JSON_UNQUOTE(JSON_EXTRACT(FollowUp_, '$.Department_FollowUp')) INTO Dept_FollowUp_;
    SELECT JSON_UNQUOTE(JSON_EXTRACT(FollowUp_, '$.Branch_Name')) INTO Branch_Name_;
    SELECT JSON_UNQUOTE(JSON_EXTRACT(FollowUp_, '$.Department_Status_Name')) INTO Department_Status_Name_;
    SELECT JSON_UNQUOTE(JSON_EXTRACT(FollowUp_, '$.Status_Type_Id')) INTO Status_Type_Id_;
    SELECT JSON_UNQUOTE(JSON_EXTRACT(FollowUp_, '$.Status_Type_Name')) INTO Status_Type_Name_;
    SELECT JSON_UNQUOTE(JSON_EXTRACT(FollowUp_, '$.User_Details_Name')) INTO User_Details_Name_;
    SELECT JSON_UNQUOTE(JSON_EXTRACT(FollowUp_, '$.By_User_Name')) INTO By_User_Name_;

    -- Role & Mail check
    SET Role_Id_ = (SELECT Role_Id FROM user_details WHERE User_Details_Id = User_Id_);
    SET Deparment_Status_Send_Mail_Check = (SELECT Send_Mail FROM department_status);

    -- Existing followup
    SET Student_FollowUp_Id_ = (SELECT Student_FollowUp_Id FROM student WHERE Student_Id = Student_Id_);
    SET Previous_Followup_Date_ = (SELECT Next_FollowUp_Date FROM student WHERE Student_Id = Student_Id_);
    SET FollowUp_Difference_ = DATEDIFF(Previous_Followup_Date_, NOW());

    UPDATE student_followup 
    SET Actual_FollowUp_Date = NOW(), FollowUp_Difference = FollowUp_Difference_ 
    WHERE Student_FollowUp_Id = Student_FollowUp_Id_;

    -- Insert into student_followup
    INSERT INTO student_followup(
        Student_Id, Entry_Date, Next_FollowUp_Date, FollowUp_Difference,
        Department, Status, User_Id, Branch, Remark, Remark_Id, By_User_Id,
        FollowUp_Type, DeleteStatus, FollowUP_Time, Actual_FollowUp_Date,
        Entry_Type, Branch_Name, UserName, ByUserName, Dept_StatusName, Dept_Name,
        Student, FollowUp, Status_Type_Id, Status_Type_Name
    ) 
    VALUES (
        Student_Id_, NOW(), Next_FollowUp_DateTime, 0, Department_, Status_, User_Id_, 
        Branch_, Remark_, Remark_Id_, By_User_Id_, 1, FALSE, NOW(), NOW(), 1,
        Branch_Name_, User_Details_Name_, By_User_Name_, Department_Status_Name_,
        Department_Name_, Student_n, Dept_FollowUp_, Status_Type_Id_, Status_Type_Name_
    );

    SET Student_FollowUp_Id_ = LAST_INSERT_ID();
	if By_User_Id_<>User_Id_ then
    set User_Match_Flag_=1;
    else
    set User_Match_Flag_=0;
    end if;
    -- First followup check
    SET First_Followup_Status_ = (SELECT First_Followup_Status FROM Student WHERE Student_Id = Student_Id_);
    IF First_Followup_Status_ = 0 THEN
        UPDATE student 
        SET 
            Student_FollowUp_Id = Student_FollowUp_Id_,
            Department = Department_,
            Status = Status_,
            User_Id = User_Id_,
            By_User_Id = By_User_Id_,
            Next_FollowUp_Date = Next_FollowUp_Date_,
            Next_FollowUp_DateTime = Next_FollowUp_DateTime,
            Remark = Remark_,
            Remark_Id = Remark_Id_,
            Branch = Branch_,
            FollowUp_Count = x + 1,
            First_Followup_Status = 1,
            First_Followup_Date = NOW(),
            Department_Name = Department_Name_,
            FollowUp = Dept_FollowUp_,
            Branch_Name = Branch_Name_,
            Department_Status_Name = Department_Status_Name_,
            User_Details_Name = User_Details_Name_,
            Role_Id = Role_Id_,
            By_UserName = By_User_Name_,
            Status_Type_Id = Status_Type_Id_,
            Status_Type_Name = Status_Type_Name_,
            User_Match_Flag=User_Match_Flag_
        WHERE student.Student_Id = Student_Id_;
    ELSE
        UPDATE student 
        SET 
            Student_FollowUp_Id = Student_FollowUp_Id_,
            Department = Department_,
            Status = Status_,
            User_Id = User_Id_,
            By_User_Id = By_User_Id_,
            Next_FollowUp_Date = Next_FollowUp_Date_,
            Next_FollowUp_DateTime = Next_FollowUp_DateTime,
            Remark = Remark_,
            Remark_Id = Remark_Id_,
            Branch = Branch_,
            FollowUp_Count = x + 1,
            Department_Name = Department_Name_,
            FollowUp = Dept_FollowUp_,
            Branch_Name = Branch_Name_,
            Department_Status_Name = Department_Status_Name_,
            User_Details_Name = User_Details_Name_,
            Role_Id = Role_Id_,
            By_UserName = By_User_Name_,
            Status_Type_Id = Status_Type_Id_,
            Status_Type_Name = Status_Type_Name_,
            User_Match_Flag=User_Match_Flag_
        WHERE student.Student_Id = Student_Id_;
    END IF;

    SELECT Student_Id_, Duplicate_Student_Name, Duplicate_User_Name, Deparment_Status_Send_Mail_Check;

    INSERT INTO data_log_ VALUES (0,'Deparment_Status_Send_Mail_Check',Deparment_Status_Send_Mail_Check);

END$$
DELIMITER ;

