Begin
Declare i int;DECLARE Student_Id_ int;declare x int default 0;declare Student_FollowUp_Id_ int;declare Remark_Id_ int;declare User_List_1 text;
declare import_master_id int default 0;declare Class_Id_ int;declare Class_Name_ varchar(100);declare Master_Id_ int;
declare Department_Status_Name_ varchar(50);declare Department_Name_ varchar(50);declare User_Id_ int;declare User_Name_ varchar(100);
declare User_List_Old_String_ text;declare User_List_New_String_ text;declare User_List_New_String_1 text;declare User_Match_Flag_ tinyint default 0;
declare User_Role_Id_ int;
SET Department_Name_ = (SELECT Department_Name FROM Department WHERE Department_Id = Department_);
SET Department_Status_Name_ = (SELECT Department_Status_Name FROM Department_Status WHERE Department_Status_Id = Status_);
Set i=0;
insert into data_log_ values(0,Student_Selected_Details_,'');

WHILE i < JSON_LENGTH(Student_Selected_Details_) DO
SELECT JSON_UNQUOTE (JSON_EXTRACT(Student_Selected_Details_,CONCAT('$[',i,'].Student_Id'))) INTO Student_Id_;
SELECT JSON_UNQUOTE (JSON_EXTRACT(Student_Selected_Details_,CONCAT('$[',i,'].User_Id'))) INTO User_Id_;
