set User_Role_Id_=(select Role_Id from user_details where User_Details_Id =User_Id_);
set Remark_Id_ = (Select Remark_Id from student where Student_Id = Student_Id_);
if Followup_Date_ = false || Followup_Date_= 0 then
set Next_FollowUp_Date_ = (Select Next_FollowUp_date from student where Student_Id = Student_Id_);
end if;
set Class_Id_ = (Select Class_Id from student where Student_Id = Student_Id_);
set Class_Name_ = (Select Class_Name from student where Student_Id = Student_Id_);

if Remove_Old_User_Value_ =1 then
set  User_List_New_String_ =CONCAT('*',By_User_Id_, '*') ;
set  User_List_New_String_1 =CONCAT(User_List_New_String_,',*',User_Id_, '*') ;
update student set User_List= User_List_New_String_1 where Student_Id = Student_Id_;
else
SET User_List_1 = (select User_List from student where Student_Id = Student_Id_);
if User_List_1!='' then
set  User_List_New_String_ =CONCAT(User_List_1,',*',By_User_Id_, '*',',*',User_Id_, '*') ;
else
set  User_List_New_String_ =CONCAT('*',By_User_Id_, '*',',*',User_Id_, '*') ;
end if;
update student set User_List= User_List_New_String_ where Student_Id = Student_Id_;
end if;
INSERT INTO student_followup(
		Student_Id,
        Entry_Date,
        Next_FollowUp_Date,
        FollowUp_Difference,
        Department,
        Status,
        User_Id,
        Branch,
        By_User_Id,
        Class_Id,
        Class_Name,
		DeleteStatus,
        FollowUP_Time,
        Actual_FollowUp_Date,
        Remark_Id,
        Entry_Type,
        Branch_Name,
        UserName,
        ByUserName,
        Dept_StatusName,
        Dept_Name
        )
values (
	Student_Id_,
    Now(),	
    Next_FollowUp_Date_,
    0,
    Department_,
    Status_,
    User_Id_,
    Branch_,
    By_User_Id_,
    Class_Id_,
    Class_Name_,
    false,
    Now(),
    Now(),
	Remark_Id_,
    3,
    Branch_Name_,
    User_Name_,
    By_User_Name_,
	Department_Status_Name_,
    Department_Name_);
    
set Student_FollowUp_Id_ =(SELECT LAST_INSERT_ID());
if By_User_Id_<>User_Id_ then
set User_Match_Flag_= 1;
else
set User_Match_Flag_= 0;
end if;
Update student set Student_FollowUp_Id=Student_FollowUp_Id_ ,Followup_Department_Id = Department_ ,Status_Id = Status_ ,
To_User_Id = User_Id_ ,By_User_Id=By_User_Id_,Next_FollowUp_date = Next_FollowUp_Date_ ,Remark_Id=Remark_Id_,
Followup_Branch_Id=Branch_,FollowUp_Count=x+1,Followup_Department_Name = Department_Name_,Followup_Branch_Name = Branch_Name_,
Department_Status_Name = Department_Status_Name_,Role_Id = User_Role_Id_,
By_UserName = By_User_Name_,To_User_Name = User_Name_,User_Match_Flag=User_Match_Flag_
where student.Student_Id=Student_Id_;
SELECT i + 1 INTO i;      
END WHILE;
set import_master_id=1;
select Student_Id_;
End$$
