CREATE DEFINER=`root`@`localhost` PROCEDURE `Save_University`(
    IN University_Id_ BIGINT,
    IN University_Name_ VARCHAR(255),
    IN Country_Id_ INT,
    IN Country_Name_ VARCHAR(255),
    IN Initial_Deposit_ VARCHAR(255),
    IN Campus_Location_ VARCHAR(255),
    IN Living_Expense_ VARCHAR(255),
    IN Description_ TEXT,
    IN Part_Time_Availability_ VARCHAR(255)
)
BEGIN
    IF University_Id_ IS NULL OR University_Id_ = 0 THEN
        -- Insert a new university
        INSERT INTO university (
            University_Name,
            Country_Id,
            Country_Name,
            Initial_Deposit,
            Campus_Location,
            Living_Expense,
            Description,
            Part_Time_Availability,
            DeleteStatus
        )
        VALUES (
            University_Name_,
            Country_Id_,
            Country_Name_,
            Initial_Deposit_,
            Campus_Location_,
            Living_Expense_,
            Description_,
            Part_Time_Availability_,
            false  
        );

        -- Return the newly created University_Id
        SELECT LAST_INSERT_ID() AS University_Id_;
    ELSE
        -- Update the existing university
        UPDATE university
        SET 
            University_Name = University_Name_,
            Country_Id = Country_Id_,
            Country_Name = Country_Name_,
            Initial_Deposit = Initial_Deposit_,
            Campus_Location = Campus_Location_,
            Living_Expense = Living_Expense_,
            Description = Description_,
            Part_Time_Availability = Part_Time_Availability_
        WHERE University_Id = University_Id_;

        -- Return the updated University_Id
        SELECT University_Id_ AS University_Id_;
    END IF;
END$$
DELIMITER ;

DELIMITER $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `Save_University_Document`(
    IN Docs_ TEXT,
    IN Document_value_ INT
)
BEGIN
    #DECLARE University_Document_Id_ INT DEFAULT 0;
    DECLARE University_Id_ INT DEFAULT 0;
    DECLARE File_Name_ VARCHAR(500) DEFAULT '';
    DECLARE Description_ TEXT DEFAULT '';
    DECLARE Document_Id_ INT DEFAULT 0;
    DECLARE Document_Name_ VARCHAR(200) DEFAULT '';
    DECLARE Image_ VARCHAR(500) DEFAULT '';
    
    IF Document_value_ = 1 THEN
     #   SET University_Document_Id_ = JSON_UNQUOTE(JSON_EXTRACT(Docs_, '$.University_Document_Id'));
        SET University_Id_ = JSON_UNQUOTE(JSON_EXTRACT(Docs_, '$.University_Id'));
        SET File_Name_ = JSON_UNQUOTE(JSON_EXTRACT(Docs_, '$.File_Name'));
        SET Description_ = JSON_UNQUOTE(JSON_EXTRACT(Docs_, '$.Description'));
        SET Document_Id_ = JSON_UNQUOTE(JSON_EXTRACT(Docs_, '$.Document_Id'));
        SET Document_Name_ = JSON_UNQUOTE(JSON_EXTRACT(Docs_, '$.Document_Name'));
        SET Image_ = JSON_UNQUOTE(JSON_EXTRACT(Docs_, '$.Image'));
        
        IF University_Id_ = 0 THEN
            INSERT INTO university (
                University_Id, 
                File_Name, 
                Description, 
                Document_Id, 
                Document_Name, 
                Image,
                DeleteStatus,
                Entry_Date
            ) VALUES (
                University_Id_, 
                File_Name_, 
                Description_, 
                Document_Id_, 
                Document_Name_, 
                Image_,
                0,
                NOW()
            );
            
            SET University_Id_ = LAST_INSERT_ID();
        ELSE
            UPDATE university 
            SET 
                University_Id = University_Id_,
                File_Name = File_Name_,
                Description = Description_,
                Document_Id = Document_Id_,
                Document_Name = Document_Name_,
                Image = Image_
            WHERE University_Id = University_Id_;
        END IF;
    END IF;
    
    SELECT 
           University_Id_ AS University_Id_;
END$$
