DELIMITER $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `Save_University_Documents`(
    IN Docs_ JSON,
    IN Document_value_ INT
)
BEGIN
    DECLARE University_Id_ INT;
    DECLARE Image_ VARCHAR(500); 
    DECLARE File_Name_ VARCHAR(100);
    DECLARE Description_ TEXT; 
    DECLARE Document_Id_ INT;
    DECLARE Document_Name_ VARCHAR(100);
    DECLARE AWS_Key_ VARCHAR(500);
    DECLARE Original_File_Name_ VARCHAR(255);
    
    IF(Document_value_ > 0) THEN
        SELECT JSON_UNQUOTE(JSON_EXTRACT(Docs_,'$.University_Id')) INTO University_Id_;
        SELECT JSON_UNQUOTE(JSON_EXTRACT(Docs_,'$.Document_Id')) INTO Document_Id_;
        SELECT JSON_UNQUOTE(JSON_EXTRACT(Docs_,'$.Image')) INTO Image_;
        SELECT JSON_UNQUOTE(JSON_EXTRACT(Docs_,'$.File_Name')) INTO File_Name_;
        SELECT JSON_UNQUOTE(JSON_EXTRACT(Docs_,'$.Description')) INTO Description_;
        SELECT JSON_UNQUOTE(JSON_EXTRACT(Docs_,'$.Document_Name')) INTO Document_Name_;
        SELECT JSON_UNQUOTE(JSON_EXTRACT(Docs_,'$.AWS_Key')) INTO AWS_Key_;
        SELECT JSON_UNQUOTE(JSON_EXTRACT(Docs_,'$.Original_File_Name')) INTO Original_File_Name_;
        
        -- Update the university table directly (one document per university)
        UPDATE university SET 
            Document_Id = Document_Id_,
            Document_Name = Document_Name_,
            File_Name = File_Name_,
            AWS_Key = AWS_Key_,
            Original_File_Name = Original_File_Name_,
            Description = Description_,
            Image = Image_,
            Document_Upload_Date = NOW()
        WHERE University_Id = University_Id_;
        
    END IF;
    
    SELECT University_Id_;
END$$
DELIMITER ;

