CREATE DEFINER=`root`@`localhost` PROCEDURE `Search_Application_Count_Track_Report`(
    IN Fromdate_ DATE,
    IN By_User_ INT
)
BEGIN
    DECLARE SearchbyName_Value VARCHAR(2000);
    DECLARE UnionQuery VARCHAR(4000);
    DECLARE Search_Date_ VARCHAR(500);
    DECLARE Search_Date_union VARCHAR(500);
    DECLARE pos1frm INT;
    DECLARE pos1to INT;
    DECLARE pos2frm INT;
    DECLARE pos2to INT;
    DECLARE PageSize INT;

    SET pos1frm = 0;
    SET pos1to = 0;
    SET pos2frm = 0;
    SET pos2to = 0;
    SET PageSize = 10;

    SET SearchbyName_Value = '';
    SET Search_Date_ = '';

    SET @query = CONCAT(
        "SELECT COUNT(Application_Id) AS Count, ",
        "DATE_FORMAT(NOW(), '%H') AS Entry_Hour ",  
        "FROM application_details_history ",
        "WHERE DATE(Entry_Date) = '", Fromdate_, "' ",
        "AND User_Id = '", By_User_, "' ",
        "GROUP BY DATE(Entry_Date) ",
        "ORDER BY Entry_Date ASC"
    );

    PREPARE QUERY FROM @query;
    EXECUTE QUERY;
END$$
