DELIMITER $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `Search_Application_Data`(
    IN Fromdate_ DATE,
    IN Todate_ DATE,
    IN Branch_ INT,
    IN By_User_ INT,
    IN Is_Date_Check_ TINYINT,
    IN Login_User_Id_ INT,
    IN Status_Value INT,
    IN Agent_Id_ INT,
    IN Application_status_Id_ INT,
    IN Intake_Id_ INT,
    IN Intake_Year_Id_ INT,
    IN Country_Id_ INT,
    IN University_Id_ INT,
    IN Is_Active_Check_ TINYINT,
    IN To_User_Id_ INT
   
)
BEGIN
    DECLARE SearchbyName_Value VARCHAR(2000);
    DECLARE UnionQuery VARCHAR(4000);
    DECLARE Search_Date_ VARCHAR(500);
    DECLARE Department_String_ VARCHAR(4000);
    DECLARE SearchbyName_Value_Userlist VARCHAR(2000);
    DECLARE Search_Date_union VARCHAR(500);
    DECLARE pos1frm INT;
    DECLARE pos1to INT;
    DECLARE pos2frm INT;
    DECLARE RoleId_ VARCHAR(100);
    DECLARE pos2to INT;
    DECLARE PageSize INT;
    DECLARE User_Type_ INT;

    SET pos1frm=0;
    SET pos1to=0;
    SET pos2frm=0;
    SET pos2to=0;
    SET PageSize=10;
    SET SearchbyName_Value='';
    SET SearchbyName_Value_Userlist='';
    SET Search_Date_='';
    SET RoleId_ =(SELECT Role_String FROM user_details WHERE User_Details_Id = Login_User_Id_);
    SET Department_String_ = (SELECT Department_String FROM user_details WHERE User_Details_Id = Login_User_Id_);
    SET User_Type_=(SELECT User_Type FROM user_details WHERE User_Details_Id=Login_User_Id_);

    IF Branch_ > 0 THEN
        SET SearchbyName_Value = CONCAT(SearchbyName_Value, " AND user_details.Branch_Id =", Branch_);
    END IF;

    IF By_User_ > 0 THEN
        SET SearchbyName_Value = CONCAT(SearchbyName_Value, " AND application_details_history.User_Id =", By_User_);
    END IF;
    insert into data_log_ value(0,To_User_Id_,'To_User_Id_');
     IF To_User_Id_ > 0 THEN
        SET SearchbyName_Value = CONCAT(SearchbyName_Value, " AND application_details_history.To_User_Id =", To_User_Id_);
    END IF;

    IF Agent_Id_ > 0 THEN
        SET SearchbyName_Value = CONCAT(SearchbyName_Value, " AND application_details_history.Agent_Id =", Agent_Id_);
    END IF;

    IF Application_status_Id_ > 0 THEN
        SET SearchbyName_Value = CONCAT(SearchbyName_Value, " AND application_details_history.Application_status_Id =", Application_status_Id_);
    END IF;

    IF Intake_Id_ > 0 THEN
        SET SearchbyName_Value = CONCAT(SearchbyName_Value, " AND application_details_history.intake_Id =", Intake_Id_);
    END IF;

    IF Intake_Year_Id_ > 0 THEN
        SET SearchbyName_Value = CONCAT(SearchbyName_Value, " AND application_details_history.Intake_Year_Id =", Intake_Year_Id_);
    END IF;

    IF Country_Id_ > 0 THEN
        SET SearchbyName_Value = CONCAT(SearchbyName_Value, " AND application_details_history.Country_Id =", Country_Id_);
    END IF;

    IF University_Id_ > 0 THEN
        SET SearchbyName_Value = CONCAT(SearchbyName_Value, " AND application_details_history.University_Id =", University_Id_);
    END IF;

    IF Is_Active_Check_ = TRUE THEN
        SET SearchbyName_Value = CONCAT(SearchbyName_Value, " AND application_details_history.Activation_Status =", Is_Active_Check_);
    END IF;

    IF Status_Value = 2 THEN
        SET SearchbyName_Value = CONCAT(SearchbyName_Value, " AND application_details_history.Activation_Status = 1");
    ELSEIF Status_Value = 3 THEN
        SET SearchbyName_Value = CONCAT(SearchbyName_Value, " AND application_details_history.Activation_Status = 0");
    END IF;

    #IF User_Type_ = 2 THEN
      #  SET SearchbyName_Value_Userlist = CONCAT(SearchbyName_Value_Userlist, " AND (application_details_history.User_List LIKE '%*", Login_User_Id_, "*%')");
   # END IF;
    IF User_Type_ = 2 THEN
        SET SearchbyName_Value_Userlist = CONCAT(SearchbyName_Value_Userlist, " AND (application_details_history.User_Id =", Login_User_Id_, ")");
    END IF;



    IF Is_Date_Check_ = TRUE THEN
        SET Search_Date_ = CONCAT(" AND DATE(application_details_history.date_Of_Applying) >= '", Fromdate_, "' AND DATE(application_details_history.date_Of_Applying) <= '", Todate_, "'");
        SET Search_Date_union = CONCAT(SearchbyName_Value, " AND application_details_history.date_Of_Applying < '", Fromdate_, "'");
    ELSE
        SET Search_Date_ = "AND 1 = 1";
    END IF;

    SET UnionQuery = "";
    SET @query = CONCAT(
        "SELECT student.Student_Id, student.Student_Name AS Student,student.Phone_Number AS Mobile, Branch.Branch_Name AS Branch, ",
        "user_details.User_Details_Name AS User, application_details_history.Country_Name AS Country, University_Name AS University, ",
        "Course_Name AS Course, intake_Name AS Intake, Intake_Year_Name AS Intake_Year, application_details_history.Remark AS Remark,to_user.User_Details_Name AS To_User_Name ,",
        "department_status.Department_Status_Name AS Status, agent.Agent_Name AS Agent, ",
        "DATE_FORMAT(application_details_history.Date_Of_Applying, '%d-%m-%Y') AS Applied_Date, ",
        "IF(application_details_history.Activation_Status > 0, 'Active', 'Deactive') AS Activation_Status, Created_User, ",
        "(SELECT User_Details_Name FROM user_details WHERE User_Details_Id = application_details_history.To_User_Id) AS To_User,
        (Date_Format(application_details_history.follow_up_date,'%d-%m-%Y ')) As follow_up_date,(Date_Format(application_details_history.Next_FollowUp_Date,'%d-%m-%Y ')) As Next_FollowUp_Date, application_details_history.FollowUp ",
        "FROM student ",
        "INNER JOIN application_details_history ON application_details_history.Student_Id = student.Student_Id ",
        "INNER JOIN user_details ON user_details.User_Details_Id = application_details_history.User_Id ",
        "INNER JOIN Branch ON Branch.Branch_Id = user_details.Branch_Id ",
        "LEFT JOIN agent ON agent.Agent_Id = application_details_history.Agent_Id ",
      " LEFT JOIN  user_details AS to_user ON to_user.User_Details_Id = application_details_history.To_User_Id ",
        "INNER JOIN department_status ON department_status.Department_Status_Id = application_details_history.Application_status_Id ",
        "WHERE student.DeleteStatus = 0 AND application_details_history.DeleteStatus = 0  ",
        SearchbyName_Value, " ", Search_Date_, " ", SearchbyName_Value_Userlist, " ",
        "ORDER BY user_details.User_Details_Id"
    );
/*select @query;AND First_Time_Status = 0*/
insert into data_log_ value(0,@query,'');
  PREPARE QUERY FROM @query;
  EXECUTE QUERY;
END$$
DELIMITER ;

DELIMITER $$
