CREATE DEFINER=`root`@`localhost` PROCEDURE `Search_Application_List`( In Login_User_Id_ Int,Enrolled_Application_Only_View_Permission_ int,
Pointer_Start_ int,Pointer_Stop_ int,Page_Length_ int,Is_View_ int,Department_Id_ int,search_name_ varchar(500),Agent_Id_ int,User_Id_ int
,AIMS_Id_ varchar(45), Today_Click_Flag_ int,Fromdate_ date,Todate_ date,Is_Date_Check_ Tinyint,Application_Country_Id_ int)
Begin
declare Search_Date_ varchar(500);
declare user_type int;declare closedentries varchar(1000);
declare SearchbyName_Value varchar(2000);declare SearchbyPermission_Value varchar(2000);declare Login_User_Department_Id_ int;
declare Current_Date_ date;declare Prefix_ varchar(500);declare Prefix_Query varchar(500);declare Student_Id_ int;
set SearchbyName_Value = "";set SearchbyPermission_Value = "";set Current_Date_ = CURDATE(); set Search_Date_='';
set closedentries="";
select Prefix into Prefix_ from application_settings;
set user_type=(select User_Type from user_details where User_Details_Id=Login_User_Id_);
if(search_name_ != '') then
set Is_Date_Check_=0;
    #SET SearchbyName_Value =concat(SearchbyName_Value," and application_details.FollowUp=",1);
    #set SearchbyName_ = replace(replace(SearchbyName_, '+', ''), ' ', '');
    SET SearchbyName_Value =   CONCAT(SearchbyName_Value, " AND application_details.Student_Name LIKE '%", search_name_ , "%'");    
end if;

select REPLACE(AIMS_Id_, Prefix_, '') into AIMS_Id_;
set Prefix_ = CONCAT("CONCAT('", Prefix_, "', Student_Id) as AIMS_Id");
IF AIMS_Id_ NOT REGEXP '^[0-9]+$' THEN
    SET Student_Id_ = -3;
ELSE
    SET Student_Id_ = AIMS_Id_;
END IF;
INSERT into data_log_ values(0,"AIMS_Id_",AIMS_Id_);

   -- Handle Today's Application filter
IF Today_Click_Flag_ = 1 THEN
    SET SearchbyName_Value = CONCAT(SearchbyName_Value, " AND DATE(application_details.Next_FollowUp_Date) = '", Current_Date_, "'");
    SET SearchbyName_Value = CONCAT(SearchbyName_Value, " AND application_details.To_User_Id = ", Login_User_Id_);  
END IF;

-- Handle Pending Application filter (Flag = 2)
IF Today_Click_Flag_ = 2 THEN
    SET SearchbyName_Value = CONCAT(SearchbyName_Value, " AND application_details.User_Id = ", Login_User_Id_);
END IF;

if Enrolled_Application_Only_View_Permission_>0 then
SET SearchbyPermission_Value =concat(SearchbyPermission_Value," and ifnull(application_details.Is_Entrolled,0) =",1);
end if;



if Is_View_=0 then
SET SearchbyName_Value =concat(SearchbyName_Value," and application_details.To_User_Id =",Login_User_Id_);
end if;

if Department_Id_>0 then
SET SearchbyName_Value =concat(SearchbyName_Value," and application_details.Application_status_Id =",Department_Id_);
end if;

if Application_Country_Id_>0 then
SET SearchbyName_Value =concat(SearchbyName_Value," and application_details.Country_Id =",Application_Country_Id_);
end if;

if Agent_Id_>0 then
SET SearchbyName_Value =concat(SearchbyName_Value," and application_details.Agent_Id =",Agent_Id_);
end if;

if User_Id_>0 then
    SET SearchbyName_Value = concat(SearchbyName_Value, " and application_details.To_User_Id = ", User_Id_);
elseif user_type=0 then
SET SearchbyName_Value = concat(SearchbyName_Value, " and application_details.User_List like '%*",Login_User_Id_,"*%'");
else
SET SearchbyName_Value = concat(SearchbyName_Value, " and application_details.To_User_Id in ( select User_Details_Id from user_details where Branch_Id in(select branch_id from
    user_department where User_Id= ", Login_User_Id_,"))");
end if;


if Is_Date_Check_=true then
    SET SearchbyName_Value = concat(SearchbyName_Value," and application_details.FollowUp=",1);
set Search_Date_=concat( " and date(application_details.Next_FollowUp_Date) >= '", Fromdate_ ,"' and  date(application_details.Next_FollowUp_Date) <= '", Todate_,"'");
ELSE
set Search_Date_= " and 1 =1 ";
end if;

if Student_Id_>0 then
SET SearchbyName_Value =concat(SearchbyName_Value," and application_details.Student_Id =",Student_Id_);
end if;

if Student_Id_=-3 then
SET SearchbyName_Value =concat(SearchbyName_Value," and application_details.Student_Id =",Student_Id_);
end if;

SET Login_User_Department_Id_ =(SELECT  Department_Id  FROM user_details where User_Details_Id=Login_User_Id_);

SET @query = Concat( "select * , ",Prefix_,"  from(SELECT 6 as tp,Application_details_Id ,Student_Id,Country_Id,Application_Source,
Country_Name,University_Id,University_Name,Course_Id,Course_Name,intake_Id,
intake_Name,Intake_Year_Id,Intake_Year_Name,Student_Reference_Id,Application_No,
Date_Of_Applying, (Date_Format(follow_up_date,'%d-%m-%Y')) as Grid_Date ,DATEDIFF( CURDATE(),follow_up_date) as Day_diff,
application_details.Remark,application_details.Class_Name,Agent_Id,Agent_Name,Reference_No,Activation_Status,Course_Fee,
Living_Expense,Preference,Paid_Status,Application_Fees_Paid,Portal_User_Name,application_details.Password,Application_Fees,
Offer_Student_Id,Fees_Payment_Last_Date,by_user.User_Details_Name User,
IFNULL(Feespaymentcheck, 0) as Feespaymentcheck, IFNULL(Offer_Received, 0) as Offer_Received,Duration_Id,
Department_Status.Department_Status_Id as Department_Status_Id,
Department_Status.Department_Status_Name as Department_Status_Name,
Department_Status.Transfer_Status,department_status.Notification_Status,
Department_Status.Notification_Department_Id,department_status.Notification_Department_Name,    
Department_Status.Transfer_Department_Id,department_status.Transfer_Department_Name,
Department_Status.Department_Status_Id as Appstatusid ,Department_Status.Department_Status_Name as AppstatusName,Student_Name,To_User_Id,
Student_Approve_Status.Status_Name as Status_Name_Approval,Bph_Approved_Status,bph_status.Bph_Status_Name as Bph_Status_Name,Student_Approved_Status,Course_Link,user_details.User_Details_Name To_Staff_Name,
Offerletter_Type_Id,Offerletter_Type_Name,CAST(CAST(ROW_NUMBER()OVER(ORDER BY application_details.Application_details_Id DESC )AS UNSIGNED)AS SIGNED)AS RowNo,application_details.Branch_Id,branch.Branch_Name,application_details.Department as Department_Id,department.Department_Name,
(Date_Format(application_details.follow_up_date,'%d-%m-%Y ')) As follow_up_date,(Date_Format(application_details.Next_FollowUp_Date,'%d-%m-%Y ')) As Next_FollowUp_Date, ifnull(application_details.FollowUp,0)FollowUp
From application_details
inner join Department_Status on Department_Status.Department_Status_Id=application_details.Application_status_Id
inner join Student_Approve_Status on Student_Approve_Status.Student_Approve_Status_Id = application_details.Student_Approved_Status
inner join bph_status on bph_status.Bph_Status_Id = application_details.Bph_Approved_Status
inner join user_details  AS by_user ON by_user.User_Details_Id=application_details.Created_User
inner join user_details on user_details.User_Details_Id=application_details.To_User_Id
left join branch on application_details.Branch_Id=branch.Branch_Id
left join department on application_details.Department = department.Department_Id
where  application_details.DeleteStatus=false " ,SearchbyName_Value,SearchbyPermission_Value,Search_Date_,"
order by application_details.Application_details_Id desc) as lds WHERE RowNo >=",Pointer_Start_," AND RowNo<= ",Pointer_Stop_,"
order by  RowNo LIMIT ",Page_Length_ );
#inner join user_department_status on user_department_status.Department_Status_Id=application_details.Department_Status_Id
PREPARE QUERY FROM @query;
#select @query;
insert into data_log_ value(0,@query,'');

#and application_details.Application_status_Id in
#(select Status_Id  from status_selection where Department_Id=",Login_User_Department_Id_,"

EXECUTE QUERY;
End$$
DELIMITER ;

DELIMITER $$
