CREATE DEFINER=`root`@`localhost` PROCEDURE `Search_Brand`(
    IN Brand_Name_ VARCHAR(100),
    IN Default_Department_Id_ INT
)
BEGIN
    SET Brand_Name_ = CONCAT('%', IFNULL(Brand_Name_, ''), '%');

    SELECT
        Brand_Id,
        Brand_Name,
        Default_Department_Id,
