CREATE DEFINER=`root`@`localhost` PROCEDURE `Search_Call_History`(
  IN p_start_date DATETIME,
    IN p_end_date DATETIME,
    IN p_direction VARCHAR(20),          -- optional filter
    IN p_caller_id_number VARCHAR(100),  -- optional search filter
    IN p_agent_name VARCHAR(100),        -- optional search filter
    IN p_student_name VARCHAR(255)       -- optional search filter
)
BEGIN
    SELECT
        call_history_id,
        uuid,
        call_to_number,
        caller_id_number,
        hangup_cause,
        direction,
        duration,
        answered_agent,
        answered_agent_name,
        answered_agent_number,
        missed_agent,
        recording_url,
        call_status,
        call_id,
        outbound_sec,
        aws_call_recording_identifier,
        customer_no_with_prefix,
        reason_key,
        Student_Id,
        Student_Name,
        Entry_Date
    FROM call_history
    WHERE
        -- Date range filter using Entry_Date
        (p_start_date IS NULL OR p_end_date IS NULL
            OR ( DATE_FORMAT(Entry_Date, '%Y%m%d')  >= p_start_date and DATE_FORMAT(Entry_Date, '%Y%m%d')<= p_end_date))

        -- Optional direction filter
        AND (p_direction IS NULL OR direction = p_direction)

        -- Optional caller ID filter
        AND (p_caller_id_number IS NULL OR caller_id_number LIKE CONCAT('%', p_caller_id_number, '%'))

        -- Optional agent name filter
        AND (p_agent_name IS NULL OR answered_agent_name LIKE CONCAT('%', p_agent_name, '%'))

        -- Optional student name filter
        AND (p_student_name IS NULL OR Student_Name LIKE CONCAT('%', p_student_name, '%'))

    ORDER BY call_history_id DESC;
END$$
DELIMITER ;

DELIMITER $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `Search_Campaign`(
    IN campaign_name_search VARCHAR(255),
    IN Branch_Id_ INT,
    IN Department_Id_ INT,
    IN form_id_ VARCHAR(255)
)
BEGIN
    SELECT 
        cd.campaign_details_id,
        cd.campaign_id,
        cd.campaign_name,
        cd.Branch_Id ,
        cd.Branch_Name ,
        cd.Department_Id,
        cd.Department_Name ,
        cd.to_user_id, 
        cd.Enquiry_Source_Id,
        cd.Enquiry_Source_Name ,
        cd.Department_Status_Id,
        cd.Department_Status_Name,
        cd.form_id,
        cd.form_name,
        cd.procedure_name,
        cd.Entry_Date
    FROM 
        campaign_details cd
    WHERE 
		Delete_Status = 0 and
        (campaign_name_search IS NULL 
         OR campaign_name_search = '' 
         OR cd.campaign_name LIKE CONCAT('%', campaign_name_search, '%'))
                 AND (
            Branch_Id_ IS NULL 
            OR Branch_Id_ = 0 
            OR cd.Branch_Id = Branch_Id_
        )
        AND (
            Department_Id_ IS NULL 
            OR Department_Id_ = 0 
            OR cd.Department_Id = Department_Id_
        )
        AND (
            form_id_ IS NULL 
            OR form_id_ = '' 
            OR cd.form_id = form_id_
        )

    ORDER BY 
        cd.campaign_name ASC;
END$$
DELIMITER ;

