CREATE DEFINER=`root`@`localhost` PROCEDURE `Search_Chanel_Department_Typeahead`(
In Branch_Id_ int,
In Login_User_Id_ int,
Department_Name_ Varchar(100))
BEGIN
DECLARE user_department_Id_ int;
set Department_Name_ = Concat( '%',Department_Name_ ,'%');
set user_department_Id_ = (SELECT COUNT(User_Department_Id)
                           FROM user_department
                           WHERE User_Id = Login_User_Id_
                           AND Branch_Id = Branch_Id_
                           AND Transfer_All = 1);
IF user_department_Id_ = 0 OR user_department_Id_ IS NULL THEN
    SELECT DISTINCT
    Department.Department_Id,
    Department.Department_Name,
    Department_Order,
    Department.FollowUp AS Department_FollowUp,
    Department.Department_Status_Id
    FROM Department
    INNER JOIN Branch_Department ON Department.Department_Id = Branch_Department.Department_Id
        AND Branch_Department.Branch_Id = Branch_Id_
    INNER JOIN User_Details ON User_Details.Department_Id = Department.Department_Id
        AND User_Details.User_Details_Id = Login_User_Id_
    WHERE Department.Department_Name LIKE Department_Name_
    AND Department.Is_Delete = false
    ORDER BY Department.Department_Order ASC;
ELSE
    SELECT DISTINCT
    User_Department.Department_Id,
    Department.Department_Name,
    Department_Order,
    Department.FollowUp AS Department_FollowUp,
    Department.Department_Status_Id
    FROM user_department
    INNER JOIN department ON User_Department.Department_Id = Department.Department_Id
   
    WHERE User_Department.Branch_Id = Branch_Id_
    AND User_Department.User_Id = Login_User_Id_
    AND User_Department.Transfer_All = 1
    AND Department.Department_Name LIKE Department_Name_
    AND Department.Is_Delete = false
    ORDER BY Department.Department_Order ASC;
END IF;
END$$
DELIMITER ;

