CREATE DEFINER=`root`@`localhost` PROCEDURE `Search_Country`(
    IN Country_Name_ VARCHAR(100),
    IN Brand_Id_ INT
)
BEGIN
    SET Country_Name_ = CONCAT('%', IFNULL(Country_Name_, ''), '%');

    SELECT
        Country_Id,
        Country_Name,
        Brand_Id,
        Brand_Name
    FROM Country
    WHERE DeleteStatus = FALSE
      AND Country_Name LIKE Country_Name_
      AND (
            Brand_Id_ = 0
            OR Country.Brand_Id = Brand_Id_
          );
END$$
DELIMITER ;

DELIMITER $$
