 End$$
DELIMITER ;

DELIMITER $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `Search_Course`(
    IN Course_Name_ VARCHAR(100),
    IN Level_Id_ INT,
    IN Country_Id_ INT,
    IN Internship_Id_ INT,
    IN Duration_Id_ INT,
    IN University_Id_ INT,
    IN Subject_Id_ INT,
    IN Sub_Section_Id_ INT,
    search_Itnake_Id_ int,
    IN Pointer_Start_ INT,
    IN Pointer_Stop_ INT,
    IN Page_Length_ INT
)
BEGIN
    DECLARE SearchbyName_Value VARCHAR(2000);
    SET SearchbyName_Value = '';

    -- Apply filters dynamically
    IF Course_Name_ != '' THEN
        SET SearchbyName_Value = CONCAT(SearchbyName_Value, " AND Course.Course_Name LIKE '%", Course_Name_, "%'");
    END IF;

    IF Level_Id_ > 0 THEN
        SET SearchbyName_Value = CONCAT(SearchbyName_Value, " AND Course.Level_Id = ", Level_Id_);
    END IF;

    IF Country_Id_ > 0 THEN
        SET SearchbyName_Value = CONCAT(SearchbyName_Value, " AND Course.Country_Id = ", Country_Id_);
    END IF;

    IF Internship_Id_ > 0 THEN
        SET SearchbyName_Value = CONCAT(SearchbyName_Value, " AND Course.Internship_Id = ", Internship_Id_);
    END IF;

    IF Duration_Id_ > 0 THEN
        SET SearchbyName_Value = CONCAT(SearchbyName_Value, " AND Course.Duration_Id = ", Duration_Id_);
    END IF;

    IF University_Id_ > 0 THEN
        SET SearchbyName_Value = CONCAT(SearchbyName_Value, " AND Course.University_Id = ", University_Id_);
    END IF;

    IF Subject_Id_ > 0 THEN
        SET SearchbyName_Value = CONCAT(SearchbyName_Value, " AND Course.Subject_Id = ", Subject_Id_);
    END IF;

    IF Sub_Section_Id_ > 0 THEN
        SET SearchbyName_Value = CONCAT(SearchbyName_Value, " AND Course.Sub_Section_Id = ", Sub_Section_Id_);
    END IF;
    
        IF search_Itnake_Id_ > 0 THEN
        SET SearchbyName_Value = CONCAT(SearchbyName_Value, " AND Course.Course_Id in(select Course_Id from course_intake where  intake_Id= ", search_Itnake_Id_,+')');
    END IF;
    

    -- Build dynamic SQL query
    SET @query = CONCAT(
        "SELECT * FROM (",
            "SELECT * FROM (",
                "SELECT 1 AS tp, ",
                    "Course_Id, Course_Name, Course_Code, ",
                    "CountryName AS Country, UniversityName AS University, ",
                    "DurationName, Level_DetailName, SubjectName, Sub_SectionName, internshipName, ",
                    "Course.Internship_Id, Course.Country_Id, Course.Subject_Id, Course.Sub_Section_Id, Course.University_Id, ",
                    "CAST(CAST(ROW_NUMBER() OVER (ORDER BY Course.Course_Name DESC) AS UNSIGNED) AS SIGNED) AS RowNo ",
                "FROM Course ",
                "WHERE Course.DeleteStatus = FALSE ",
                SearchbyName_Value, " ",
                "ORDER BY Course.Course_Name DESC",
            ") AS lds ",
            "WHERE RowNo >= ", Pointer_Start_, " AND RowNo <= ", Pointer_Stop_, " ",
            "ORDER BY RowNo ",
            "LIMIT ", Page_Length_,
        ") AS t ",
        "UNION ",
        "SELECT 0 AS tp, COUNT(Course_Id) AS Course_Id, ",
            "'' AS Course_Name, '' AS Course_Code, '' AS Country, '' AS University, ",
            "'' AS DurationName, '' AS Level_DetailName, '' AS SubjectName, '' AS Sub_SectionName, '' AS internshipName, ",
            "0 AS Internship_Id, 0 AS Country_Id, 0 AS Subject_Id, 0 AS Sub_Section_Id, 0 AS University_Id, 0 AS RowNo ",
        "FROM Course ",
        "WHERE Course.DeleteStatus = FALSE ",
        SearchbyName_Value, " ",
        "ORDER BY tp DESC"
    );

    -- Prepare and execute the dynamic SQL
    PREPARE QUERY FROM @query;    
    EXECUTE QUERY;

    -- Optional: Uncomment to debug the generated query
    -- SELECT @query;

END$$
DELIMITER ;

DELIMITER $$
