DELIMITER $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `Search_DailyWork_Summary`(
    IN Todate_ DATE,
    IN Login_User_Id_ INT,
    IN Inc_Create_Date_ TINYINT
)
BEGIN

DECLARE Filter_SQL LONGTEXT;
DECLARE Filter_To_SQL LONGTEXT;
DECLARE Filter_by_SQL LONGTEXT;
DECLARE Filter_User_SQL LONGTEXT;
DECLARE Filter_User_Details_SQL LONGTEXT;
DECLARE Filter_department_SQL LONGTEXT;
DECLARE Filter_Create_Date LONGTEXT;

SET Filter_SQL ='';
SET Filter_To_SQL='';
SET Filter_by_SQL='';
SET Filter_User_SQL='';
SET Filter_department_SQL='';
SET Filter_User_Details_SQL='';
SET Filter_Create_Date='';

SET Filter_SQL = CONCAT(
" AND (To_User_Id IN (
   SELECT User_Selection_Id 
   FROM sub_users 
   WHERE User_Id = ",Login_User_Id_,"))"
);

SET Filter_User_Details_SQL = CONCAT(
" AND User_Details_Id IN (
   SELECT User_Selection_Id 
   FROM sub_users 
   WHERE User_Id = ",Login_User_Id_,")"
);

SET Filter_by_SQL = CONCAT(
" AND (By_User_Id = ",Login_User_Id_,
" OR By_User_Id IN (
   SELECT User_Selection_Id 
   FROM sub_users 
   WHERE User_Id = ",Login_User_Id_,"))"
);

IF Inc_Create_Date_ > 0 THEN
SET Filter_Create_Date = CONCAT(
" AND DATE(Created_On)=CURDATE() 
  AND DATE(Entry_date)<>DATE(Created_On)"
);
ELSE
SET Filter_Create_Date = " AND 1=1 ";
END IF;

SET @query = CONCAT(

"SELECT 
o.User_Details_Id,
o.User_Details_Name AS To_Staff,
o.Branch_Name AS Branch,
o.Department_Name AS Channels,

IFNULL(c.Today_Leads,0) AS Today_Leads,
IFNULL(p.Today_Followups,0) AS Today_Followups,
IFNULL(q.Pending_Followups,0) AS Pending_Followups,

(IFNULL(c.Today_Leads,0)+
IFNULL(p.Today_Followups,0)+
IFNULL(q.Pending_Followups,0)) AS Totals

FROM
(
SELECT 
user_details.User_Details_Id,
user_details.User_Details_Name,
branch.Branch_Name,
department.Department_Name

FROM user_details

INNER JOIN branch 
ON branch.Branch_Id=user_details.Branch_Id

INNER JOIN department
ON department.Department_Id=user_details.Department_Id

WHERE user_details.DeleteStatus=0 ",
Filter_User_Details_SQL,"

) o

LEFT JOIN
(
SELECT 
COUNT(Student_Id) Today_Leads,
To_User_Id

FROM student

WHERE Entry_Type=1
AND DeleteStatus=0
AND DATE(Entry_date)='",Todate_,"'
",Filter_SQL,"

GROUP BY To_User_Id

) c ON o.User_Details_Id=c.To_User_Id

LEFT JOIN
(
SELECT 
COUNT(Student_Id) Today_Followups,
By_User_Id

FROM student_followup

WHERE FollowUp=1
AND DeleteStatus=0
AND DATE(Entry_date)='",Todate_,"'
",Filter_by_SQL,"

GROUP BY By_User_Id

) p ON o.User_Details_Id=p.By_User_Id

LEFT JOIN
(
SELECT 
COUNT(Student_Id) Pending_Followups,
To_User_Id

FROM student

WHERE FollowUp=1
AND DeleteStatus=0
AND DATE(Next_FollowUp_date)<'",Todate_,"'
",Filter_SQL,"

GROUP BY To_User_Id

) q ON o.User_Details_Id=q.To_User_Id

");

INSERT INTO data_log_ VALUES(0,@query,'Search_DailyWork_Summary');

PREPARE stmt FROM @query;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

END$$
DELIMITER ;

