CREATE DEFINER=`root`@`localhost` PROCEDURE `Search_Department_User_Typeahead_student`(
    IN Branch_Id_ INT,
    IN Department_Id_ INT,
    IN Login_User_Id_ INT,
     IN Users_Name_ VARCHAR(100)
)
BEGIN
    DECLARE Login_User_Type_ INT;

    -- Prepare search text
    SET Users_Name_ = CONCAT('%', Users_Name_, '%');

    -- Get logged-in user's type
    SELECT User_Type
    INTO Login_User_Type_
    FROM user_details
    WHERE User_Details_Id = Login_User_Id_
      AND DeleteStatus = FALSE
    LIMIT 1;

    -- If user type = 2 → return only logged-in user
    IF Login_User_Type_ = 2 THEN
		select distinct user_details.User_Details_Id,User_Details_Name
		from user_details inner join user_department on user_details.User_Details_Id=user_department.User_Id
		where user_department.Branch_Id=Branch_Id_
		and user_department.Department_Id=Department_Id_
		and user_details.User_Details_Name like Users_Name_  and user_details.DeleteStatus=false 
		and user_details.Working_Status=1 and user_details.Lead_Assigned=0 and user_department.Transfer_All=1
		and User_Details_Id = Login_User_Id_
		ORDER BY User_Details_Name Asc ;
    ELSE
        -- Normal typeahead list
		select distinct user_details.User_Details_Id,User_Details_Name
		from user_details inner join user_department on user_details.User_Details_Id=user_department.User_Id
		where user_department.Branch_Id=Branch_Id_
		and user_department.Department_Id=Department_Id_
		and user_details.User_Details_Name like Users_Name_  and user_details.DeleteStatus=false 
		and user_details.Working_Status=1 and user_details.Lead_Assigned=0 and user_department.Transfer_All=1
		ORDER BY User_Details_Name Asc ;
    END IF;

END$$
DELIMITER ;

