DELIMITER $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `Search_Enquiryfor_Report`(
    IN Login_User_Id_ INT,
    IN Is_Date_ INT,
    IN From_Date_ VARCHAR(20),
    IN To_Date_ VARCHAR(20),
    IN To_User_Id_ INT,
    IN Branch_Id_ INT,
    IN Department_Id_ INT,
    IN Enquiry_For_Id_ INT
)
BEGIN
DECLARE SubUser_Condition LONGTEXT DEFAULT '';
DECLARE SearchbyName_Value LONGTEXT DEFAULT '';
DECLARE Search_Date_Follow_ LONGTEXT DEFAULT '';
/* Sub User Condition */
SET SubUser_Condition = CONCAT(
" AND (student.By_User_Id = ",Login_User_Id_,
" OR To_User_Id IN (
SELECT User_Selection_Id 
FROM sub_users 
WHERE User_Id = ",Login_User_Id_,
" AND DeleteStatus = 0 )) "
);
/* Optional Filters */
IF To_User_Id_ > 0 THEN
SET SearchbyName_Value = CONCAT(SearchbyName_Value,
" AND To_User_Id = ",To_User_Id_);
END IF;
IF Department_Id_ > 0 THEN
SET SearchbyName_Value = CONCAT(SearchbyName_Value,
" AND Followup_Department_Id = ",Department_Id_);
END IF;
IF Branch_Id_ > 0 THEN
SET SearchbyName_Value = CONCAT(SearchbyName_Value,
" AND student.Followup_Branch_Id = ",Branch_Id_);
END IF;
IF Enquiry_For_Id_ > 0 THEN
SET SearchbyName_Value = CONCAT(SearchbyName_Value,
" AND Enquiryfor_Id = ",Enquiry_For_Id_);
END IF;
/* Date Condition */
IF Is_Date_ > 0 THEN
SET Search_Date_Follow_ = CONCAT(
" AND DATE(student.Next_FollowUp_Date) BETWEEN '",
From_Date_,"' AND '",To_Date_,"'"
);
ELSE
SET Search_Date_Follow_ = "";
END IF;
/* Dynamic Date Columns */
SET SESSION group_concat_max_len = 1000000;
SET @sql = NULL;
SET @date_sql = CONCAT("
SELECT GROUP_CONCAT(
DISTINCT CONCAT(
'SUM(CASE WHEN DATE(Next_FollowUp_Date) = ''',
DATE(Next_FollowUp_Date),
''' THEN 1 ELSE 0 END) AS `',
DATE_FORMAT(Next_FollowUp_Date,'%d-%m-%Y'),
'`')
ORDER BY DATE(Next_FollowUp_Date)
) INTO @sql
FROM student
WHERE DeleteStatus = 0 ",
SubUser_Condition,
SearchbyName_Value,
Search_Date_Follow_);
PREPARE stmt FROM @date_sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;
/* Final Query */
SET @final_sql = CONCAT("
SELECT 
To_User_Name HandledBy,
Enquirfor_Name Enquiryfor,
Followup_Department_Name Channel,
Followup_Branch_Name Branch_Name,
",@sql,"
FROM student
WHERE student.DeleteStatus = 0 ",
SubUser_Condition,
SearchbyName_Value,
Search_Date_Follow_,"
GROUP BY
To_User_Name,
Enquirfor_Name,
Followup_Department_Name,
Followup_Branch_Name
ORDER BY student.To_User_Name ASC
");
PREPARE stmt FROM @final_sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;
END$$
DELIMITER ;

DELIMITER $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `Search_Enquiryfor_Wise_Report`(
    IN Login_User_Id_ INT,
    IN Is_Date_ INT,
    IN From_Date_ VARCHAR(20),
    IN To_Date_ VARCHAR(20),
    IN To_User_Id_ INT,
    IN Branch_Id_ INT,
    IN Department_Id_ INT,
    IN Enquiry_For_Id_ INT,
    Inc_Create_Date_ tinyint
)
BEGIN

DECLARE SubUser_Condition LONGTEXT DEFAULT '';
DECLARE SearchbyName_Value LONGTEXT DEFAULT '';
DECLARE Search_Date_Follow_ LONGTEXT DEFAULT '';
declare Filter_Create_Date longtext;
set Filter_Create_Date='';
/* Sub User Condition */

SET SubUser_Condition = CONCAT(
" AND (By_User_Id = ",Login_User_Id_,
" OR To_User_Id IN (
SELECT User_Selection_Id 
FROM sub_users 
WHERE User_Id = ",Login_User_Id_,
" AND DeleteStatus = 0 )) "
);

/* Optional Filters */

IF To_User_Id_ > 0 THEN
SET SearchbyName_Value = CONCAT(SearchbyName_Value,
" AND To_User_Id = ",To_User_Id_);
END IF;

IF Department_Id_ > 0 THEN
SET SearchbyName_Value = CONCAT(SearchbyName_Value,
" AND Followup_Department_Id = ",Department_Id_);
END IF;

IF Branch_Id_ > 0 THEN
SET SearchbyName_Value = CONCAT(SearchbyName_Value,
" AND Followup_Branch_Id = ",Branch_Id_);
END IF;

IF Enquiry_For_Id_ > 0 THEN
SET SearchbyName_Value = CONCAT(SearchbyName_Value,
" AND Enquiryfor_Id = ",Enquiry_For_Id_);
END IF;

/* Date Condition */

IF Is_Date_ > 0 THEN
SET Search_Date_Follow_ = CONCAT(
" AND DATE(Next_FollowUp_Date) BETWEEN '",
From_Date_,"' AND '",To_Date_,"'"
);
ELSE
SET Search_Date_Follow_ = "";
END IF;
	IF Inc_Create_Date_ > 0 THEN
			SET Filter_Create_Date = CONCAT(
			" AND DATE(Created_On) =",now(), "and DATE(Entry_date)<>DATE(Created_On) "
			);
			ELSE
			SET Filter_Create_Date = 1=1;
			END IF;


/* Dynamic Date Columns */

SET SESSION group_concat_max_len = 1000000;
SET @sql = NULL;

SET @date_sql = CONCAT("
SELECT GROUP_CONCAT(
DISTINCT CONCAT(
'SUM(CASE WHEN DATE(Next_FollowUp_Date) = ''',
DATE(Next_FollowUp_Date),
''' THEN 1 ELSE 0 END) AS `',
DATE_FORMAT(Next_FollowUp_Date,'%d-%m-%Y'),
'`'
)
ORDER BY DATE(Next_FollowUp_Date)
) INTO @sql
FROM student
WHERE student.DeleteStatus = 0 ",
SubUser_Condition,
SearchbyName_Value,
Search_Date_Follow_);

PREPARE stmt FROM @date_sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

/* NULL Fix */

SET @sql = IFNULL(@sql,'0 AS No_Data');

/* Final Query */

SET @final_sql = CONCAT("
SELECT 
To_User_Name AS HandledBy,
Enquirfor_Name Enquiryfor,
Followup_Department_Name AS Channel,
Followup_Branch_Name AS Branch_Name,
",@sql,",
COUNT(*) AS Total
FROM student
WHERE DeleteStatus = 0 ",
SubUser_Condition,
SearchbyName_Value,
Search_Date_Follow_,"
GROUP BY 
To_User_Name,
Enquirfor_Name,
Followup_Department_Name,
Followup_Branch_Name
ORDER BY To_User_Name ASC
");

PREPARE stmt FROM @final_sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

END$$
DELIMITER ;

