DELIMITER $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `Search_Overall_Report`(
    IN Fromdate_ DATE,
    IN Todate_ DATE,
    IN Search_By_ INT,
    IN SearchbyName_ VARCHAR(50),
    IN Department_ INT,
    IN Enquiry_Source_ INT,
    IN Branch_ INT,
    IN By_User_ INT,
    IN Is_Date_Check_ TINYINT,
    IN Is_Old_Datas_ TINYINT,
    IN Page_Index1_ INT,
    IN Page_Index2_ INT,
    IN Login_User_Id_ INT,
    IN RowCount int,
    IN RowCount2 int,
    IN remarks_ INT,
    IN To_User_ INT,
    IN Status_Id_ INT,
    IN Register_Value int,
    IN Date_value_ INT,
    IN Country_id_ INT,
    IN Course_Id_ INT,
    IN Enquiry_For_ INT,
    IN Location_Name_ varchar(500)
)
BEGIN

    DECLARE Filter_SQL LONGTEXT DEFAULT '';
    DECLARE Date_SQL   VARCHAR(1000) DEFAULT '';
    DECLARE Final_SQL  LONGTEXT;
    declare PageSize int;
    set PageSize=50;
	set Final_SQL="";
    /* ---------------- SEARCH BY NAME ---------------- */
    IF SearchbyName_ <> '0' THEN
        IF Search_By_ = 1 THEN
            SET Filter_SQL = CONCAT(Filter_SQL,
                " AND s.Student_Name LIKE '%", SearchbyName_, "%'");
        ELSEIF Search_By_ = 2 THEN
            SET Filter_SQL = CONCAT(Filter_SQL,
                " AND s.Email LIKE '%", SearchbyName_, "%'");
        ELSEIF Search_By_ = 3 THEN
            SET Filter_SQL = CONCAT(Filter_SQL,
                " AND s.Phone_Number LIKE '%", SearchbyName_, "%'");
        END IF;
    END IF;
    IF Department_ > 0 THEN
        SET Filter_SQL = CONCAT(Filter_SQL,
            " AND s.Followup_Department_Id = ", Department_);
    END IF;
    IF Enquiry_Source_ > 0 THEN
        SET Filter_SQL = CONCAT(Filter_SQL,
            " AND s.Enquiry_Source_Id = ", Enquiry_Source_);
    END IF;
    IF Enquiry_For_ > 0 THEN
        SET Filter_SQL = CONCAT(Filter_SQL,
            " AND s.Enquiryfor_Id = ", Enquiry_For_);
    END IF;
    IF Status_Id_ > 0 THEN
        SET Filter_SQL = CONCAT(Filter_SQL,
            " AND s.Status_Id = ", Status_Id_);
    END IF;
    IF Branch_ > 0 THEN
        SET Filter_SQL = CONCAT(Filter_SQL,
            " AND s.Followup_Branch_Id = ", Branch_);
    END IF;
    IF By_User_ > 0 THEN
        SET Filter_SQL = CONCAT(Filter_SQL,
            " AND s.Created_By = ", By_User_);
    END IF;
    IF To_User_ > 0 THEN
        SET Filter_SQL = CONCAT(Filter_SQL,
            " AND s.To_User_Id = ", To_User_);
    END IF;
    IF remarks_ > 0 THEN
        SET Filter_SQL = CONCAT(Filter_SQL,
            " AND s.Remark_Id = ", remarks_);
    END IF;
    IF Country_id_ > 0 THEN
        SET Filter_SQL = CONCAT(Filter_SQL,
            " AND s.Profile_Country_Id = ", Country_id_);
    END IF;
    IF Course_Id_ > 0 THEN
        SET Filter_SQL = CONCAT(Filter_SQL,
            " AND s.Program_Course_Id = ", Course_Id_);
    END IF;
    SET Filter_SQL = CONCAT(Filter_SQL,
        " AND (s.By_User_Id = ", Login_User_Id_,
        " OR s.To_User_Id IN (
            SELECT User_Selection_Id
            FROM sub_users
            WHERE User_Id = ", Login_User_Id_, "))");  
            
    /*IF Is_Date_Check_ = 1 THEN
        IF Date_value_ = 1 THEN
            SET Date_SQL = CONCAT(
                " AND date(s.Next_FollowUp_Date) BETWEEN '",
                Fromdate_, "' AND '", Todate_, "'");
        ELSE
            SET Date_SQL = CONCAT(
                " AND date(s.Entry_date) BETWEEN '",
                Fromdate_, "' AND '", Todate_, "'");
        END IF;
    END IF;*/
    
	if Is_Date_Check_=true then
		if Date_value_=4 then
			set Date_SQL=concat( Date_SQL," and date(s.Created_On) >= '", Fromdate_ ,"' and  date(s.Created_On) <= '", Todate_,"'");
		elseif Date_value_=3 then
			set Date_SQL=concat( Date_SQL," and date(s.Transfer_Date) >= '", Fromdate_ ,"' and  date(s.Transfer_Date) <= '", Todate_,"'");
		elseif Date_value_=2 then
			set Date_SQL=concat( Date_SQL," and date(s.Entry_date) >= '", Fromdate_ ,"' and  date(s.Entry_date) <= '", Todate_,"'");
		elseif Date_value_=1 then
			set Date_SQL=concat( Date_SQL," and date(s.FollowUp_Entrydate) >= '", Fromdate_ ,"' and  date(s.FollowUp_Entrydate) <= '", Todate_,"'");
		end if;		
	ELSE
		set Date_SQL= "and 1 =1 ";
	end if;
    
	IF Location_Name_ !='Select' THEN
     SET Filter_SQL = CONCAT(Filter_SQL,
                " AND s.Location_Name LIKE '%", Location_Name_, "%'");
    end if;
    
     SET @query = CONCAT(" select * from(
      select CAST(CAST(1 AS UNSIGNED) AS SIGNED)as tp,
    s.Student_Id Lead_Id,
     (Date_Format(s.Entry_date,'%d-%m-%Y   %h:%i')) As Entry_date,
                (Date_Format(s.Created_On,'%d-%m-%Y   %h:%i')) As Created_On,
                s.Created_User As Created_By,
                s.Student_Name Lead_Name,
                 s.Enquiry_No,
                   s.Enquirfor_Name as Enquiryfor_Name,
                   s.Phone_Number Mobile,
                    s.Whatsapp  UTM_Parameter,
                    s.Followup_Branch_Name Branch,
                s.Enquiry_Source_Name AS Enquiry_Source,    
                 s.Brand_Name,
                  s.Country_Name Model,
                  s.Programme_Course Enquiry_Status,
                  (Date_Format(s.Transfer_Date,'%d-%m-%Y')) As Tranfered_On,
                  s.Proceeding_Intake_Name DSE,
                  s.Address2 DSE_Update,
                  s.Location_Name,                   
                 s.Address1 Customer_Location,
                  s.Proceeding_University_Name Booked_Vehicle,
                   s.Previous_Visa_Rejection LostorDropReason,
                   s.Spouse_visa_Name Test_Drive,
                (Date_Format(s.Next_FollowUp_Date,'%d-%m-%Y')) As Follow_Up_On,
                s.Followup_Department_Name Channel,
                s.Department_Status_Name Chnanel_Status,
                s.To_User_Name Handled_By,                
                s.Remark,  
				s.Alternative_Phone_Number,
                s.Lead_Id as Lead_No,
	/* ---------- ATTEMPT 1 ---------- */
	CASE WHEN COUNT(f.Student_FollowUp_Id) >= 1 THEN
