DELIMITER $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `Search_Overall_Report_New`(
    IN Fromdate_ DATE,
    IN Todate_ DATE,
    IN Search_By_ INT,
    IN SearchbyName_ VARCHAR(50),
    IN Department_ INT,
    IN Enquiry_Source_ INT,
    IN Branch_ INT,
    IN By_User_ INT,
    IN Is_Date_Check_ TINYINT,
    IN Is_Old_Datas_ TINYINT,
    IN Page_Index1_ INT,
    IN Page_Index2_ INT,
    IN Login_User_Id_ INT,
    IN RowCount int,
    IN RowCount2 int,
    IN remarks_ INT,
    IN To_User_ INT,
    IN Status_Id_ INT,
    IN Register_Value int,
    IN Date_value_ INT,
    IN Country_id_ INT,
    IN Course_Id_ INT,
    IN Enquiry_For_ INT
)
BEGIN

    DECLARE Filter_SQL LONGTEXT DEFAULT '';
    DECLARE Date_SQL   VARCHAR(1000) DEFAULT '';
    DECLARE Final_SQL  LONGTEXT;
	set Final_SQL="";
    /* ---------------- SEARCH BY NAME ---------------- */
    IF SearchbyName_ <> '0' THEN
        IF Search_By_ = 1 THEN
            SET Filter_SQL = CONCAT(Filter_SQL,
                " AND s.Student_Name LIKE '%", SearchbyName_, "%'");
        ELSEIF Search_By_ = 2 THEN
            SET Filter_SQL = CONCAT(Filter_SQL,
                " AND s.Email LIKE '%", SearchbyName_, "%'");
        ELSEIF Search_By_ = 3 THEN
            SET Filter_SQL = CONCAT(Filter_SQL,
                " AND s.Phone_Number LIKE '%", SearchbyName_, "%'");
        END IF;
    END IF;

    /* ---------------- FILTERS ---------------- */
    IF Department_ > 0 THEN
        SET Filter_SQL = CONCAT(Filter_SQL,
            " AND s.Followup_Department_Id = ", Department_);
    END IF;

    IF Enquiry_Source_ > 0 THEN
        SET Filter_SQL = CONCAT(Filter_SQL,
            " AND s.Enquiry_Source_Id = ", Enquiry_Source_);
    END IF;

    IF Enquiry_For_ > 0 THEN
        SET Filter_SQL = CONCAT(Filter_SQL,
            " AND s.Enquiryfor_Id = ", Enquiry_For_);
    END IF;

    IF Status_Id_ > 0 THEN
        SET Filter_SQL = CONCAT(Filter_SQL,
            " AND s.Status_Id = ", Status_Id_);
    END IF;

    IF Branch_ > 0 THEN
        SET Filter_SQL = CONCAT(Filter_SQL,
            " AND s.Followup_Branch_Id = ", Branch_);
    END IF;

    IF By_User_ > 0 THEN
        SET Filter_SQL = CONCAT(Filter_SQL,
            " AND s.Created_By = ", By_User_);
    END IF;

    IF To_User_ > 0 THEN
        SET Filter_SQL = CONCAT(Filter_SQL,
            " AND s.To_User_Id = ", To_User_);
    END IF;

    IF remarks_ > 0 THEN
        SET Filter_SQL = CONCAT(Filter_SQL,
            " AND s.Remark_Id = ", remarks_);
    END IF;

    IF Country_id_ > 0 THEN
        SET Filter_SQL = CONCAT(Filter_SQL,
            " AND s.Profile_Country_Id = ", Country_id_);
    END IF;

    IF Course_Id_ > 0 THEN
        SET Filter_SQL = CONCAT(Filter_SQL,
            " AND s.Program_Course_Id = ", Course_Id_);
    END IF;

    /* ---------------- USER ACCESS ---------------- */
    SET Filter_SQL = CONCAT(Filter_SQL,
        " AND (s.By_User_Id = ", Login_User_Id_,
        " OR s.To_User_Id IN (
            SELECT User_Selection_Id
            FROM sub_users
            WHERE User_Id = ", Login_User_Id_, "))");

    /* ---------------- DATE FILTER ---------------- */
    IF Is_Date_Check_ = 1 THEN
        IF Date_value_ = 1 THEN
            SET Date_SQL = CONCAT(
                " AND s.Next_FollowUp_Date BETWEEN '",
                Fromdate_, "' AND '", Todate_, "'");
        ELSE
            SET Date_SQL = CONCAT(
                " AND s.Entry_date BETWEEN '",
                Fromdate_, "' AND '", Todate_, "'");
        END IF;
    END IF;

    /* ---------------- FINAL QUERY ---------------- */
    SET @query = CONCAT("
       SELECT
    s.Student_Id AS Lead_Id,
    DATE_FORMAT(s.Created_On,'%d-%m-%Y %h:%i') AS Created_On,
    s.Created_User AS Created_By,
    s.Student_Name AS Lead_Name,
    s.Enquiry_No,
    s.Phone_Number AS Mobile,
    s.Whatsapp,
    s.Followup_Branch_Name AS Branch,
    s.Enquiry_Source_Name,
    s.Brand_Name,
    s.Country_Name,
    s.Programme_Course,
    s.To_User_Name AS Handled_By,
    s.Remark,

	/* ---------- ATTEMPT 1 ---------- */
	CASE WHEN COUNT(f.Student_FollowUp_Id) >= 1 THEN
	SUBSTRING_INDEX(SUBSTRING_INDEX(GROUP_CONCAT(DATE_FORMAT(f.Next_FollowUp_Date,'%d-%m-%Y')
	ORDER BY f.Student_FollowUp_Id), ',', 1), ',', -1)
	END AS Attempt_1_Date,

	CASE WHEN COUNT(f.Student_FollowUp_Id) >= 1 THEN
	SUBSTRING_INDEX(SUBSTRING_INDEX(GROUP_CONCAT(f.Remark
	ORDER BY f.Student_FollowUp_Id), ',', 1), ',', -1)
	END AS Attempt_1_Remark,

	/* ---------- ATTEMPT 2 ---------- */
	CASE WHEN COUNT(f.Student_FollowUp_Id) >= 2 THEN
	SUBSTRING_INDEX(SUBSTRING_INDEX(GROUP_CONCAT(DATE_FORMAT(f.Next_FollowUp_Date,'%d-%m-%Y')
	ORDER BY f.Student_FollowUp_Id), ',', 2), ',', -1)
	END AS Attempt_2_Date,

	CASE WHEN COUNT(f.Student_FollowUp_Id) >= 2 THEN
	SUBSTRING_INDEX(SUBSTRING_INDEX(GROUP_CONCAT(f.Remark
	ORDER BY f.Student_FollowUp_Id), ',', 2), ',', -1)
	END AS Attempt_2_Remark,

	/* ---------- ATTEMPT 3 ---------- */
