	END AS Attempt_3_Remark,

	/* ---------- ATTEMPT 4 ---------- */
	CASE WHEN COUNT(f.Student_FollowUp_Id) >= 4 THEN
	SUBSTRING_INDEX(SUBSTRING_INDEX(GROUP_CONCAT(DATE_FORMAT(f.Next_FollowUp_Date,'%d-%m-%Y')
	ORDER BY f.Student_FollowUp_Id), ',', 4), ',', -1)
