	END AS Attempt_8_Date,

	CASE WHEN COUNT(f.Student_FollowUp_Id) >= 8 THEN
	SUBSTRING_INDEX(SUBSTRING_INDEX(GROUP_CONCAT(f.Remark
	ORDER BY f.Student_FollowUp_Id), ',', 8), ',', -1)
	END AS Attempt_8_Remark,

	/* ---------- ATTEMPT 9 ---------- */
	CASE WHEN COUNT(f.Student_FollowUp_Id) >= 9 THEN
	SUBSTRING_INDEX(SUBSTRING_INDEX(GROUP_CONCAT(DATE_FORMAT(f.Next_FollowUp_Date,'%d-%m-%Y')
	ORDER BY f.Student_FollowUp_Id), ',', 9), ',', -1)
	END AS Attempt_9_Date,

	CASE WHEN COUNT(f.Student_FollowUp_Id) >= 9 THEN
	SUBSTRING_INDEX(SUBSTRING_INDEX(GROUP_CONCAT(f.Remark
	ORDER BY f.Student_FollowUp_Id), ',', 9), ',', -1)
	END AS Attempt_9_Remark,

	/* ---------- ATTEMPT 10 ---------- */
	CASE WHEN COUNT(f.Student_FollowUp_Id) >= 10 THEN
	SUBSTRING_INDEX(SUBSTRING_INDEX(GROUP_CONCAT(DATE_FORMAT(f.Next_FollowUp_Date,'%d-%m-%Y')
	ORDER BY f.Student_FollowUp_Id), ',', 10), ',', -1)
	END AS Attempt_10_Date,

	CASE WHEN COUNT(f.Student_FollowUp_Id) >= 10 THEN
	SUBSTRING_INDEX(SUBSTRING_INDEX(GROUP_CONCAT(f.Remark
	ORDER BY f.Student_FollowUp_Id), ',', 10), ',', -1)
	END AS Attempt_10_Remark,

	/* ---------- ATTEMPT 11 ---------- */
	CASE WHEN COUNT(f.Student_FollowUp_Id) >= 11 THEN
	SUBSTRING_INDEX(SUBSTRING_INDEX(GROUP_CONCAT(DATE_FORMAT(f.Next_FollowUp_Date,'%d-%m-%Y')
	ORDER BY f.Student_FollowUp_Id), ',', 11), ',', -1)
	END AS Attempt_11_Date,

	CASE WHEN COUNT(f.Student_FollowUp_Id) >= 11 THEN
