DELIMITER $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `Search_Overall_Report_old`(In Fromdate_ date,Todate_ date,Search_By_ int,SearchbyName_ varchar(50),Department_ int,
Enquiry_Source_ int,Branch_ int,By_User_ int,Is_Date_Check_ Tinyint,Is_Old_Datas_ Tinyint,Page_Index1_ int,Page_Index2_ int,Login_User_Id_ int,RowCount int,
RowCount2 int,remarks_ int,To_User_ int,Status_Id_ int,Register_Value int,Date_value_ int,Country_id_ int,Course_Id_ int,Enquiry_For_ int)
BEGIN
    declare SearchbyName_Value varchar(2000);
    declare UnionQuery varchar(4000);
    declare Search_Date_ varchar(1000);
    declare Search_Old_Date_ varchar(1000);
    declare Search_Date_union varchar(500);
    declare pos1frm int;
    declare pos1to int;
    declare pos2frm int;
    declare RoleId_ varchar(100);
    declare Department_String_ varchar(4000);
    declare pos2to int;
    declare PageSize int;
   
    set pos1frm=0;    
    set pos1to=0;    
    set pos2frm=0;    
    set pos2to=0;    
    set PageSize=10;
    set SearchbyName_Value='',Department_String_='',Search_Date_union='',
    Search_Old_Date_='',Search_Date_='';set Search_Date_='',RoleId_='';
   
   # set RoleId_ =(select Role_String from user_details where User_Details_Id = Login_User_Id_);
    #set Department_String_ = (select Department_String from user_details where User_Details_Id = Login_User_Id_);
   
    if(SearchbyName_ !='0') then
        if Search_By_=1 then
            SET SearchbyName_Value = Concat(SearchbyName_Value," and student.Student_Name like '%",SearchbyName_ ,"%'") ;
        end if;
        if Search_By_=2 then
            SET SearchbyName_Value = Concat(SearchbyName_Value," and student.Email like '%",SearchbyName_ ,"%'") ;
        end if;
        if Search_By_=3 then
            SET SearchbyName_Value = Concat(SearchbyName_Value," and student.Phone_Number like '%",SearchbyName_ ,"%'") ;
        end if;
    end if;
   
    if Department_>0 then
        SET SearchbyName_Value =concat(SearchbyName_Value," and student.Followup_Department_Id =",Department_);
    end if;

    if Enquiry_Source_>0 then
        SET SearchbyName_Value =concat(SearchbyName_Value," and student.Enquiry_Source_Id =",Enquiry_Source_);
    end if;
    
    if Enquiry_For_>0 then
	SET SearchbyName_Value =concat(SearchbyName_Value," and student.Enquiryfor_Id =",Enquiry_For_);
	end if;
    
    if Status_Id_>0 then
        SET SearchbyName_Value =concat(SearchbyName_Value," and student.Status_Id =",Status_Id_);
    end if;
   
    if Branch_>0 then
        SET SearchbyName_Value =concat(SearchbyName_Value," and student.Followup_Branch_Id =",Branch_);
    end if;
   
    if By_User_>0 then
        SET SearchbyName_Value =concat(SearchbyName_Value," and student.Created_By =",By_User_);
    end if;
   
    if To_User_>0 then
        SET SearchbyName_Value =concat(SearchbyName_Value," and student.To_User_Id =",To_User_);
    end if;
   
   SET SearchbyName_Value =concat(SearchbyName_Value," and (student.By_User_Id=",Login_User_Id_," or student.To_User_Id in(select User_Selection_Id from sub_users where User_Id =",Login_User_Id_,"))");
     
    if remarks_ >0 then
        SET SearchbyName_Value =concat(SearchbyName_Value," and student.Remark_Id =",remarks_);
    end if;
   
    if Country_id_>0 then
        SET SearchbyName_Value =concat(SearchbyName_Value," and student.Profile_Country_Id =",Country_id_);
    end if;

    if Course_Id_>0 then
        SET SearchbyName_Value =concat(SearchbyName_Value," and student.Program_Course_Id =",Course_Id_);
    end if;

    if Is_Date_Check_=true then
        if Date_value_=2 then
            set Search_Date_=concat(SearchbyName_Value," and date(student.Entry_date) >= '", Fromdate_ ,"' and  date(student.Entry_date) <= '", Todate_,"'");
        elseif Date_value_=1 then
            set Search_Date_=concat(SearchbyName_Value," and date(student.Next_FollowUp_date) >= '", Fromdate_ ,"' and  date(student.Next_FollowUp_date) <= '", Todate_,"'");
        end if;
    ELSE
        set Search_Date_= "and 1 =1 ";
    end if;

  set UnionQuery="";   
    SET @query = Concat("
        select 
            student.Student_Id Lead_Id,
                (Date_Format(student.Created_On,'%d-%m-%Y   %h:%i')) As Created_On,
                student.Created_User As Created_By,
                student.Student_Name Lead_Name,
                 student.Enquiry_No,
                   student.Enquirfor_Name,
                   student.Phone_Number Mobile,
                    student.Whatsapp  UTM_Parameter,
                    student.Followup_Branch_Name Branch,
                student.Enquiry_Source_Name AS Enquiry_Source,    
                 student.Brand_Name,
                  student.Country_Name Model,
                  student.Programme_Course Enquiry_Status,
                  student.Proceeding_Intake_Name DSE,
                  student.Address2 DSE_Update,
                  student.Location_Name,                   
                 student.Address1 Customer_Location,
                  student.Proceeding_University_Name Booked_Vehicle,
                   student.Previous_Visa_Rejection LostorDropReason,
                   student.Spouse_visa_Name Test_Drive,
                (Date_Format(student.Next_FollowUp_Date,'%d-%m-%Y')) As Follow_Up_On,
                student.Followup_Department_Name Channel,
                student.Department_Status_Name Chnanel_Status,
                student.To_User_Name Handled_By,                
                student.Remark,               
                -- First Follow-up details
                (SELECT Date_Format(Next_FollowUp_Date,'%d-%m-%Y')
                 FROM student_followup
                 WHERE Student_Id = student.Student_Id
                 ORDER BY Student_FollowUp_Id ASC
                 LIMIT 1) AS Attempt_1_Date,
                (SELECT Remark
                 FROM student_followup
                 WHERE Student_Id = student.Student_Id
                 ORDER BY Student_FollowUp_Id ASC
                 LIMIT 1) AS Attempt_1_Remark,
                -- Second Follow-up details
                (SELECT Date_Format(Next_FollowUp_Date,'%d-%m-%Y')
