                 WHERE Student_Id = student.Student_Id
                 ORDER BY Student_FollowUp_Id ASC
                 LIMIT 8,1) AS Attempt_9_Remark,
                                  
                 -- tenth Follow-up details
                (SELECT Date_Format(Next_FollowUp_Date,'%d-%m-%Y')
