                 LIMIT 9,1) AS Attempt_10_Remark,                
                 
                   -- elevnth Follow-up details
                (SELECT Date_Format(Next_FollowUp_Date,'%d-%m-%Y')
                 FROM student_followup
                 WHERE Student_Id = student.Student_Id
                 ORDER BY Student_FollowUp_Id ASC
                 LIMIT 10,1) AS Attempt_11_Date,
                (SELECT Remark
                 FROM student_followup
                 WHERE Student_Id = student.Student_Id
                 ORDER BY Student_FollowUp_Id ASC
                 LIMIT 10,1) AS Attempt_11_Remark,
                 
                   -- twelveth Follow-up details
                (SELECT Date_Format(Next_FollowUp_Date,'%d-%m-%Y')
                 FROM student_followup
                 WHERE Student_Id = student.Student_Id
                 ORDER BY Student_FollowUp_Id ASC
                 LIMIT 11,1) AS Attempt_12_Date,
                (SELECT Remark
                 FROM student_followup
                 WHERE Student_Id = student.Student_Id
                 ORDER BY Student_FollowUp_Id ASC
                 LIMIT 11,1) AS Attempt_12_Remark,
                 
                   -- thirteenth Follow-up details
                (SELECT Date_Format(Next_FollowUp_Date,'%d-%m-%Y')
                 FROM student_followup
                 WHERE Student_Id = student.Student_Id
                 ORDER BY Student_FollowUp_Id ASC
                 LIMIT 12,1) AS Attempt_13_Date,
                (SELECT Remark
                 FROM student_followup
                 WHERE Student_Id = student.Student_Id
                 ORDER BY Student_FollowUp_Id ASC
                 LIMIT 12,1) AS Attempt_13_Remark,
                 
                  -- forteenth Follow-up details
                (SELECT Date_Format(Next_FollowUp_Date,'%d-%m-%Y')
