CREATE DEFINER=`root`@`localhost` PROCEDURE `Search_Payment`(In Fromdate_ date, Todate_ date,Login_User_Id_ int,Is_Date_Check_ tinyint,Branch_ int,Fees_Receipt_Status_ int)
BEGIN
declare Search_Date_ varchar(500);declare SearchbyName_Value varchar(2000);declare User_Type_ int;
