DELIMITER $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `Search_StatusWithAll_Report`(
    IN Login_User_Id_ INT,
    IN Is_Date_ INT,
    IN From_Date_ VARCHAR(20),
    IN To_Date_ VARCHAR(20),
    IN To_User_Id_ INT,
    IN Branch_Id_ INT,
    IN Department_Id_ INT,
    IN Status_Id_ INT,
    IN Enquiry_For_Id_ INT
)
BEGIN
DECLARE SubUser_Condition LONGTEXT DEFAULT '';
DECLARE SearchbyName_Value LONGTEXT DEFAULT '';
DECLARE Search_Date_Follow_ LONGTEXT DEFAULT '';
/* Sub User Condition */
SET SubUser_Condition = CONCAT(
" AND (student.By_User_Id = ",Login_User_Id_,
" OR student.To_User_Id IN (
SELECT User_Selection_Id 
FROM sub_users 
WHERE User_Id = ",Login_User_Id_,
" AND DeleteStatus = 0 )) "
);
/* Optional Filters */
IF To_User_Id_ > 0 THEN
SET SearchbyName_Value = CONCAT(SearchbyName_Value,
" AND student.To_User_Id = ",To_User_Id_);
END IF;
IF Department_Id_ > 0 THEN
SET SearchbyName_Value = CONCAT(SearchbyName_Value,
" AND student.Followup_Department_Id = ",Department_Id_);
END IF;
IF Branch_Id_ > 0 THEN
SET SearchbyName_Value = CONCAT(SearchbyName_Value,
" AND student.Followup_Branch_Id = ",Branch_Id_);
END IF;
IF Enquiry_For_Id_ > 0 THEN
SET SearchbyName_Value = CONCAT(SearchbyName_Value,
" AND student.Enquiryfor_Id = ",Enquiry_For_Id_);
END IF;
IF Status_Id_ > 0 THEN
SET SearchbyName_Value = CONCAT(SearchbyName_Value,
" AND student.Department_Status_Id = ",Status_Id_);
END IF;
/* Date Condition */
IF Is_Date_ > 0 THEN
SET Search_Date_Follow_ = CONCAT(
" AND DATE(student.Next_FollowUp_Date) BETWEEN '",
From_Date_,"' AND '",To_Date_,"'"
);
ELSE
SET Search_Date_Follow_ = "";
END IF;
/* Dynamic Date Columns */
SET SESSION group_concat_max_len = 1000000;
SET @sql = NULL;
SET @date_sql = CONCAT("
SELECT GROUP_CONCAT(
DISTINCT CONCAT(
'SUM(CASE WHEN DATE(Next_FollowUp_Date) = ''',
DATE(Next_FollowUp_Date),
''' THEN 1 ELSE 0 END) AS `',
DATE_FORMAT(Next_FollowUp_Date,'%d-%m-%Y'),
'`')
ORDER BY DATE(Next_FollowUp_Date)
) INTO @sql
FROM student
WHERE student.DeleteStatus = 0 ",
SubUser_Condition,
SearchbyName_Value,
Search_Date_Follow_);
PREPARE stmt FROM @date_sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;
/* Final Query */
SET @final_sql = CONCAT("
SELECT 
By_UserName ByUser,
To_User_Name TUser,
Department_Status_Name Status_Name,
Followup_Department_Name Department_Name,
Followup_Branch_Name Branch_Name,
Enquirfor_Name Enquiry_For,
Programme_Course  as Enquiry_Status,
Brand_Name,
Country_Name Model,
Proceeding_Intake_Name DSE,
Proceeding_University_Name Booked_Vehicle,
",@sql,"
FROM student
WHERE student.DeleteStatus = 0 ",
SubUser_Condition,
SearchbyName_Value,
Search_Date_Follow_,"
GROUP BY
By_UserName,
To_User_Name,
Department_Status_Name,
Followup_Department_Name,
Followup_Branch_Name,
Enquirfor_Name,
Programme_Course,
Brand_Name,
Country_Name,
Proceeding_Intake_Name,
Proceeding_University_Name
ORDER BY student.To_User_Name ASC
");
PREPARE stmt FROM @final_sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;
END$$
DELIMITER ;

