DELIMITER $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `Search_Student_Report`(In Fromdate_ date,Todate_ date,Search_By_ int,
SearchbyName_ varchar(50),Department_ int,Enquiry_Source_ int,Branch_ int,By_User_ int,Is_Date_Check_ Tinyint,Is_Old_Datas_ Tinyint,
Page_Index1_ int,Page_Index2_ int,Login_User_Id_ int,RowCount int ,RowCount2 int,remarks_ int,To_User_ int,Status_Id_ int,
Register_Value int,Date_value_ int,Country_id_ int,Course_Id_ int,Location_Name_ varchar(1000))
BEGIN
declare SearchbyName_Value varchar(2000);declare UnionQuery varchar(4000);declare Search_Date_ varchar(1000);declare Search_Old_Date_ varchar(1000);
declare Search_Date_union varchar(500);declare pos1frm int;declare pos1to int;declare pos2frm int;
declare RoleId_ varchar(100);declare Department_String_ varchar(4000);
declare pos2to int; declare PageSize int;
 set pos1frm=0;    set pos1to=0;    set pos2frm=0;    set pos2to=0;    set PageSize=10;
 set SearchbyName_Value='';
 set Search_Date_='',Search_Old_Date_='',Search_Date_union='',Department_String_='';
   set RoleId_ =(select Role_String from user_details where User_Details_Id = Login_User_Id_);
#set Department_String_ = (select Department_String from user_details where User_Details_Id = Login_User_Id_);
if(SearchbyName_ !='0') then
	if Search_By_=1 then
		SET SearchbyName_Value =   Concat( SearchbyName_Value," and student.Student_Name like '%",SearchbyName_ ,"%'") ;
	end if;
    if Search_By_=2 then
		SET SearchbyName_Value =   Concat( SearchbyName_Value," and student.Email like '%",SearchbyName_ ,"%'") ;
	end if;
    if Search_By_=3 then
		SET SearchbyName_Value =   Concat( SearchbyName_Value," and student.Phone_Number like '%",SearchbyName_ ,"%'") ;
	end if;
end if;
if Department_>0 then
	SET SearchbyName_Value =concat(SearchbyName_Value," and student.Followup_Department_Id =",Department_);
end if;

if Enquiry_Source_>0 then
	SET SearchbyName_Value =concat(SearchbyName_Value," and student.Enquiry_Source_Id =",Enquiry_Source_);
end if;

if Register_Value=2 then
Set SearchbyName_Value= Concat( SearchbyName_Value," and student.Is_Registered= ",1) ;
    elseif Register_Value=3 then
    Set SearchbyName_Value= Concat( SearchbyName_Value," and student.Is_Registered= ",0) ;
    end if;
if Status_Id_>0 then
SET SearchbyName_Value =concat(SearchbyName_Value," and student.Status_Id =",Status_Id_);
end if;
if Branch_>0 then
	SET SearchbyName_Value =concat(SearchbyName_Value," and student.Followup_Branch_Id =",Branch_);
end if;
if By_User_>0 then
	SET SearchbyName_Value =concat(SearchbyName_Value," and student.Created_By in(select User_Selection_Id from sub_users where User_Id =",By_User_,")");
end if;
if To_User_>0 then
	SET SearchbyName_Value =concat(SearchbyName_Value," and student.To_User_Id in(select User_Selection_Id from sub_users where User_Id =",To_User_,")");
end if;

if Login_User_Id_>0 then
	SET SearchbyName_Value =concat(SearchbyName_Value," and student.To_User_Id in(select User_Selection_Id from sub_users where User_Id =",Login_User_Id_,")");
end if;

if remarks_ >0 then
	SET SearchbyName_Value =concat(SearchbyName_Value," and student.Remark_Id =",remarks_);
end if;
if Country_id_>0 then
	SET SearchbyName_Value =concat(SearchbyName_Value," and student.Profile_Country_Id =",Country_id_);
end if;

if Course_Id_>0 then
	SET SearchbyName_Value =concat(SearchbyName_Value," and student.Program_Course_Id =",Course_Id_);
end if;

   IF Location_Name_ !='Select' THEN
     SET SearchbyName_Value = CONCAT(SearchbyName_Value,
                " AND student.Location_Name LIKE '%", Location_Name_, "%'");
    end if;

if Is_Date_Check_=true then
if Date_value_=4 then
		set Search_Date_=concat( SearchbyName_Value," and date(student.Created_On) >= '", Fromdate_ ,"' and  date(student.Created_On) <= '", Todate_,"'");
	elseif Date_value_=3 then
		set Search_Date_=concat( SearchbyName_Value," and date(student.Transfer_Date) >= '", Fromdate_ ,"' and  date(student.Transfer_Date) <= '", Todate_,"'");
	elseif Date_value_=2 then
		set Search_Date_=concat( SearchbyName_Value," and date(student.Entry_date) >= '", Fromdate_ ,"' and  date(student.Entry_date) <= '", Todate_,"'");
	elseif Date_value_=1 then
		set Search_Date_=concat( SearchbyName_Value," and date(student.FollowUp_Entrydate) >= '", Fromdate_ ,"' and  date(student.FollowUp_Entrydate) <= '", Todate_,"'");
	end if;		
ELSE
	set Search_Date_= "and 1 =1 ";
end if;

if Is_Old_Datas_=true then
	 set Search_Old_Date_= "and 1 =1 ";
	
ELSE
	#set Search_Old_Date_=concat( SearchbyName_Value," and date(student.Created_On) < '2022-09-30' ");
    set Search_Old_Date_=concat( SearchbyName_Value," and date(student.Created_On) >='2022-01-30' ");
   
end if;

set UnionQuery="";
SET @query = Concat( "select * from (select * from(select CAST(CAST(1 AS UNSIGNED) AS SIGNED)as tp,
CAST(CAST(ROW_NUMBER()OVER(ORDER BY student.Student_Id DESC)AS UNSIGNED)AS SIGNED)AS No,student.Student_Id,
(Date_Format(student.Created_On,'%d-%m-%Y   %h:%i')) As Created_On,user_details.User_Details_Name As Created_By,student.Student_Name Student,
enquiry_source.Enquiry_Source_Name AS Enquiry_Source,student.Is_Registered,student.Department_Status_Name,student.Location_Name,
(Date_Format(student.Transfer_Date,'%d-%m-%Y   %h:%i')) As Tranfered_On,(Date_Format(student.Entry_Date,'%d-%m-%Y   %h:%i')) As Entry_Date,
student.Phone_Number Mobile,Branch.Branch_Name Branch,(Date_Format(student.Next_FollowUp_Date,'%d-%m-%Y')) As Follow_Up_On,
Department.Department_Name Department_Name,student.Department_Status_Name Status,T.User_Details_Name To_Staff,B.User_Details_Name Registered_By,
(Date_Format(student.Registered_On,'%d-%m-%Y   %h:%i')) As Registered_On,student.Remark,student.Email,country.Country_Name,course.Course_Name
from student 
	inner join Department on Department.Department_Id= student.Followup_Department_Id  ",Department_String_," 
	left join user_details on user_details.User_Details_Id=student.Created_By 
	inner join Branch on Branch.Branch_Id= student.Followup_Branch_Id
	inner join enquiry_source on enquiry_source.Enquiry_Source_Id= student.Enquiry_Source_Id
	#inner join Department_Status on Department_Status.Department_Status_Id=student.Status_Id 
	inner join user_details as T on T.User_Details_Id=student.To_User_Id 
    left join country on country.Country_Id = student.Profile_Country_Id
    left join course on course.Course_Id = student.Program_Course_Id
	left join user_details as B on B.User_Details_Id=student.Registered_By 
	where student.DeleteStatus=0  ",SearchbyName_Value," ",Search_Date_," ",Search_Old_Date_," 
	)as lds )as ldtwo
	order by tp ");	 
PREPARE QUERY FROM @query;
#select @query;
insert into data_log_ value(0,@query,'Search_Student_Report');
EXECUTE QUERY;
END$$
DELIMITER ;

