DELIMITER $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `Search_User_Target_Retport`(
    IN Login_User_Id_ INT,
    IN To_User_Id_ INT,
    IN Branch_Id_ INT,
    IN Department_Id_ INT,
    IN user_Month_Id_ INT,
    IN Target_Year_ VARCHAR(10),
    IN Inc_Create_Date_ TINYINT)
BEGIN
DECLARE Filter_User_SQL LONGTEXT DEFAULT '';
DECLARE Filter_Student_SQL LONGTEXT DEFAULT '';
DECLARE Filter_To_SQL LONGTEXT DEFAULT '';
DECLARE Filter_branch_SQL LONGTEXT DEFAULT '';
DECLARE Filter_department_SQL LONGTEXT DEFAULT '';
DECLARE user_Month_SQL LONGTEXT DEFAULT '';
DECLARE Target_Year_sql LONGTEXT DEFAULT '';
DECLARE statement_sql LONGTEXT DEFAULT '';
DECLARE fromdate_ VARCHAR(20);
DECLARE todate_ VARCHAR(20);
declare monthlast_ int;
set monthlast_=(select Month_Count from  user_month where User_Month_Id = user_Month_Id_);
SET fromdate_ = DATE(CONCAT(Target_Year_,'-',user_Month_Id_,'-01'));
SET todate_ = LAST_DAY(CONCAT(Target_Year_,'-',user_Month_Id_,'-',monthlast_));

SET Filter_User_SQL = CONCAT(
" AND user_details.User_Details_Id IN 
 (SELECT User_Selection_Id FROM sub_users WHERE User_Id = ",Login_User_Id_,")"
);

SET Filter_Student_SQL = CONCAT(
" AND To_User_Id IN 
 (SELECT User_Selection_Id FROM sub_users WHERE User_Id = ",Login_User_Id_,")"
);

IF To_User_Id_ > 0 THEN
    SET Filter_To_SQL = CONCAT(" AND To_User_Id = ",To_User_Id_);
END IF;

IF Branch_Id_ > 0 THEN
    SET Filter_branch_SQL = CONCAT(" AND user_details.Branch_Id = ",Branch_Id_);
END IF;

IF Department_Id_ > 0 THEN
    SET Filter_department_SQL = CONCAT(" AND user_details.Department_Id = ",Department_Id_);
END IF;

IF user_Month_Id_ > 0 THEN
    SET user_Month_SQL = CONCAT(" AND t.user_Month_Id = ",user_Month_Id_);
END IF;

IF Target_Year_ <> '' THEN
    SET Target_Year_sql = CONCAT(" AND t.User_Target_Year = ",Target_Year_);
END IF;

IF Inc_Create_Date_ > 0 THEN
    SET statement_sql = CONCAT(
    " AND DATE(Create_On)=CURDATE() AND DATE(Entry_date)<>DATE(Create_On)");
END IF;
SET @query = CONCAT(
"SELECT 
    o.Branch_Name AS Branch,
    o.User_Details_Name AS Handled_By,
    o.Department_Name AS Channel,
    o.User_Taget_No AS Target,
    IFNULL(c.Booked_Lead,0) AS Booked,
    IFNULL(p.Saled_Lead,0) AS Retail,
    (IFNULL(c.Booked_Lead,0)+IFNULL(p.Saled_Lead,0)) AS Total,
    ROUND(((IFNULL(c.Booked_Lead,0)+IFNULL(p.Saled_Lead,0))/
    NULLIF(o.User_Taget_No,0))*100,2) AS Percentage
FROM
(
    SELECT 
        user_details.User_Details_Id,
        user_details.User_Details_Name,
        branch.Branch_Name,
        department.Department_Name,
        t.User_Taget_No
    FROM user_details
    INNER JOIN branch 
        ON branch.Branch_Id = user_details.Branch_Id
    INNER JOIN department
        ON department.Department_Id = user_details.Department_Id
    INNER JOIN user_target t
        ON user_details.User_Details_Id = t.User_Id
    WHERE user_details.DeleteStatus = 0
    ",Filter_branch_SQL,Filter_department_SQL,user_Month_SQL,Target_Year_sql,Filter_User_SQL,"

) o
LEFT JOIN
(
    SELECT 
        COUNT(Student_Id) AS Booked_Lead,
        To_User_Id

    FROM student

    WHERE DeleteStatus = 0
    AND Status_Id = 685
    AND DATE(Entry_date) >= '",fromdate_,"'
    AND DATE(Entry_date) <= '",todate_,"'
    ",Filter_Student_SQL,Filter_To_SQL,statement_sql,"

    GROUP BY To_User_Id

) c ON o.User_Details_Id = c.To_User_Id

LEFT JOIN
(
    SELECT 
        COUNT(Student_Id) AS Saled_Lead,
        To_User_Id

    FROM student

    WHERE  DeleteStatus = 0
    AND Status_Id = 686
    AND DATE(Entry_date) >= '",fromdate_,"'
    AND DATE(Entry_date) <= '",todate_,"'
    ",Filter_Student_SQL,Filter_To_SQL,statement_sql,"

    GROUP BY To_User_Id

) p ON o.User_Details_Id = p.To_User_Id

");

INSERT INTO data_log_ VALUES(0,@query,'');

PREPARE stmt FROM @query;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

END$$
DELIMITER ;

DELIMITER $$
