CREATE DEFINER=`root`@`localhost` PROCEDURE `Search_Work_Summary`(In Fromdate_ date,Login_User_Id_ int,Branch_ int)
BEGIN
declare SearchbyName_Value varchar(2000);declare Search_Date_ varchar(500);declare Search_Date_follow varchar(500);declare User_Type_ int;
declare UserFilter varchar(500);declare brachstring varchar(5000);declare brnchfolloup varchar(1000);declare Transfer_date varchar(1000);
set SearchbyName_Value='';set Search_Date_='';set brachstring='';set UserFilter='';set brnchfolloup='';set Transfer_date='';
 set User_Type_=(select User_Type from user_details where User_Details_Id=Login_User_Id_);
 if Branch_>0 then
SET brachstring =concat(brachstring," and Followup_Branch_Id =",Branch_);
SET brnchfolloup =concat(brnchfolloup," and Branch =",Branch_);
end if;
SET UserFilter = concat(" and user_details.User_Details_Id in (select User_Selection_Id from sub_users where User_Id = ", Login_User_Id_,")"); 

#if look_In_Date_Value=true thenend if;
set Search_Date_=concat( SearchbyName_Value," and date(Entry_Date) = '", Fromdate_ ,"'");
set Search_Date_follow=concat( SearchbyName_Value," and date(Next_FollowUp_date) = '", Fromdate_ ,"'");
set SearchbyName_Value=concat( SearchbyName_Value," and date(Next_FollowUp_date) < '", Fromdate_ ,"'");
set Transfer_date=concat( Transfer_date," and date(Transfer_Date) = '", Fromdate_ ,"'");
SET @query = Concat(" 
   SELECT 
   o.User_Details_Id,
    o.Branch_Id,
	o.User_Details_Name Handled_By,
    o.Department_Name Channel,
    o.Branch_Name Branch,    
	IFNULL(c.Today_Lead, 0) AS Today_Lead,
    IFNULL(p.Today_Followup, 0) AS Today_Followup,
    IFNULL(q.Pending_Followup, 0) AS Pending_Followup,     
    IFNULL(r.Interested_Lead, 0) AS Interested_Lead,
    IFNULL(s.Called_Leads, 0) AS Called_Leads
FROM 
   (select distinct User_Details_Id,User_Details_Name,Department_Name,branch.Branch_Id,branch.Branch_Name
   from user_details inner join student on user_details.User_Details_Id = student.To_User_Id inner join branch
   on student.Followup_Branch_Id=branch.Branch_Id
   WHERE user_details.DeleteStatus = 0 ", UserFilter,brachstring," )AS o
LEFT JOIN (
    SELECT ifnull(count(Student_Id),0) Today_Lead,To_User_Id,Followup_Branch_Id
    FROM student where FollowUp_Count in(0,1) and DeleteStatus=0 ",Search_Date_,brachstring,"
    GROUP BY To_User_Id,Followup_Branch_Id
) AS c ON o.User_Details_Id = c.To_User_Id and o.Branch_Id=c.Followup_Branch_Id
LEFT JOIN (
    select ifnull(count(Student_Id),0) Today_Followup,To_User_Id,Followup_Branch_Id
    FROM student  where FollowUp=1 and FollowUp_Count>1 and student.DeleteStatus=0 ",Search_Date_follow,brachstring,"
    GROUP BY To_User_Id,Followup_Branch_Id
) AS p ON o.User_Details_Id = p.To_User_Id and o.Branch_Id=p.Followup_Branch_Id
LEFT JOIN (
    SELECT ifnull(count(Student_Id),0) Pending_Followup,To_User_Id,Followup_Branch_Id
    FROM student where FollowUp=1 and FollowUp_Count>1 and student.DeleteStatus=0 ",SearchbyName_Value,brachstring,"
     GROUP BY To_User_Id,Followup_Branch_Id
) AS q ON o.User_Details_Id = q.To_User_Id and o.Branch_Id=q.Followup_Branch_Id
LEFT JOIN (
    SELECT ifnull(count(Student_Id),0) Interested_Lead,To_User_Id,Followup_Branch_Id
    FROM student where Program_Course_Id=13 and student.DeleteStatus=0 ",Transfer_date,brachstring,"
     GROUP BY To_User_Id,Followup_Branch_Id
) AS r ON o.User_Details_Id = r.To_User_Id and o.Branch_Id=r.Followup_Branch_Id

LEFT JOIN (
    SELECT ifnull(count(Student_Id),0) Called_Leads,User_Id,Branch
    FROM student_followup where student_followup.DeleteStatus=0 and student_followup.FollowUp_Count>1  ",Search_Date_,brnchfolloup,"
     GROUP BY User_Id,Branch
) AS s ON o.User_Details_Id = s.User_Id and o.Branch_Id=s.Branch
   ");
   insert into data_log_ value(0,@query,'Search_Work_Summary');
PREPARE QUERY FROM @query;
EXECUTE QUERY;
END$$
DELIMITER ;

