CREATE DEFINER=`root`@`localhost` PROCEDURE `Send_Selected_Students`(
##this sp is unwanted and added for just testing
    IN Students_IDS_ JSON
)
BEGIN
    DECLARE i INT DEFAULT 0;
    DECLARE total INT;

    CREATE TEMPORARY TABLE IF NOT EXISTS temp_selected_ids (
        Student_Id INT
    );

    TRUNCATE TABLE temp_selected_ids;

    SET total = JSON_LENGTH(Students_IDS_);

    WHILE i < total DO
        INSERT INTO temp_selected_ids (Student_Id)
        VALUES (CAST(JSON_EXTRACT(Students_IDS_, CONCAT('$[', i, ']')) AS UNSIGNED));
        SET i = i + 1;
    END WHILE;

    SELECT 
        s.Student_Id,
        s.Student_Name,
        s.Email,
        s.Phone_Number,
        s.Country_Name,
        s.Status_Id,
        s.To_User_Name,
        s.Created_On
    FROM student s
    INNER JOIN temp_selected_ids tsi ON s.Student_Id = tsi.Student_Id;

    DROP TEMPORARY TABLE IF EXISTS temp_selected_ids;
END$$
DELIMITER ;

