CREATE DEFINER=`root`@`localhost` PROCEDURE `Send_Visa_Email`()
BEGIN
    SELECT 
        student.Student_Id, 
        student.Student_Name, 
        student.Phone_Number, 
        user_details.Email AS User_Email
    FROM 
        student
    INNER JOIN 
        visa ON student.Student_Id = visa.Student_Id
    INNER JOIN 
        user_details ON student.To_User_Id = user_details.User_Details_Id
    WHERE 
        visa.Visa_Type_Id = '2' 
        AND visa.Visa_Granted = 0
        AND visa.Approved_Date + INTERVAL 14 DAY < CURDATE()
    UNION
    SELECT 
        student.Student_Id, 
        student.Student_Name, 
        student.Phone_Number, 
        user_details.Email AS User_Email
    FROM 
        student
    INNER JOIN 
        visa ON student.Student_Id = visa.Student_Id
    INNER JOIN 
        user_details ON student.To_User_Id = user_details.User_Details_Id
    WHERE 
        visa.Visa_Type_Id = '1' 
        AND visa.Visa_Granted = 0
        AND visa.Approved_Date + INTERVAL 7 DAY < CURDATE();
END$$
