CREATE DEFINER=`root`@`localhost` PROCEDURE `Statsuwise_repot`(
    IN dept_id_ INT,
    IN date_status_ TINYINT,
    IN from_date_ DATE,
    IN to_date_ DATE
)
BEGIN

    DECLARE column_list LONGTEXT;

    -- Increase GROUP_CONCAT limit
    SET SESSION group_concat_max_len = 1000000;

    -- Step 1: Generate dynamic status columns
    SELECT 
        GROUP_CONCAT(
            DISTINCT CONCAT(
                'COUNT(CASE WHEN sf.Dept_StatusName = ''',
                Dept_StatusName,
                ''' THEN sf.Student_FollowUp_Id END) AS `',
                Dept_StatusName, '`'
            )
            ORDER BY Dept_StatusName
        )
    INTO column_list
    FROM student_followup
    WHERE DeleteStatus = 0
      AND (date_status_ = 0 
           OR Next_FollowUp_Date BETWEEN from_date_ AND to_date_);

    IF column_list IS NULL THEN
        SET column_list = '0 AS `No Status`';
    END IF;

    -- Step 2: Build dynamic SQL
    SET @sql_query = CONCAT(
    'SELECT 
        u.User_Details_Name AS `User Name`, ',
        column_list,
    ' FROM user_details u
      LEFT JOIN student_followup sf 
        ON u.User_Details_Id = sf.User_Id
      WHERE u.DeleteStatus = 0
        AND (sf.DeleteStatus = 0 OR sf.DeleteStatus IS NULL)
        AND (', dept_id_, ' = 0 
             OR u.Department_Id = ', dept_id_, ')
        AND (', date_status_, ' = 0 
             OR sf.Next_FollowUp_Date BETWEEN ''', from_date_, ''' 
             AND ''', to_date_, ''')
      GROUP BY u.User_Details_Id, u.User_Details_Name
      ORDER BY u.User_Details_Name'
    );

    PREPARE stmt FROM @sql_query;
    EXECUTE stmt;
    DEALLOCATE PREPARE stmt;

END$$
DELIMITER ;

