CREATE DEFINER=`root`@`localhost` PROCEDURE `Student_Registration_Summary`(In Fromdate_ date,Todate_ date,  Branch_  int,Is_Date_Check_ Tinyint,Login_User_Id_ int,User_Id_Temp_ int)
BEGIN
declare Search_Date_ varchar(500);declare RoleId_ varchar(100);declare Department_String_ varchar(4000);DECLARE Search_by_type_ VARCHAR(200);
declare SearchbyName_Value varchar(2000);declare User_Type_ int;
set SearchbyName_Value='';set Search_by_type_ ='';
set Search_Date_='';
set RoleId_ =(select Role_String from user_details where User_Details_Id = Login_User_Id_);
set Department_String_ = (select Department_String from user_details where User_Details_Id = Login_User_Id_);
