#Department_String_ ","  and user_details.Role_Id in(",RoleId_,")
SET @query = Concat( "select  Registered_Branch Branch,user_details.User_Details_Name User,count(student.Student_Id) as No_of_Registration,
Registered_By User_Details_Id
from student
inner join user_details on user_details.User_Details_Id=student.Registered_By 
where student.DeleteStatus=0 and student.Is_Registered=1 and user_details.DeleteStatus=0",Search_Date_," ",SearchbyName_Value," 
and (student.Role_Id in(",RoleId_,")  ",Search_by_type_,")
group by Registered_Branch,user_details.User_Details_Name,Registered_By order by Registered_Branch,Registered_By");
insert into data_log_ value(0,@query,'Student_Registration_Summary');
PREPARE QUERY FROM @query;
#select @query;

EXECUTE QUERY;
END$$
